# and the project guards do not apply to them.
_RELEASE_CMDS: Tuple[str, ...] = ("channels", "deploy", "promote")

_TOP_DESCRIPTION = (
    "taxjson — capital gains, income and the superficial-loss / "
    "wash-sale rules from your broker exports, computed on your "
    "machine. `tjs` is the same program under a shorter name. Run with "
    "no command for this page; `COMMAND -h` explains one command. New "
    "here? docs/getting-started.md walks a first project through, "
    "missing purchase history included "
    "(github.com/taxjson/taxjson/blob/main/docs/getting-started.md).")

# The name the program was invoked as: `tjs` (the short console script)
# or `taxjson` (also for `python -m taxjson.bin.taxjson_run`). Set by
# main(); usage lines and error prefixes show it.
_PROG = "taxjson"


def _invoked_name(argv0: Optional[str] = None) -> str:
    """"tjs" when invoked through the `tjs` console script (tjs, tjs.exe,
    tjs-script.py on Windows), else "taxjson"."""
    import os
    name = os.path.basename(argv0 if argv0 is not None
                            else (sys.argv[0] if sys.argv else ""))
    stem = name.lower().split(".", 1)[0]
    return "tjs" if stem in ("tjs", "tjs-script") else "taxjson"


class _GroupedHelpParser(argparse.ArgumentParser):
    """The top-level parser: its help page lists the subcommands under
    _COMMAND_GROUPS' headings (argparse can only print one flat
    COMMAND list). Usage, description, options and epilog are argparse's
    own. A subcommand missing from the groups is still listed, under
    "Other commands", never hidden.

    Inside a project whose country is known (`help_country`), a command
    the OTHER country owns (lib/country.COMMAND_COUNTRY) is left out and
    a closing line counts them; `help --all` (`show_all`) lists every
    command. Outside a project, or with --all, a one-country command is
    marked "(Canada)" / "(USA)". Running a hidden command still gets the
    dispatcher's refusal naming why."""

    help_country: Optional[str] = None
    show_all: bool = False

    def format_help(self) -> str:
        import copy
        from taxjson.lib.country import COMMAND_COUNTRY

        def display_name(c: str) -> str:
            return {"canada": "Canada", "usa": "USA"}.get(c, c)
        formatter = self._get_formatter()
        formatter.add_usage(self.usage, self._actions,
                            self._mutually_exclusive_groups)
        formatter.add_text(self.description)
        subs = next((a for a in self._actions
                     if isinstance(a, argparse._SubParsersAction)), None)
        by_name = {}
        hidden = 0
        for a in getattr(subs, "_choices_actions", []):
            owner = COMMAND_COUNTRY.get(a.dest)
            if owner and self.help_country and not self.show_all \
                    and owner != self.help_country:
                hidden += 1
                continue
            if owner and (self.show_all or not self.help_country):
                a = copy.copy(a)
                a.help = f"({display_name(owner)}) {a.help or ''}"
            by_name[a.dest] = a
        placed = set()
        sections = []
        for title, names in _COMMAND_GROUPS:
            acts = [by_name[n] for n in names if n in by_name]
            placed.update(n for n in names if n in by_name)
            sections.append((title, acts))
        rest = [a for n, a in by_name.items() if n not in placed]
        if rest:
            sections.append(("Other commands", rest))
        for title, acts in sections:
            if not acts:
                continue
            formatter.start_section(title)
            formatter.add_arguments(acts)
            formatter.end_section()
        for group in self._action_groups:
            acts = [a for a in group._group_actions if a is not subs]
            if not acts:
                continue
            formatter.start_section(group.title)
            formatter.add_text(group.description)
            formatter.add_arguments(acts)
            formatter.end_section()
        formatter.add_text(self.epilog)
        if hidden:
            formatter.add_text(
                f"{hidden} command{'s' if hidden != 1 else ''} hidden for "
                f"{display_name(self.help_country)} — `{self.prog} help "
                f"--all` lists every command.")
        return formatter.format_help()


def _help_country(argv: List[str]) -> Optional[str]:
    """The country of the project the help page is shown for (-C/--dir,
    else the current directory): None outside a project or when its
    country is not set (lib/country's resolver, never a guess)."""
    from taxjson.lib.country import settings_country
    d = "."
    for i, tok in enumerate(argv):
        if tok in ("-C", "--dir") and i + 1 < len(argv):
            d = argv[i + 1]
        elif tok.startswith("--dir="):
            d = tok[len("--dir="):]
        elif tok.startswith("-C") and len(tok) > 2:
            d = tok[2:]
    root = Path(d)
    try:
        if not (root / "taxjson.toml").is_file():
            return None
        if not _legacy_free(root):
            # The command itself says why the project cannot run; the
            # help page needs only the country, read without the guards.
            cfg = tomllib.loads((root / "taxjson.toml").read_bytes()
                                .decode("utf-8-sig"))
            return settings_country(cfg.get("settings") or {})
        return settings_country(_soft_settings(root.resolve()))
    except (Exception, SystemExit):                     # noqa: BLE001
        # (SystemExit: a config the command itself refuses — e.g. a
        # crypto project with no local_timezone — still gets help.)
        return None


def _legacy_free(root: Path) -> bool:
    from taxjson.lib.migrate import legacy_files
    return not legacy_files(root)


def _no_command(argv: List[str], commands) -> bool:
    """True when argv names no command and holds nothing but -C/--dir
    DIR: `taxjson` or `taxjson -C DIR` alone prints the help page. Any
    other token (-h, --version, a mistyped command) keeps argparse's
    own handling."""
    i = 0
    while i < len(argv):
        tok = argv[i]
        if tok in ("-C", "--dir"):
            if i + 1 >= len(argv):
                return False            # argparse names the missing DIR
            i += 2
            continue
        if tok.startswith("--dir=") or (tok.startswith("-C")
                                         and len(tok) > 2):
            i += 1
            continue
        return False
    return not any(t in commands for t in argv)


def _child_error(stderr: Optional[str], limit: int = 400) -> str:
    """What a wrapper relays of a failed child's stderr: all of it when
    short, else its error line. A fixed-length PREFIX cut a traceback off
    before the exception line, so the actual error never showed (audit
    A2-1190). For a traceback: the lines before it plus its last line;
    otherwise the last lines, newest kept."""
    lines = [ln.rstrip() for ln in (stderr or "").strip().splitlines()
             if ln.strip()]
    if not lines:
        return "(no error output)"
    text = "\n".join(lines)
    if len(text) <= limit:
        return text
    tb = next((i for i, ln in enumerate(lines)
               if ln.startswith("Traceback (most recent call last)")), None)
    if tb is not None:
        keep = lines[:tb][-2:] + ["(traceback omitted) " + lines[-1]]
    else:
        keep = []
        for ln in reversed(lines):
            if keep and sum(len(k) for k in keep) + len(ln) > limit:
                break
            keep.insert(0, ln)
    return "\n".join(k if len(k) <= limit else k[:limit] + " …"
                     for k in keep)


def _cmd_prog() -> str:
    """`taxjson <command>` while a command runs (the prog of its
    messages), else `taxjson` (`tjs` when invoked so)."""
    return f"{_PROG} {_CURRENT_CMD}" if _CURRENT_CMD else _PROG


def _die(msg: str, *details: str) -> None:
    """Stop the command, exit 1: `taxjson <cmd>: error: <msg>`, then each
    of `details` as an indented paragraph (docs/output-style.md). Keep
    `msg` a short headline — what was refused, about what — and put the
    why and the fix in `details`. SystemExit carries the text, as
    sys.exit(msg) did."""
    from taxjson.lib.out import fail
    fail(msg, prog=_cmd_prog(), details=details, code=1)


def _die_input(msg: str, *details: str) -> None:
    """Like _die, with exit 2: a named input (or output) that is missing
    or cannot be read or written, or a usage error. Exit 1 stays the
    command's FINDING (drift, a handoff problem, PII found, a lint hit),
    so cron and the checklist can tell 'broken input' from 'finding' —
    the cli_diag convention every console script follows (re-audit
    A2-0164)."""
    from taxjson.lib.out import fail
    fail(msg, prog=_cmd_prog(), details=details, code=2)




def _estimate_deductions(root: Path, args) -> Tuple[float, float]:
    """(deductions, carrying_charges) for the Canada estimate: CLI
    flags win, else the [estimate] table, else zero. `deductions` are
    lines 20700-23500 the AMT allows in full (RRSP 20800, FHSA, RPP);
    `carrying_charges` is line 22100 (50% under the post-2024 AMT).
    other_income stays >= 0: deductions are their own input, not a
    negative income (R1-213)."""
    import math as _math
    _warn_config_tables(root)
    cfg = _soft_config(root).get("estimate") or {}
    out = []
    for key in ("deductions", "carrying_charges"):
        v = getattr(args, key, None)
        src = f"--{key.replace('_', '-')}"
        if v is None:
            v, src = cfg.get(key), f"[estimate] {key}"
        if isinstance(v, bool):
            _die(f"{src} must be a number, got {v!r}")
        try:
            f = float(v or 0.0)
        except (TypeError, ValueError):
            _die(f"{src} must be a number, got {v!r}")
        if not _math.isfinite(f) or f < 0:
            _die(f"{src} must be a non-negative finite number (the "
                 f"amount you deduct, as a positive figure), got {v!r}")
        out.append(f)
    return out[0], out[1]


def _estimate_lt_losses(root: Path, args) -> float:
    """The US long-term capital loss carryover (Schedule D line 14):
    --long-term-losses, else [estimate] long_term_losses, else 0
    (`--other-losses` is then the short-term carryover; tax-logic
    US-EST-CARRY-TERM, re-audit A2-0481 / A2-0809). Both are refused in
    a Canada project (lib/country FLAG_COUNTRY / CONFIG_COUNTRY)."""
    import math as _math
    v = getattr(args, "long_term_losses", None)
    src = "--long-term-losses"
    if v is None:
        cfg = _soft_config(root).get("estimate") or {}
        v, src = cfg.get("long_term_losses"), "[estimate] long_term_losses"
    if isinstance(v, bool):
        _die(f"{src} must be a number, got {v!r}")
    try:
        f = float(v or 0.0)
    except (TypeError, ValueError):
        _die(f"{src} must be a number, got {v!r}")
    if not _math.isfinite(f) or f < 0:
        _die(f"{src} must be a non-negative finite number (enter loss "
             f"carryovers as positive amounts), got {v!r}")
    return f


def _carry_inputs(root: Path, args, cfg: Dict[str, Any], ol: float,
                  ltl: float):
    """The carry-forwards the estimate uses (lib/carryforward):
    explicit input wins (--other-losses / --long-term-losses, their
    [estimate] keys; [estimate] amt_carryover),
    else the latest close-year lock before the project year. Returns
    (other_losses, lt_losses, amt_carryover_by_year | None, sources) —
    `sources` says where each figure came from (printed and in --json;
    tax-logic CA-CARRY-03, CA-AMT-08, US-CARRY-02)."""
    from taxjson.lib import carryforward as CF
    settings = cfg.get("settings") or {}
    country = _country(settings)
    est_cfg = cfg.get("estimate") or {}
    if not isinstance(est_cfg, dict):
        est_cfg = {}

    def _given(flag_attr: str, key: str) -> Optional[str]:
        if getattr(args, flag_attr, None) is not None:
            return "--" + flag_attr.replace("_", "-")
        if key in est_cfg:
            return f"[estimate] {key}"
        return None
    src: Dict[str, Any] = {
        "other_losses": _given("other_losses", "other_losses"),
        "long_term_losses": (_given("long_term_losses", "long_term_losses")
                             if country == "usa" else None),
        "amt_carryover": None, "notes": [],
        "other_income_entered": _given("other_income", "other_income")
        is not None,
        "other_income_value": None}
    explicit = bool(src["other_losses"] or src["long_term_losses"])
    try:
        lr = CF.resolve_losses(root, settings, country, explicit)
    except CF.CarryInputError as e:
        _die(str(e))
    if "other_losses" in lr:
        ol = float(lr["other_losses"])
        src["other_losses"] = lr["source"]
        if country == "usa":
            ltl = float(lr.get("lt_losses") or 0.0)
            src["long_term_losses"] = lr["source"]
        src["notes"] += lr["notes"]
    amt = None
    if country == "canada":
        try:
            a = CF.resolve_amt(root, settings, est_cfg)
        except CF.CarryInputError as e:
            _die(str(e))
        amt = a["by_year"]
        src["amt_carryover"] = a["source"]
        for n in a["notes"]:
            if n not in src["notes"]:
                src["notes"].append(n)
    return ol, ltl, amt, src


def _estimate_inputs(root: Path, args) -> Tuple[float, float]:
    """(other_income, other_losses) for the tax estimate: CLI flags
    win, else the [estimate] table, else zero. Shared by cmd_summary
    and cmd_instalments — `taxjson instalments` shells out to the
    estimate, and without a common resolution the two commands
    reported different net tax owing for anyone with employment
    income (5.5x on the auditor's fixture)."""
    _warn_config_tables(root)
    cfg = _soft_config(root).get("estimate") or {}
    import math as _math
    out = []
    for key in ("other_income", "other_losses"):
        v = getattr(args, key, None)
        src = f"--{key.replace('_', '-')}"
        if v is None:
            v, src = cfg.get(key), f"[estimate] {key}"
        # float(True) is 1.0: `other_income = true` was read as $1
        # (R1-217).
        if isinstance(v, bool):
            _die(f"{src} must be a number, got {v!r}")
        try:
            f = float(v or 0.0)
        except (TypeError, ValueError):
            _die(f"{src} must be a number, got {v!r}")
        # The ONE guard for flags and config alike (A2-1123: cmd_summary
        # kept a second copy this one masked): a NEGATIVE other_losses
        # (the "-10,000 carryover" sign trap) fabricates taxable gains,
        # and nan/inf poisons every downstream figure (REVIEW #25/#42).
        if not _math.isfinite(f) or f < 0:
            _die(f"{src} must be a non-negative finite number (enter "
                 f"loss carryovers as positive amounts), got {v!r}")
        out.append(f)
    oi_f, ol_f = out
    return oi_f, ol_f


# Every known [settings] key, and the country that owns it, lives in
# lib/country.SETTING_COUNTRY (one table for the config check, the
# commands and scripts/check_tax_rules.py).
from taxjson.lib.country import SETTING_COUNTRY as _SETTING_COUNTRY  # noqa: E402
_SETTINGS_KEYS = tuple(_SETTING_COUNTRY)
# [accounts.<name>] keys: lib/config_check.ACCOUNT_KEYS (_ACCOUNT_KEYS).


def _brokerage_account_flags(acfg: Dict[str, Any]) -> List[str]:
    """taxjson-brokerage flags an [accounts.<name>] table asks for:
    `combined_broker_accounts = true` (every broker account in the
    label's statements is the user's and taxable together — the
    'statement spans N accounts' ATTENTION becomes a NOTE; the parser
    refuses it on a sheltered label unless the statement shows one
    plan). config_check refuses a non-boolean value."""
    acfg = acfg or {}
    flags = (["--combined-broker-accounts"]
             if acfg.get("combined_broker_accounts") is True else [])
    # Webull's exercise/assignment charge: a broker convention the user
    # states (config_check checks the value; none: nothing inferred).
    if acfg.get("exercise_fee") is not None:
        flags += ["--exercise-fee", f"{float(acfg['exercise_fee']):g}"]
    # RBC's year-end posting day (default 06-30 in the parser).
    if acfg.get("year_end_posting") is not None:
        flags += ["--year-end-posting", str(acfg["year_end_posting"])]
    return flags
_ACCOUNT_TYPES = ("taxable", "sheltered")


def _fetch_brokerages(cfg: Dict[str, Any]) -> Tuple[str, ...]:
    """The `brokerage` values the installed fetcher plugins serve —
    () when no account declares one (no plugin scan) or none is
    installed."""
    from taxjson.lib import fetchers as _FP
    if not _FP.declared_brokerages(cfg):
        return ()
    return tuple(_FP.served_brokerages())


def _fetch_account_keys(cfg: Dict[str, Any]) -> Tuple[str, ...]:
    """Extra [accounts.<name>] keys the installed fetcher plugins
    declare (beyond brokerage / account / query_id, always accepted).
    Scanned only when an account declares a `brokerage`."""
    from taxjson.lib import fetchers as _FP
    if not _FP.declared_brokerages(cfg):
        return ()
    return tuple(k for f in _FP.installed() for k in f.account_keys)


def _fetch_plugin_note(cfg: Dict[str, Any]) -> Optional[str]:
    """One note when accounts declare a `brokerage` but no fetcher
    plugin is installed: the keys are accepted (they only matter to
    `taxjson fetch`), and the user learns how to get the command."""
    from taxjson.lib import fetchers as _FP
    declared = _FP.declared_brokerages(cfg)
    if not declared or _FP.installed():
        return None
    names = ", ".join(f"[accounts.{a}]" for a in declared)
    return (f"{names} brokerage is read only by `taxjson fetch`, and no "
            f"fetcher is installed — {_FP.INSTALL_HINT}")


def validate_config(cfg: Dict[str, Any],
                    inputs_dir: Optional[Path] = None) -> List[str]:
    """Schema-check taxjson.toml BEFORE any stage runs. Fatal problems
    sys.exit (they would otherwise surface minutes into a run, or worse,
    not at all — a typo'd account `type` matches neither partition and the
    account silently vanishes from the run while stale reports keep
    looking healthy). Unknown keys and populated-but-unconfigured input
    dirs come back as warnings for the caller to print."""
    import difflib

    def _suggest(key: str, valid: Tuple[str, ...]) -> str:
        close = difflib.get_close_matches(key, valid, n=1)
        return f" (did you mean {close[0]!r}?)" if close else ""

    warnings: List[str] = []
    settings = cfg.get("settings", {})
    for key in settings:
        if key not in _SETTINGS_KEYS:
            warnings.append(f"unknown [settings] key {key!r} is ignored"
                            f"{_suggest(key, _SETTINGS_KEYS)}")

    year = settings.get("year")
    if year is not None and not isinstance(year, int):
        _die(f"[settings] year must be an integer, got {year!r}")
    # Country (required), date basis, base currency, and every
    # setting/table the country does not own: the same check every
    # config reader applies (lib/config_check.settings_problems).
    from taxjson.lib.config_check import settings_problems
    _problems = settings_problems(cfg)
    if _problems:
        _die(_problems[0] if len(_problems) == 1 else
             "taxjson.toml:\n  " + "\n  ".join(_problems))
    settings = cfg["settings"]
    # tax_date against the country's practice: allowed (both countries
    # own the key) but said, once per run (partition INPUTS-05).
    from taxjson.lib.country import default_tax_date as _dtd
    _td, _c = settings.get("tax_date"), settings["country"]
    if _td is not None and _td != _dtd(_c):
        warnings.append(
            f"[settings] tax_date = \"{_td}\" in a {_c} project: "
            + ("the IRS dates a disposition by its TRADE date (the US "
               "default)" if _c == "usa" else
               "CRA practice dates a disposition by its SETTLEMENT date "
               "(the Canadian default)")
            + " — keep it only if you mean to depart from that")
    # option_premium_timing, option_grant_timing_since (1900..2100, as
    # S047-20 set) and option_buyback_loss_superficial are refused by
    # load_config (lib/config_check.bool_setting_problems, every config
    # reader) before this runs; the twin checks that stood here were
    # dead code no test could reach (audit A2-1211).
    _froc = settings.get("foreign_return_of_capital")
    if _froc is not None and _froc not in ("dividend", "acb"):
        _die(f"[settings] foreign_return_of_capital must be \"dividend\" or \"acb\" (got {_froc!r}).")
    _fs = settings.get("futures_settle")
    if _fs is not None and _fs not in ("trade", "next_day"):
        _die(f"[settings] futures_settle must be \"trade\" or \"next_day\" (got {_fs!r}).")
    try:
        _income_rules(settings)
    except ValueError as e:
        _die(str(e))
    if "cross_asset" in settings:
        # Each country's own rule (audit A2-1241, A2-1273): the US
        # engine only flags a long call (US-WASH-12).
        try:
            _ca_usa = _country(settings) == "usa"
        except SystemExit:
            _ca_usa = False
        warnings.append(
            "[settings] cross_asset is retired and ignored: "
            + ("a long call bought in a share loss's window is always "
               "flagged as a warning (§1091 'option to acquire'; the US "
               "engine does not deny on it); the identical option is a "
               "replacement for an option loss. Delete the line."
               if _ca_usa else
               "a long call on the same shares is always replacement "
               "property for a share loss (s.54 'a right to acquire'); "
               "shares never replace an option, and only the identical "
               "contract replaces an option. Delete the line."))
    src = settings.get("source_currencies")
    if src is not None and (not isinstance(src, list)
                            or not all(isinstance(c, str) for c in src)):
        _die(f"[settings] source_currencies must be a list of "
                 f"currency codes, got {src!r}")

    # Unknown top-level tables ([estimates]) and unknown [estimate] /
    # [instalments] keys — the same check the commands reading those
    # tables print (R1-216, R1-257, S038-13).
    warnings.extend(_config_table_warnings(cfg))
    accounts = cfg.get("accounts", {})
    for name, acfg in accounts.items():
        if not isinstance(acfg, dict):
            _die(f"[accounts.{name}] must be a table")
        for key in acfg:
            if key not in _ACCOUNT_KEYS \
                    and key not in _fetch_account_keys(cfg):
                warnings.append(f"unknown [accounts.{name}] key {key!r} is "
                                f"ignored{_suggest(key, _ACCOUNT_KEYS)}")
    # Missing / invalid `type`: fatal, and the SAME check every other
    # config reader applies (lib/config_check.py).
    _refuse_bad_account_types(cfg)
    for name, acfg in accounts.items():
        for flag in ("crypto", "transfers"):
            if flag in acfg and not isinstance(acfg[flag], bool):
                _die(f"[accounts.{name}] {flag} must be "
                         f"true/false, got {acfg[flag]!r}")
        _plan = acfg.get("plan")
        if _plan is not None and str(_plan).strip().lower() \
                not in _PLAN_KINDS:
            # Name and suggest only the project's own country's plans
            # (a US 'hsa' was offered Canada's 'fhsa'; A2-1272).
            try:
                _pk = _plan_kinds(_country(cfg.get("settings") or {}))
            except SystemExit:
                _pk = list(_PLAN_KINDS)
            warnings.append(
                f"[accounts.{name}] plan {_plan!r} is not a known plan "
                f"kind ({' | '.join(_pk)}) and is ignored"
                f"{_suggest(str(_plan).strip().lower(), _pk)}")
        elif _plan is not None and _ptype_conflict(acfg):
            warnings.append(
                f"[accounts.{name}] plan {str(_plan).strip().lower()!r} "
                f"contradicts type = {acfg.get('type')!r} — the type "
                f"decides how the account is taxed; fix one of them")
        brok = acfg.get("brokerage")
        _served = _fetch_brokerages(cfg)
        if brok is not None and _served and str(brok) not in _served:
            # Only the installed fetcher plugins know their brokerages
            # (lib/fetchers); with none installed the key is accepted
            # and cmd_run prints one note instead (_fetch_plugin_note).
            warnings.append(
                f"[accounts.{name}] brokerage {brok!r} is not a fetch "
                f"source ({' | '.join(_served)}) — `taxjson fetch` "
                f"will refuse it{_suggest(str(brok), _served)}")

    # CSVs in a SUBFOLDER of an account's inputs are never read (only
    # files directly in inputs/<account>/ are) — say so instead of
    # silently dropping, e.g., inputs/margin/2025/*.csv.
    if inputs_dir is not None and inputs_dir.is_dir():
        for name in accounts:
            adir = inputs_dir / str(name)
            if not adir.is_dir():
                continue
            for sub in sorted(adir.iterdir()):
                if (not sub.is_dir() or sub.name.startswith(".")
                        or sub.suffix.lower() == ".numbers"):
                    continue
                # Spreadsheets too: an .xlsx here got no word at all
                # (S043-13).
                n_csv = sum(1 for f in sub.rglob("*")
                            if f.is_file() and f.suffix.lower()
                            in (".csv", ".tt") + SPREADSHEET_SUFFIXES)
                if n_csv:
                    warnings.append(
                        f"inputs/{name}/{sub.name}/ holds {n_csv} "
                        f"CSV/.tt/spreadsheet file(s) that are NOT read "
                        f"— only CSV and .tt files "
                        f"directly in inputs/{name}/ are processed; move "
                        f"them up a level (or out of inputs/ if they are "
                        f"not meant for this account)")
    # Spreadsheet exports (Questrade's default download is .xlsx) sit
    # next to the CSVs but are never read: the run exited 0 with every
    # trade in them missing and never named the file (R1-64/R1-248).
    # Fatal unless the file's CSV conversion sits beside it.
    if inputs_dir is not None and inputs_dir.is_dir():
        unconverted: List[str] = []
        for name in accounts:
            adir = inputs_dir / str(name)
            csv_stems = {p.stem.lower() for p in input_files(adir, ".csv")}
            for sheet in spreadsheet_inputs(adir):
                rel = f"inputs/{name}/{sheet.name}"
                if sheet.stem.lower() in csv_stems:
                    warnings.append(
                        f"{rel} is not read (spreadsheets never are); its "
                        f"CSV conversion {sheet.stem}.csv is. Move the "
                        f"spreadsheet out of inputs/ to silence this.")
                else:
                    unconverted.append(rel)
        if unconverted:
            _die("spreadsheet export(s) in inputs/ are NOT read — only "
                 ".csv and .tt files are, so every trade in them would be "
                 "missing from the books:\n    "
                 + "\n    ".join(unconverted)
                 + "\n  Convert each to CSV next to it (`taxjson-xlsx-to-csv "
                 "FILE.xlsx -o FILE.csv`, or the broker's CSV download) "
                 "and move the spreadsheet out of inputs/.")
    # Inputs dir with data but no [accounts.*] entry: today that folder is
    # silently ignored — the inverse of the configured-but-unpopulated
    # warning the run loop already prints.
    if inputs_dir is not None and inputs_dir.is_dir():
        for sub in sorted(inputs_dir.iterdir()):
            # inputs/slips/ is the checklist's home for T5008/1099-B
            # CSVs (read by reconcile-slips) — not an account folder.
            if not sub.is_dir() or sub.name in accounts \
                    or sub.name == "slips":
                continue
            if input_files(sub, ".csv") or input_files(sub, ".tt") \
                    or spreadsheet_inputs(sub):
                warnings.append(f"inputs/{sub.name}/ contains data but has "
                                f"no [accounts.{sub.name}] section — it "
                                f"will NOT be processed")
    return warnings


# ---------------------------------------------------------------- broker detection

# Brokers with corp-action extractors (taxjson-corp-actions). Others
# (webull, coinbase, kraken) have no extractor and skip that stage.
CORP_ACTION_BROKERS = {"ib", "interactive_brokers", "questrade", "qt",
                       "rbc", "rbc_direct"}

# The config advertises `country = "canada | ca | usa | us"` and the gains
# engine accepts all four, but taxjson-corp-actions only knows the canonical
# names. Normalize once so an alias like "ca" doesn't abort the corp-actions
# stage at argparse (which restricts --country to RULES_BY_COUNTRY's keys).
# The one resolver lives in lib/country.py (partition audit R1): an
# unknown or missing country is refused everywhere with one message.
from taxjson.lib.country import command_country_problem  # noqa: E402


# (headline, detail) — `_say("note", *_US_EXPERIMENTAL_NOTE)`.
_US_EXPERIMENTAL_NOTE = (
    "the US engine is EXPERIMENTAL",
    "Its rules are implemented and unit-tested but have not been "
    "validated against a real account. Treat the output as a draft, and "
    "consider contributing a redacted export (`taxjson redact`) so it "
    "can be.")


def _normalize_country(c: str) -> str:
    """Canonical canada|usa (lib/country.canonical_country); dies with
    the resolver's message on anything else."""
    from taxjson.lib.country import CountryError, canonical_country
    try:
        return canonical_country(c)
    except CountryError as e:
        _die(str(e))


def _country(settings: Optional[Dict[str, Any]]) -> str:
    """The project's canonical country from a [settings] table. A
    missing or unknown value dies with the one resolver message — never
    a silent Canada (partition audit R1: every reader but `run` used to
    default to it)."""
    from taxjson.lib.country import CountryError, settings_country
    try:
        return settings_country(settings)
    except CountryError as e:
        _die(f"{e}{'' if (settings or {}).get('country') else ' in taxjson.toml'}")


def _home_currency(settings: Dict[str, Any]) -> str:
    """The currency the project's country files in (CAD / USD)."""
    from taxjson.lib.country import home_currency
    return home_currency(_country(settings))


def _base(settings: Dict[str, Any]) -> str:
    """[settings] base_currency, else the country's currency. The
    config readers refuse a base that is not the country's."""
    b = settings.get("base_currency")
    return str(b).strip().upper() if b else _home_currency(settings)


def _tax_date(settings: Dict[str, Any]) -> str:
    """The date basis in force: [settings] tax_date, else the country
    default (lib/country.settings_tax_date)."""
    from taxjson.lib.country import CountryError, resolve_tax_date
    try:
        return resolve_tax_date(_country(settings), settings.get("tax_date"))
    except CountryError as e:
        _die(str(e))


def _country_has_corp_rules(country: str) -> bool:
    """Whether taxjson-corp-actions has election rules for this
    jurisdiction (both countries do: RULES_BY_COUNTRY)."""
    from taxjson.lib.corp_actions import RULES_BY_COUNTRY
    return _normalize_country(country) in RULES_BY_COUNTRY


def _warn_zero_value_spinoffs(name: str, is_taxable: bool,
                              corp_files: List[Path], cache: Path) -> None:
    """A taxable spin-off booked at $0 (the documented `fmv_per_share=0`
    "defer") books no dividend income and a $0 cost for the new shares:
    a later sale overstates the gain by the same amount. It stays loud
    on EVERY run — on the console and, through a `.diag` sidecar, in the
    account's .sum — until a value is set (2026-09 audit: it was silent
    after the prompt). Registered accounts: no tax effect, no warning."""
    import json as _json
    from taxjson.lib.corp_actions import (ALLOCATED_BASIS_HINT,
                                          zero_basis_rollover_rows,
                                          zero_value_merger_rows,
                                          zero_value_spinoff_rows)
    diag = cache / f"{name}_corp_spinoff_value.diag"
    lines: List[str] = []
    if is_taxable:
        for f in corp_files:
            try:
                rows = _json.loads(f.read_text(encoding="utf-8")).get(
                    "transactions", [])
            except (OSError, ValueError):
                continue
            for r in zero_value_spinoff_rows(rows):
                eid = r.get("corp_event_id", "?")
                lines.append(
                    f"warning: {name}: spin-off {r.get('symbol')} on "
                    f"{r.get('date')} (event {eid}) is booked at $0 — no "
                    f"dividend income and a $0 cost for the new shares, "
                    f"so a later sale overstates the gain by the same "
                    f"amount. Set its value: taxjson elect {name} --set "
                    f"{eid}={r.get('corp_election')} --hint "
                    f"fmv_per_share=<value>")
            # A taxable merger at $0 (the "0 to defer" FMV, with or
            # without cash-in-lieu): a fake loss on the old shares and a
            # $0 cost for the new ones (audits S020-06, S074-00).
            for r in zero_value_merger_rows(rows):
                eid = r.get("corp_event_id", "?")
                lines.append(
                    f"warning: {name}: merger into {r.get('symbol')} on "
                    f"{r.get('date')} (event {eid}) is booked at $0 — the "
                    f"old shares' proceeds are only any cash-in-lieu (a "
                    f"fake loss) and the new shares cost $0. Set its "
                    f"value: taxjson elect {name} --set "
                    f"{eid}={r.get('corp_election')} --hint "
                    f"fmv_per_share=<value>")
            # An s.86.1 / §355 rollover allocated $0: the parent keeps
            # its whole cost, the spin-off's sale books the gain
            # (audits S073-21, S074-04).
            for r in zero_basis_rollover_rows(rows):
                eid = r.get("corp_event_id", "?")
                el = r.get("corp_election")
                lines.append(
                    f"warning: {name}: spin-off {r.get('symbol')} on "
                    f"{r.get('date')} (event {eid}, {el}) is booked with "
                    f"$0 allocated cost — the parent keeps all of it and "
                    f"the spin-off's sale books the gain. Set it: taxjson "
                    f"elect {name} --set {eid}={el} --hint "
                    f"{ALLOCATED_BASIS_HINT[el]}=<amount>")
    if lines:
        diag.write_text("\n".join(lines) + "\n", encoding="utf-8")
        for ln in lines:
            _echo_captured(ln, file=sys.stderr)
    else:
        diag.unlink(missing_ok=True)


def _warn_expired_open_options(name: str, gains_json: Path, cache: Path,
                               year: Any,
                               tax_date: Optional[str] = None) -> None:
    """An option still open in the books after its expiry date: the
    export dropped the expiry / assignment / exercise row. For a LONG
    contract the premium paid is a capital loss of the expiry year that
    the books never realize (R1-37); option-boundary covers written
    contracts only. Loud on every run and, through a `.diag` sidecar,
    in the account's .sum. Cutoff: lib/option_boundary.expired_test,
    the one its twin `expired_open` (checklist, option-boundary) uses —
    expired by the later of the year end and the last date the books
    cover, and before today (audit A2-1210, A2-1112)."""
    import json as _json
    from datetime import date as _date
    from taxjson.lib.core import is_option_symbol, parse_option_expiry
    diag = cache / f"{name}_expired_options.diag"
    # An expiry ON Dec 31 is that year's (re-audit A2-0716): the year
    # end is inclusive, today exclusive (a contract expiring today may
    # still trade).
    _today = _date.today().isoformat()

    def _expired(exp: str) -> bool:
        return exp <= f"{year}-12-31" and exp < _today
    lines: List[str] = []
    try:
        inv = _json.loads(gains_json.read_text(encoding="utf-8")).get(
            "inventory") or []
    except (OSError, ValueError, AttributeError):
        inv = []
    _txs = None
    if any(is_option_symbol(str(h.get("symbol") or "")) for h in inv):
        try:
            from taxjson.lib.core import load_transactions
            from taxjson.lib.option_boundary import expired_test
            _base = cache / f"{name}_base.json"
            if _base.exists():
                _txs = load_transactions(_base)
                _expired = expired_test(_txs, int(year), tax_date=tax_date)
        except (OSError, ValueError, TypeError):
            _txs = None
    # Positions the broker says were opened BEFORE the data (IB code C on
    # the trade that opened them in the books): the missing row is the
    # purchase, not the expiry (audit S013-00).
    _closing: set = set()
    # One contract under two roots (a CLOSING row booked on RCX.B while
    # the books hold RCX, audit A2-0266): both legs stay open past the
    # expiry, and the fix is the ticker.map line, not a missing row.
    _redescribed: Dict[str, str] = {}
    if any(is_option_symbol(str(h.get("symbol") or "")) for h in inv):
        try:
            from taxjson.lib.option_boundary import expired_open
            from taxjson.lib.option_close_check import (
                unbacked_option_closes)
            if _txs is not None:
                _closing = {x["symbol"] for x in expired_open(
                    _txs, int(year), tax_date=tax_date)
                    if x.get("broker_closing")}
                for _f in unbacked_option_closes(_txs):
                    if len(_f["partners"]) == 1:
                        _p = _f["partners"][0][0]
                        _fix = f"GLOBAL {_p} {_f['symbol']}"
                        _redescribed.setdefault(_f["symbol"], _fix)
                        _redescribed.setdefault(_p, _fix)
        except (OSError, ValueError, TypeError):
            _closing = set()
    for h in inv:
        sym = str(h.get("symbol") or "")
        try:
            qty = float(h.get("qty") or 0.0)
        except (TypeError, ValueError):
            continue
        if abs(qty) < 1e-9 or not is_option_symbol(sym):
            continue
        exp = parse_option_expiry(sym)
        if not exp or not _expired(exp):
            continue
        side = "long" if qty > 0 else "written"
        if sym in _redescribed:
            lines.append(
                f"warning: {name}: {sym} expired {exp} and the books still "
                f"hold {qty:g} ({side}): a CLOSING row was booked under "
                f"another root of the same contract (see the ATTENTION "
                f"line) — add to ticker.map:  {_redescribed[sym]}  — not "
                f"a missing row.")
            continue
        if sym in _closing:
            lines.append(
                f"warning: {name}: {sym} expired {exp} and the books still "
                f"hold {qty:g} ({side}), but the broker coded the trade "
                f"that opened it CLOSING (IB code C / RBC CLOSE CONTRACT): "
                f"it closed a position "
                f"opened before the data — add the missing "
                f"{'write' if qty > 0 else 'purchase'} (`taxjson "
                f"find-missing-history`), not an expiry row.")
            continue
        lines.append(
            f"warning: {name}: {sym} expired {exp} but the books still "
            f"hold {qty:g} ({side}) — the export is missing its expiry, "
            f"assignment or exercise row"
            + (f"; the {abs(float(h.get('total_cost') or 0.0)):,.2f} paid "
               f"is a loss of {exp[:4]} that is not booked"
               if qty > 0 else "")
            + ". Add the missing row (an expiry is a BUYSELL closing "
              "the position at 0 on the expiry date) and re-run.")
    if lines:
        diag.write_text("\n".join(lines) + "\n", encoding="utf-8")
        for ln in lines:
            _echo_captured(ln, file=sys.stderr)
    else:
        diag.unlink(missing_ok=True)


def _refuse_crypto_openings(name: str, tt_jsons) -> None:
    """An OPENING line in a crypto account: the crypto books have no
    merge2 stage, so the snapshot cut-off (lib/opening) would not run
    and the coins before it would count twice. Refused, naming the
    file."""
    import json as _json
    from taxjson.lib.core import is_opening_row
    for p in tt_jsons:
        try:
            rows = _json.loads(Path(p).read_text(
                encoding="utf-8")).get("transactions") or []
        except (OSError, ValueError, AttributeError):
            continue
        if any(isinstance(t, dict) and is_opening_row(t) for t in rows):
            _die(f"account {name} is a crypto account: an OPENING line "
                 f"({Path(p).name}) is for share accounts only — enter "
                 f"the coins' purchases as BUYSELL lines instead.")


def detect_broker(csv_path: Path) -> Optional[str]:
    """Which parser reads this CSV (lib/brokerages/detect.detect): an
    explicit generic mapping, else the file's CONTENT (each supported
    export's header signature, from the parser's own required columns),
    else — only when no content signature matched — the cb_/kr_/generic_
    prefix or the coinbase/kraken word in the name. None when nothing
    routes it. A file whose content matches two exports raises
    AmbiguousBroker."""
    from taxjson.lib.brokerages.detect import detect
    return detect(csv_path).broker


def input_files(dirpath: Path, suffix: str) -> List[Path]:
    """Input files by suffix, CASE-INSENSITIVE. Excel and several
    brokers export TRADES.CSV / START.TT; glob("*.csv") silently
    ignored them while the GUI import accepted them — a run that
    exits 0 with those trades missing (REVIEW-2026-07-ui #1)."""
    if not dirpath.is_dir():
        return []
    # Hidden files (macOS '._x.csv' AppleDouble) and Office lock files
    # ('~$x.csv') are never inputs; the checklist's input fingerprint
    # skips them too, so the two agree on the input set (A2-1145,
    # A2-1166).
    out = []
    for p in sorted(dirpath.iterdir()):
        if p.suffix.lower() != suffix or p.name.startswith((".", "~$")):
            continue
        if p.is_file():
            out.append(p)
        elif p.is_symlink():
            # A statement that is a dangling (or looping) symlink was
            # left out of the books at exit 0 (re-audit A2-0143/A2-0403).
            import os as _os
            try:
                tgt = _os.readlink(p)
            except OSError:
                tgt = "?"
            _die(f"{p} is a symlink to {tgt}, which does not exist (or "
                 f"loops) — its rows would be missing from the books. "
                 f"Fix the link or remove it.")
    return out


# Spreadsheet suffixes a broker export may arrive in. None is read by
# the run; validate_config refuses them unless converted (R1-64; Apple
# Numbers too, A2-1156 — lib/checklist.SPREADSHEET_SUFFIXES is the same).
SPREADSHEET_SUFFIXES = (".xlsx", ".xls", ".xlsm", ".ods", ".numbers")


def spreadsheet_inputs(dirpath: Path) -> List[Path]:
    """Spreadsheet files directly in an inputs folder (never read)."""
    if not dirpath.is_dir():
        return []
    # A Numbers document can be a package DIRECTORY (macOS bundle copied
    # as-is): it is a spreadsheet all the same (re-audit A2-0714).
    return sorted(p for p in dirpath.iterdir()
                  if (p.is_file() or (p.is_dir()
                                      and p.suffix.lower() == ".numbers"))
                  and not p.name.startswith((".", "~$"))
                  and p.suffix.lower() in SPREADSHEET_SUFFIXES)


def group_inputs(account_dir: Path) -> Dict[str, List[Path]]:
    """{parser id: [csv]} for an account's inputs folder."""
    return group_inputs_detailed(account_dir)[0]


def group_inputs_detailed(account_dir: Path):
    """({parser id: [csv]}, [Detection]) — every CSV of the folder and
    how it was routed (lib/brokerages/detect). Stops the run on a file
    that cannot be read, is empty, is not UTF-8/UTF-16, matches two
    exports, or matches nothing."""
    from taxjson.lib.brokerages.detect import AmbiguousBroker, detect
    from taxjson.bin.taxjson_detect_brokerage import cannot_detect_message
    out: Dict[str, List[Path]] = {}
    found = []
    for csv in input_files(account_dir, ".csv"):
        # An unreadable or empty file got the "rename it to cb_/kr_/
        # generic_" advice; renaming never helps (re-audit A2-0713,
        # A2-1228).
        try:
            with open(csv, "rb") as _fh:
                _head = _fh.read(4096)
        except OSError as e:
            from taxjson.lib.cli_diag import describe_input_error
            _die(f"{describe_input_error(e)} — taxjson cannot read this "
                 f"input; fix its permissions (or remove it).")
        if not _head.strip(b" \t\r\n\xef\xbb\xbf\x00"):
            _die(f"{csv} is empty — a failed or interrupted download? "
                 f"Download the export again (or remove the file).")
        try:
            det = detect(csv)
        except AmbiguousBroker as e:
            _die(str(e))
        if det.positions:
            # A positions report (what is held on a date, not activity —
            # lib/positions_reports) dropped into inputs/: listed with
            # the detection lines and skipped, never parsed as trades
            # and never a failed run. `taxjson sanity` / `taxjson
            # opening` read it.
            found.append(det)
            continue
        if not det.broker:
            # Content detection cannot read a cp1252 re-save: the
            # rename advice below pointed at the wrong fix (S024-03).
            try:
                _raw = csv.read_bytes()
                if _raw[:2] not in (b"\xff\xfe", b"\xfe\xff"):
                    _raw.decode("utf-8-sig")
            except UnicodeDecodeError as e:
                from taxjson.lib.cli_diag import not_utf8
                _die(str(not_utf8(csv, e)))
            except OSError:
                pass
            # On the console: the file as it is on disk (an export's
            # default name is its account number; masking it here hid
            # which of two such files is meant).
            from taxjson.lib.out import one_line as _one_line
            _die(cannot_detect_message(
                det, shown=f"inputs/{account_dir.name}/"
                           f"{_one_line(csv.name)}"))
        out.setdefault(det.broker, []).append(csv)
        found.append(det)
    # A [[holding]] TOML in the folder (a positions file, not a generic
    # mapping sidecar `<file>.csv.toml` nor the folder's generic.toml)
    # is never read by the run either: listed the same way, so its
    # silence does not read as "taken into account".
    from taxjson.lib.brokerages.detect import Detection
    from taxjson.lib.positions_reports import (_is_holdings_toml,
                                               read_positions)
    for tml in input_files(account_dir, ".toml"):
        low = tml.name.lower()
        if low.endswith(".csv.toml") or low == "generic.toml":
            continue
        if not _is_holdings_toml(tml):
            continue
        try:
            _asof = read_positions(tml).as_of
        except Exception:
            _asof = ""
        found.append(Detection(
            tml, None, "positions",
            "holdings TOML" + (f", as of {_asof}" if _asof else ""),
            positions="holdings_toml"))
    return out, found


# Accounts whose per-file detection lines this `taxjson run` printed
# already (a crypto account is staged twice: parse first, then books).
_DETECTION_SHOWN: set = set()
# The broker parses this `taxjson run` made, by output: (what the parse
# read — its command and the bytes of every file it reads; what it
# wrote — its outputs as left on disk). An account read in the first
# pass (transfers / sends between your accounts) is staged again for its
# books: the same command over the same bytes is the same parse, so the
# books' pass takes it instead of parsing (and printing its messages)
# a second time (_reused_parse).
_PARSED_THIS_RUN: Dict[Path, Tuple[Any, Any]] = {}
# Run-console messages a stage shows once per run although the account
# is staged twice (first pass, then books): their keys.
_SHOWN_THIS_RUN: set = set()


def _say_once(key: Any, kind: str, text: str, *details: str,
              **kw: Any) -> None:
    """_say, unless this run already showed the message keyed `key`."""
    if key in _SHOWN_THIS_RUN:
        return
    _SHOWN_THIS_RUN.add(key)
    _say(kind, text, *details, **kw)


# The cross-listing joins this run computed: {work dir: (map path or
# None, analysis)} — once per run (lib/cross_listings).
_XLIST_THIS_RUN: Dict[Path, Tuple[Optional[Path], Dict[str, Any]]] = {}
# The dated events the project's .tt files declare (lib/dated_events):
# {work dir: Declarations} — read once per run, up front (cmd_run), and
# settled against the broker's legs once (stage_dated_events).
_DATED_THIS_RUN: Dict[Path, Any] = {}
_DATED_SETTLED: set = set()


def _read_dated_events(root: Path, accounts: Dict[str, Any],
                       tmap: Any) -> Any:
    """The project's .tt JOURNAL and RENAME lines (lib/dated_events),
    checked against ticker.map; a line that cannot be booked stops the
    run with its message (it names the form). Said once: the notes (a
    rename declared twice) and warnings."""
    from taxjson.lib import dated_events as DE
    # The record of the last run's events goes until this run writes its
    # own (_write_dated_events_state, at the end): a run that stops —
    # here or in any later stage — never leaves the last one's record
    # describing books it did not build.
    try:
        (root / "work" / DE.STATE).unlink()
    except OSError:
        pass
    try:
        decl = DE.read_declarations(root, accounts)
        problems = DE.check_against_map(decl, tmap)
    except DE.DatedEventError as e:
        problems = str(e).splitlines()
    else:
        # Two identical JOURNAL lines are one journal (a Warning).
        from taxjson.lib.cross_listings import declared_twins
        decl.journals, _twins = declared_twins(decl.journals)
        decl.warnings += _twins
    if problems:
        _die(f"{len(problems)} .tt dated-event line(s) cannot be booked",
             *[f"- {p}" for p in problems],
             "A JOURNAL line is `JOURNAL <date> <FROM> <TO> <qty>`, a "
             "RENAME line `RENAME <date> <OLD> <NEW> "
             "[late=fold|late=separate]` (date first). Fix the line or "
             "delete it.")
    for n in decl.notes:
        _say("note", *_split_msg(n), prog=_PROG)
    for w in decl.warnings:
        _say("warning", *_split_msg(w), prog=_PROG)
    _DATED_THIS_RUN[(root / "work").resolve()] = decl
    return decl


def _dated_effective_lines(cache: Path) -> List[str]:
    """The lines the run's effective map carries for the dated renames
    the project declares (lib/dated_events.effective_lines: the .tt
    events, and the merged facts of a legacy map line's event)."""
    from taxjson.lib import dated_events as DE
    decl = _DATED_THIS_RUN.get(cache.resolve())
    if decl is None:
        return []
    return DE.effective_lines(decl.events or decl.renames)


def stage_dated_events(cache: Path, accounts: List[str]):
    """The declared journals settled against the broker's own legs
    (lib/dated_events.settle_journals: a duplicate is booked once, a
    journal with one broker leg books the other), their legs written to
    each account's transfer evidence (work/<acct>_tt-journal_
    transfers.json) — once per run, from every equity account's parsed
    exports (`gathered`, lib/cross_listings.gather). Returns the
    Declarations (None when cmd_run read none: a stand-alone stage)."""
    from taxjson.lib import dated_events as DE
    key = cache.resolve()
    decl = _DATED_THIS_RUN.get(key)
    if decl is None or key in _DATED_SETTLED:
        return decl
    _DATED_SETTLED.add(key)
    if decl.journals:
        from taxjson.lib import cross_listings as XL
        legs, _n, _s = XL.gather(cache, accounts)
        for n in DE.settle_journals(decl.journals, legs):
            _say("note", *_split_msg(n), prog=_PROG)
        # A line restating the broker's own journal with another size
        # would move those units twice: it stops the run.
        _over = XL.partial_overlaps(decl.journals, legs)
        if _over:
            _die(f"{len(_over)} .tt dated-event line(s) cannot be booked",
                 *[f"- {p}" for p in _over],
                 "A journal the broker's rows already hold is booked from "
                 "them; a .tt JOURNAL line adds only what they lack.")
        # A bigger line a day from the broker's journal (the gambit's
        # trade date for its settlement date): booked, and said.
        from taxjson.lib.missing_history import _day_trades
        for _w in XL.near_restatements(decl.journals, legs,
                                       _day_trades(cache, accounts)):
            _say("warning", *_split_msg(_w), prog=_PROG)
    DE.write_sidecars(cache, accounts, decl.journals)
    by_acct: Dict[str, List[str]] = {}
    for j in decl.journals:
        if j.status != DE.STATUS_DUPLICATE:
            by_acct.setdefault(j.account, []).append(
                f"{j.date} {j.frm} -> {j.to} {j.quantity:g}")
    for acct, items in sorted(by_acct.items()):
        _say("note", f"{acct}: {len(items)} journal(s) from .tt lines "
             f"booked as transfer legs (one security, no disposition): "
             f"{'; '.join(items)}", indent="  ", file=sys.stdout)
    return decl


def stage_cross_listings(name: str, settings: Dict[str, Any], cache: Path,
                         ticker_map: Optional[Path]) -> Optional[Path]:
    """Two listings of one security joined by their transfer journal
    (lib/cross_listings, tax-logic CA-XLIST-01 / US-XLIST-01): computed
    once per run from every equity account's parsed exports (the first
    pass parses them all before any account's books are merged), written
    to work/cross_listings.state, and — when any pair is joined — the map
    the merge stages read becomes work/ticker.map.effective (the
    project's ticker.map plus a TOBASE line per pair). Returns the map
    path the account's merge stages use. One `Warning:` per account
    names the pairs joined through its legs and the `DISTINCT` line that
    undoes each."""
    from taxjson.lib import cross_listings as XL
    key = cache.resolve()
    if key not in _XLIST_THIS_RUN:
        cfg = _soft_config(cache.parent)
        accounts = [n for n, c in ((cfg.get("accounts") or {}).items())
                    if not (c or {}).get("crypto")]
        named: set = set()
        apart: set = set()
        if ticker_map is not None and ticker_map.is_file():
            from taxjson.bin.taxjson_ticker_map import _parse_map_file
            try:
                _tm = _parse_map_file(ticker_map)[0]
            except (OSError, ValueError):
                _tm = None
            if _tm is not None:
                # A rename / DELETE naming a listing decides it; a
                # DISTINCT line keeps its own pair apart.
                named = set(_tm.delete)
                for _d in (_tm.glob, _tm.tobase, _tm.journal):
                    named.update(_d)
                    named.update(_d.values())
                for _dr in _tm.dated:
                    named.update((_dr.old, _dr.new))
                apart = set(_tm.distinct)
        _pre = _DATED_THIS_RUN.get(key)
        for _dr in (_pre.renames if _pre is not None else ()):
            named.update((_dr.old, _dr.new))
        from taxjson.lib.country import is_canada
        from taxjson.lib import dated_events as _DE
        _decl = stage_dated_events(cache, accounts or [name])
        _rows: list = []
        legs, names, shown = XL.gather(cache, accounts or [name], _rows)
        if _decl is not None and _decl.journals:
            legs = sorted(legs + _DE.journal_legs(_decl.journals),
                          key=lambda g: (g.date, g.account, g.broker,
                                         g.symbol, g.quantity))
        _base = str(settings.get("base_currency") or "").upper() or None
        # One symbol naming two companies (a TSX fund's US-dollar unit
        # booked .US beside an NYSE stock of the root): never a join or
        # a TOBASE suggestion — the EXTRACT line that separates them.
        _coll = XL.collisions(_rows, names, shown, legs,
                              base_currency=_base)
        _refused: list = []
        result = XL.analyze(legs, names, shown, map_named=named,
                            map_distinct=apart, base_currency=_base,
                            collided=[c.symbol for c in _coll],
                            # A broker's currency journal between a
                            # security's CAD and USD lines is joined as a
                            # JOURNAL line in a Canadian project only
                            # (CA-XLIST-03); a US project reads its legs
                            # as transfers.
                            currency_journals=is_canada(
                                settings.get("country")),
                            declared=(_decl.journals if _decl is not None
                                      else ()),
                            # The pairs left alone (the user's map, two
                            # companies): `taxjson journals` lists them.
                            refused=_refused)
        result["collisions"] = _coll
        result["refused"] = _refused
        state = cache / XL.STATE
        text = XL.state_text(result)
        if _read_work_stamp(state) != text:
            _write_work_stamp(state, text)
        # A .tt JOURNAL line between two listings nothing shows are one
        # security stops the run (pre-release review M2): a join of two
        # symbols on the user's word alone is a ticker.map TOBASE line.
        _unproven = [p for p in _refused
                     if p.extra.get("refused") == XL.UNPROVEN]
        if _unproven:
            _die(f"{len(_unproven)} .tt JOURNAL line(s) join two listings "
                 f"that nothing shows are one security",
                 *[f"- {p.extra.get('where') or p.out.account}: JOURNAL "
                   f"{p.out.date} {p.out.symbol} {p.into.symbol} — "
                   f"{p.reason}" for p in _unproven],
                 "A JOURNAL line moves units between two listings of ONE "
                 "security (a TSX line and its US-dollar or NYSE line): "
                 "check the two symbols. To join two symbols on your word "
                 "(the same shares under another ticker), add "
                 + " / ".join(
                     "`TOBASE {} {}`".format(*XL.tobase_direction(
                         p.out.symbol, p.into.symbol, _base))
                     for p in _unproven)
                 + " to ticker.map: the line is then booked. Else delete "
                 "the line.")
        eff = cache / XL.EFFECTIVE_MAP
        # The ticker changes declared in .tt files (lib/dated_events)
        # reach every stage that books renames through the effective map.
        _ren_lines = _dated_effective_lines(cache)
        if result["joined"] or _ren_lines:
            body = XL.effective_map_text(ticker_map, result["joined"],
                                         _ren_lines)
            if _read_work_stamp(eff) != body:
                _write_work_stamp(eff, body)
            path: Optional[Path] = eff
        else:
            if eff.exists():
                # The joins are gone: the books merged with them must
                # rebuild (a sources manifest is every merge's dep).
                eff.unlink()
                import os as _os
                for _f in cache.glob("*_sources.list"):
                    if not _f.name.startswith("."):
                        _os.utime(_f)
            path = ticker_map
        _XLIST_THIS_RUN[key] = (path, result)
    path, result = _XLIST_THIS_RUN[key]
    for _c in result.get("collisions") or []:
        _h, _d = XL.collision_note(_c)
        _say_once(("xcollide", _c.symbol), "warning", _h, *_d,
                  indent="  ", file=sys.stdout)
    # A listing read from the evidence, not the row currency (lib/
    # listing_suffix): the join that names it says so; the others get
    # a Warning of their own (it changes the books too).
    from taxjson.lib import listing_suffix as LS
    _fixed = {k: LS.why(frm, r)
              for k, (frm, r) in LS.all_corrections(cache).items()}
    msg = XL.joined_note(name, result["joined"], corrected=_fixed)
    if msg:
        # A Warning: the join changes the books (pre-release review H1).
        _say_once(("xlist", name), "warning", msg[0], *msg[1],
                  indent="  ", file=sys.stdout)
    _in_joins = {p.into.symbol for p in result["joined"]
                 if p.into.account == name} | {
        p.out.symbol for p in result["joined"] if p.out.account == name}
    msg = LS.corrections_note(name, cache, skip=_in_joins)
    if msg:
        _say_once(("listing", name), "warning", msg[0], *msg[1],
                  indent="  ", file=sys.stdout)
    return path


def _parse_reads(cmd: List[str], acct_dir: Path, reads: List[Path]
                 ) -> Tuple[Any, ...]:
    """What a broker parse reads: its command, and the name, size and
    SHA-256 of every file it opens — `reads` (its inputs, maps, rates)
    and every CSV and mapping file of the account's folder (a parser
    reads a sibling export: a Kraken ledger beside its trades)."""
    files = list(reads)
    try:
        files += [p for p in acct_dir.iterdir()
                  if p.suffix.lower() in (".csv", ".toml")]
    except OSError:
        pass
    return (tuple(cmd), _inputs_fingerprint(
        [p for p in files if p.is_file()]))


def _parse_outputs(out: Path) -> Tuple[Any, ...]:
    """A broker parse's outputs as they are on disk: the books, its
    .diag, its transfers sidecar, its overrides log — present or not,
    each by inode, size and mtime."""
    state = []
    for p in (out, out.with_name(out.name + ".diag"),
              out.with_name(out.stem + "_transfers.json"),
              out.with_name(out.stem + ".overrides")):
        try:
            st = p.stat()
            state.append((p.name, st.st_ino, st.st_size, st.st_mtime_ns))
        except OSError:
            state.append((p.name, None))
    return tuple(state)


def _reused_parse(out: Path, reads: Tuple[Any, ...]) -> bool:
    """True when this run already made the parse `out` from the same
    `reads` (_parse_reads) and its outputs are as it left them."""
    seen = _PARSED_THIS_RUN.get(out)
    return seen is not None and seen == (reads, _parse_outputs(out))


def _report_detection(name: str, found, cache: Path) -> None:
    """Print one line per input CSV — how its broker was detected — and
    persist them to work/<acct>_detect.diag, whose `note:` lines (the
    name disagreed with the content, a name-only routing) reach the
    account's .sum DIAGNOSTICS. The console names each file as it is on
    disk (two exports whose names mask alike, 55500001.csv and
    55500001_2.csv, must be told apart there); the saved .diag, like
    every saved diagnostic, masks account-number-like parts
    (shown_name)."""
    from taxjson.lib.brokerages.base import shown_name
    from taxjson.lib.out import one_line
    lines: List[str] = []
    notes: List[str] = []
    console: List[Tuple[str, str]] = []
    for det in found:
        masked = shown_name(det.path)
        # A control character in the name is escaped (one_line): a
        # newline in it must not start a line of its own.
        on_disk = one_line(det.path.name)
        lines.append(det.line(f"inputs/{name}/{masked}"))
        console.append(("  ", det.line(f"inputs/{name}/{on_disk}")))
        if det.note:
            notes.append(f"note: {det.note}")
            real = (det.note.replace(masked, on_disk, 1)
                    if det.note.startswith(masked) else det.note)
            console.append(("    ", f"note: {real}"))
    from taxjson.lib.out import show as _show, width as _width
    if name not in _DETECTION_SHOWN and _width(sys.stdout) > 0:
        _DETECTION_SHOWN.add(name)
        # Shown to a person (The run's console): one `Info:` line per
        # file, what it was identified as — how (the content's header)
        # stays in work/<acct>_detect.diag; then the notes.
        for det in found:
            on_disk = one_line(det.path.name)
            where = f"inputs/{name}/{on_disk}"
            if det.positions:
                text = (f"Info: File {where} is a positions report, not "
                        f"activity: skipped (`taxjson sanity` and "
                        f"`taxjson opening` read it)")
            elif det.broker:
                text = f"Info: File {where} → identified as {det.display}"
            else:
                text = (f"Warning: File {where} → not identified"
                        + (f" ({det.reason})" if det.reason else ""))
            _show(_out_wrap(text, hang=""), sys.stdout)
        for ind, ln in console:
            if ind != "  ":
                _show(_out_wrap(_labelled_note(ln), hang=""), sys.stdout)
    elif name not in _DETECTION_SHOWN:
        _DETECTION_SHOWN.add(name)
        # Lines first, then the notes, as the .diag keeps them (a note
        # shown with its label first, lib/out.labelled).
        from taxjson.lib.out import labelled as _labelled
        for ind, ln in ([c for c in console if c[0] == "  "]
                        + [c for c in console if c[0] != "  "]):
            for _w in _out_wrap(_labelled(ln), indent=ind, hang="      "):
                print(_w)
    _txt = "".join(f"{x}\n" for x in lines + notes)
    _diag = cache / f"{name}_detect.diag"
    if _read_work_stamp(_diag) != _txt:
        _write_work_stamp(_diag, _txt)


def _labelled_note(line: str) -> str:
    """A `note: ...` line as a person is shown it (lib/out.labelled)."""
    from taxjson.lib.out import labelled
    return labelled(line)


def _is_generic_group(broker: str) -> bool:
    return broker == "generic" or broker.startswith("generic-")


def _generic_files(grouped: Dict[str, List[Path]]) -> List[Path]:
    return [p for b, ps in grouped.items() if _is_generic_group(b)
            for p in ps]


def _split_generic_groups(grouped: Dict[str, List[Path]]
                          ) -> Dict[str, List[Path]]:
    """generic_*.csv files whose mapping names the real broker
    (`[broker] name = "wealthsimple"`) are parsed per broker, in a
    `generic-<name>` group (work/<acct>_generic-<name>.json, recorded as
    source_brokerage generic:<name>), so the fees report attributes each
    broker instead of one 'generic' bucket (audit S027-05). Unnamed
    mappings stay in the plain `generic` group."""
    files = grouped.get("generic")
    if not files:
        return grouped
    from taxjson.lib.brokerages.generic import mapping_broker_name
    out: Dict[str, List[Path]] = {}
    for b, ps in grouped.items():
        if b != "generic":
            out[b] = ps
            continue
        for p in ps:
            try:
                nm = mapping_broker_name(p)
            except ValueError:
                nm = None       # the parse stage reports the mapping error
            out.setdefault(f"generic-{nm}" if nm else "generic",
                           []).append(p)
    return out


def _raw_mixed_currency_symbols(raw_json: Path) -> List[str]:
    """Symbols whose NATIVE-currency pool would mix currencies —
    following SPLIT renames. A cross-currency rollover (e.g. ABG.TO
    [CAD] --s.85.1(5)--> ABH.US [USD]) renames the CAD pool onto a
    symbol whose later trades are USD; the raw (unconverted) gains
    stage then dies with a currency-mismatch error and killed the
    whole run. Such positions are unrepresentable in the native view
    BY CONSTRUCTION — the caller skips the raw stage with a warning
    instead (the converted, tax-authoritative books are unaffected)."""
    import json as _json
    try:
        txs = _json.loads(raw_json.read_text(
            encoding="utf-8")).get("transactions", [])
    except (OSError, ValueError):
        return []
    renames: Dict[str, str] = {}
    for t in txs:
        if (t.get("action") == "SPLIT" and t.get("symbol_new")
                and t["symbol_new"] != t.get("symbol")):
            renames[t["symbol"]] = t["symbol_new"]

    def _final(sym: str) -> str:
        seen = set()
        while sym in renames and sym not in seen:
            seen.add(sym)
            sym = renames[sym]
        return sym

    curs: Dict[str, set] = {}
    for t in txs:
        # SPLIT rows are not counted: they carry no money, and a .tt
        # SPLIT is stamped CAD whatever the listing — a USD stock's
        # split then looked like a mixed-currency pool and the holdings
        # refresh was skipped with a misleading "rollover rename"
        # message (R1-126). A rename's currency mix still shows through
        # the trades on either side of it (followed via `renames`).
        # ADJUST / DISALLOW rows carry money onto the pool too: a
        # CAD-valued corporate-action ADJUST on a USD pool (an s.86.1
        # allocation with no rate to express it in USD — A2-0002), or a
        # USD return of capital on a CAD listing that
        # _raw_align_adjust_currency could not price (A2-0055/0191/0204),
        # would stop the native gains pass.
        # Every action the engines' currency guards check (an
        # OPENING_BALANCE too; a TRANSFER is never checked) — the list
        # here missed OPENING_BALANCE and flagged TRANSFER (audit
        # A2-0440). lib/core.POOL_FREE_ACTIONS is the one list.
        from taxjson.lib.core import POOL_FREE_ACTIONS
        if t.get("action") in POOL_FREE_ACTIONS:
            continue
        c, sym = t.get("currency"), t.get("symbol")
        if c and sym:
            curs.setdefault(_final(sym), set()).add(c)
    return sorted(sym for sym, cs in curs.items() if len(cs) > 1)


def _raw_align_adjust_currency(raw_json: Path, rates_path: Path,
                               base_currency: str) -> List[str]:
    """Restate, in the pool's own currency, every ADJUST / DISALLOW row of
    the NATIVE-currency raw merge that is in another currency: a USD
    return of capital on a TSX listing (RBC, Questrade, IB), a CAD T3
    box-42 ADJUST on a USD unit (README recipe). The native gains pass
    pools one currency per symbol and used to stop the whole run at
    "raw gains" with advice a project user cannot act on (audit
    A2-0055/0191/0204). The amount is converted through the base
    currency at the row's date (the same Bank of Canada / base rates the
    filing books use); the converted, tax-authoritative books are
    untouched — they convert every row anyway. A row with no rate is
    left as is (the raw view is then skipped with a note). Returns one
    line per restated row for the console."""
    import json as _json
    from datetime import timedelta
    from decimal import Decimal as _D
    try:
        doc = _json.loads(raw_json.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return []
    txs = doc.get("transactions", []) if isinstance(doc, dict) else []
    pool_cur: Dict[str, set] = {}
    for t in txs:
        if t.get("action") in ("BUYSELL", "ASSIGN", "TRANSFER",
                               "OPENING_BALANCE") and t.get("currency"):
            pool_cur.setdefault(t.get("symbol"), set()).add(t["currency"])
    todo = [t for t in txs
            if t.get("action") in ("ADJUST", "DISALLOW")
            and t.get("currency")
            and len(pool_cur.get(t.get("symbol"), ())) == 1
            and t["currency"] not in pool_cur[t.get("symbol")]]
    if not todo:
        return []
    from taxjson.bin.taxjson_convert_currency import load_exchange_rates
    base = (base_currency or "").upper()
    try:
        hist = load_exchange_rates(rates_path, target_curr=base)
    except (OSError, ValueError):
        return []

    def _rate(cur: str, day: str):
        if cur == base:
            return _D(1)
        h = hist.get(cur) or {}
        try:
            d0 = datetime.strptime(day, "%Y-%m-%d")
        except (TypeError, ValueError):
            return None
        for i in range(6):           # prior business day, as convert does
            k = (d0 - timedelta(days=i)).strftime("%Y-%m-%d")
            if k in h:
                return h[k]
        return None
    notes = []
    for t in todo:
        src, dst = t["currency"], next(iter(pool_cur[t["symbol"]]))
        day = t.get("date") or ""
        r_src, r_dst = _rate(src, day), _rate(dst, day)
        if not r_src or not r_dst:
            continue
        f = r_src / r_dst
        for k in ("net_amount", "gross_amount"):
            if t.get(k) not in (None, ""):
                t[k] = float(_D(str(t[k])) * f)
        t["currency"] = dst
        notes.append(f"{t['symbol']} {t['action']} {day}: {src} amount "
                     f"restated as {t['net_amount']:,.2f} {dst} for the "
                     f"native-currency holdings view")
    if notes:
        from taxjson.lib.safe_write import write_atomic
        write_atomic(raw_json, _json.dumps(doc, indent=2))
    return notes


# ---------------------------------------------------------------- stages

def _rates_coverage_stale(rates_path: Path, today: Optional[date_cls] = None,
                          currencies: Optional[List[str]] = None) -> bool:
    """Whether to_base.csv's DATA has aged out. Freshness is a property of
    the data, not the file's mtime: coverage ends at the generation date,
    so on a stable install (no package/config mtime bumps to invalidate
    the cache) the file would otherwise be reused forever and every trade
    after its last row would have no rate (and stop the conversion).
    Stale when the newest rate row is more than 3 days old (tolerates
    weekends/short holidays without refetching daily) — judged PER
    CURRENCY when `currencies` is given: the file concatenates one block
    per source currency, and a USD block cut short by a failed download
    hid behind a fresh AUD last line (S046-06)."""
    today = today or date_cls.today()
    newest: Dict[str, date_cls] = {}
    try:
        with rates_path.open("r", encoding="utf-8") as f:
            for line in f:
                parts = line.split()
                if not parts:
                    continue
                d = datetime.strptime(parts[0], "%Y-%m-%d").date()
                cur = parts[2].upper() if len(parts) > 2 else ""
                for key in (cur, "*"):
                    if key not in newest or d > newest[key]:
                        newest[key] = d
    except (OSError, ValueError, IndexError):
        return True                          # unreadable/malformed: refetch
    if "*" not in newest:
        return True                          # sources configured, no rows
    keys = [c.upper() for c in currencies] if currencies else ["*"]
    return any(k not in newest or (today - newest[k]).days > 3
               for k in keys)


def stage_currency_rates(settings: Dict[str, Any], cache: Path) -> Path:
    """Build to_base.csv by appending taxjson-to-base-curr output for each
    configured source currency. Caches across runs while every source
    currency's rates reach the last few days: a refresh whose download
    failed for one currency (its block ends early) is refetched on the
    next run instead of being served for days behind another currency's
    fresh last line (S046-06)."""
    base = settings["base_currency"]
    sources = [c for c in settings.get("source_currencies", ["USD"]) if c != base]
    # Ensure the cache dir exists before any write — applies to both
    # the no-sources branch (writes an empty file as a marker) and the
    # fetch branch below. Without this, a fresh CAD-only setup with
    # `source_currencies = []` would crash on the empty-write because
    # `work/` didn't exist yet.
    cache.mkdir(parents=True, exist_ok=True, mode=0o700)
    rates_path = cache / "to_base.csv"
    if rates_path.is_dir():
        # a traceback at st_size / write_text (re-audit A2-1433)
        _die_input(_work_path_problem(rates_path))
    if not sources:
        # Only touch the marker when its content is wrong: an
        # unconditional write bumped the mtime every run, and since
        # to_base.csv is a merge2/convert dep, --fast re-merged every
        # account on every invocation for offline (no-source-currency)
        # configs — the cache never actually cached.
        if not rates_path.exists() or rates_path.stat().st_size:
            rates_path.write_text("")
        return rates_path
    # `needs_rebuild` here picks up the implicit taxjson.toml dependency
    # (via _CONFIG_PATH), so a change to base_currency or
    # source_currencies invalidates the cached rates file. Without
    # this, switching from CAD-base to USD-base silently reused the
    # old rates. The coverage check catches the inverse failure: an
    # mtime-fresh file whose data ends in the past.
    if (not needs_rebuild(rates_path)
            and not _rates_coverage_stale(rates_path, currencies=sources)):
        return rates_path
    had_previous = rates_path.exists() and rates_path.stat().st_size > 0
    parts: List[bytes] = []
    from taxjson.lib.offline import offline_enabled
    # Offline the helper reads its cache only: no download to announce.
    _fetch = ("Loading cached" if offline_enabled() else "Downloading")
    try:
        for src in sources:
            _step(f"{_fetch} {src} → {base} rates")
            parts.append(run_capture(_cmd("taxjson-to-base-curr") + [src, base]))
    except Exception as exc:
        # A refresh attempt (e.g. offline, yfinance hiccup) must not turn a
        # usable-if-aging rates file into a hard failure — but say so
        # loudly: rows past the file's coverage convert at --default-rate.
        if had_previous:
            _say("warning", f"FX rate refresh failed ({exc}); keeping the "
                 f"existing to_base.csv",
                 "Transactions dated after its coverage (beyond its last "
                 "rate and the look-back) have no rate and stop the "
                 "conversion — re-run online to refresh.", prog=_PROG)
            return rates_path
        raise
    # Atomic: to_base.csv is mtime-cached, so a kill mid-write must never
    # leave a fresh-looking empty/partial rates file (every later run would
    # silently fall back to the default FX rate).
    from taxjson.lib.safe_write import write_atomic
    write_atomic(rates_path, b"".join(parts))
    return rates_path


def _resolve_manifest(acct_dir: Path, cache: Path, name: str,
                      create: bool = False) -> Path:
    """The corp-action elections manifest for an account. Canonical home is
    `inputs/<account>/manifest.json` — elections and hand-typed FMV/ACB
    hints are user DECISIONS, the one thing that is NOT rebuildable from
    inputs, so they must not live in the disposable (gitignored,
    documented-as-safe-to-delete) work/ cache. A legacy
    `work/<account>_manifest.json` is migrated on first touch; with
    `create=True` a fresh empty manifest is written when neither exists."""
    user_manifest = acct_dir / "manifest.json"
    legacy = cache / f"{name}_manifest.json"
    if user_manifest.exists():
        return user_manifest
    if user_manifest.is_symlink():
        # A dangling link is not "no manifest": writing through it put
        # an empty {"elections": {}} at the link target (or crashed),
        # and the saved elections were silently gone (re-audit
        # A2-1400). The user's decisions are not rebuildable — refuse.
        import os as _os
        try:
            _tgt = _os.readlink(user_manifest)
        except OSError:
            _tgt = "?"
        _die_input(f"{user_manifest} is a symlink to {_tgt}, which does "
                   f"not exist (or loops) — it should hold your "
                   f"corporate-action elections. Fix the link (or remove "
                   f"it to start a new manifest).")
    if legacy.exists():
        acct_dir.mkdir(parents=True, exist_ok=True, mode=0o700)
        # Atomic (tmp + replace, as Manifest.save writes): a failed write
        # left a truncated canonical manifest that then won over the
        # intact legacy copy on every later run (A2-0218).
        from taxjson.lib.safe_write import write_atomic
        write_atomic(user_manifest, legacy.read_text(encoding="utf-8"))
        _say("note", f"migrated the elections manifest to "
             f"{user_manifest}",
             "Version-control this file; the work/ copy is no longer "
             "read once it exists.", file=sys.stdout)
        return user_manifest
    if create:
        acct_dir.mkdir(parents=True, exist_ok=True, mode=0o700)
        user_manifest.write_text('{"elections": {}}\n', encoding="utf-8")
        return user_manifest
    # Read-only callers (taxjson elect) on a project with no manifest yet:
    # report the canonical path; Manifest.load treats missing as empty.
    return user_manifest


def _locked_year_flags(root: Path, settings: Dict[str, Any]) -> List[str]:
    """`--locked-year Y` per filed-year lock (US projects; US-WASH-22)."""
    from taxjson.bin.taxjson_filed import locked_year_flags
    return locked_year_flags(root, settings)


def _lock_files(root: Path, settings: Dict[str, Any]) -> List[Path]:
    """The filed-year locks a US gains run depends on (US-WASH-22): a
    new or removed lock rebuilds the cached gains."""
    if _country(settings) not in ("us", "usa"):
        return []
    from taxjson.bin.taxjson_filed import project_locks
    try:
        return [p for _y, p, _w in project_locks(root, settings)]
    except ValueError:
        return []


def _wash_flags(is_taxable: bool, is_crypto: bool, country: str) -> List[str]:
    """Wash-detection flags for an account's gains run. US crypto gets
    --no-wash: the IRS treats digital assets as property, not "securities",
    so §1091 does not apply — running it denied legitimate crypto losses.
    Canada's superficial-loss rule covers any identical property, crypto
    included, so crypto stays wash-checked there."""
    if not is_taxable:
        return []
    flags = ["--taxable"]
    if is_crypto and country == "usa":
        flags.append("--no-wash")
    return flags


class PendingElectionsError(RuntimeError):
    """An account's corp-action events need elections and prompting
    isn't possible (--no-input or no TTY). Carries the pending-JSON
    path so the orchestrator can aggregate and exit 3 instead of
    crashing."""

    def __init__(self, account: str, pending_path: Path):
        super().__init__(f"{account}: elections required")
        self.account = account
        self.pending_path = pending_path


_SKIPPED_ACCOUNTS_FILE = "skipped_accounts.json"


def _record_skipped_accounts(cache: Path, names: List[str], *,
                             only: Optional[str] = None) -> None:
    """Persist which accounts `taxjson run` skipped for having no inputs
    (work/skipped_accounts.json), so later commands don't tell the user
    to "run `taxjson run` first" about an account that run deliberately
    skipped. A single-account run (`only`) updates just that entry."""
    import json as _json
    path = cache / _SKIPPED_ACCOUNTS_FILE
    keep = set()
    if only:
        try:
            keep = set(_json.loads(path.read_text(encoding="utf-8"))
                       .get("accounts") or []) - {only}
        except (OSError, ValueError, AttributeError):
            keep = set()
    names_all = sorted(keep | set(names))
    try:
        if names_all:
            cache.mkdir(parents=True, exist_ok=True, mode=0o700)
            path.write_text(_json.dumps({"schema_version": 1,
                                         "accounts": names_all},
                                        indent=2) + "\n",
                            encoding="utf-8")
        else:
            path.unlink(missing_ok=True)
    except OSError:
        pass                          # advisory only — never break a run


def _accounts_skipped_for_no_inputs(root: Path) -> set:
    """Accounts the last `taxjson run` skipped because inputs/<name>/
    held no CSV or .tt file — and that STILL hold none (a user who has
    since added files does need the "run `taxjson run` first" hint).
    Readers that warn about a missing work/<name>_* artifact should
    stay quiet for these: their absence is expected, not staleness."""
    import json as _json
    try:
        doc = _json.loads((root / "work" / _SKIPPED_ACCOUNTS_FILE)
                          .read_text(encoding="utf-8"))
        names = [str(n) for n in (doc.get("accounts") or [])]
    except (OSError, ValueError, AttributeError):
        return set()
    out = set()
    for n in names:
        d = root / "inputs" / n
        if not (input_files(d, ".csv") or input_files(d, ".tt")):
            out.add(n)
    return out


def _sheltered_expected(root: Path) -> bool:
    """Should work/sheltered_base.json exist? True when the config has
    a sheltered account that `taxjson run` did not skip for having no
    inputs — the "no sheltered_base.json" notes are noise otherwise."""
    _acfg = _soft_config(root).get("accounts") or {}
    skipped = _accounts_skipped_for_no_inputs(root)
    return any((c or {}).get("type") == "sheltered" and n not in skipped
               for n, c in _acfg.items())


def _crypto_broker_files(root: Path, cfg: Dict[str, Any]
                         ) -> Dict[str, List[Tuple[str, Path]]]:
    """{crypto account: [(broker, csv)]} — the raw exchange exports the
    stablecoin pool of `taxjson crypto-sends` is rebuilt from."""
    from taxjson.lib.crypto_sends import crypto_accounts
    out: Dict[str, List[Tuple[str, Path]]] = {}
    for acct in crypto_accounts(cfg):
        d = root / "inputs" / acct
        if d.is_dir():
            out[acct] = [(b, p) for b, ps in group_inputs(d).items()
                         for p in ps]
    return out


def _is_us(cfg: Dict[str, Any]) -> bool:
    return _country((cfg.get("settings") or {})) in ("us",
                                                                 "usa")


def _crypto_sends_tt(root: Path, acct: str, report: Dict[str, Any]
                     ) -> Tuple[str, List[Dict[str, Any]]]:
    """(Re)write inputs/<acct>/crypto_sends.tt from the report. Returns
    (write status, duplicate hand-written lines). Raises
    crypto_sends.RefusedDecision AFTER writing the file without them
    when a saved decision is one the country refuses (a US gift:
    partition SPEC-01/INPUTS-04), and crypto_sends.UnpricedSends AFTER
    writing the priced lines when a gift/payment or network fee cannot
    be priced (its ``dups`` carries the duplicate lines)."""
    from taxjson.lib import crypto_sends as CS
    adoc = report["accounts"][acct]
    entries, unpriced = CS.tt_entries(adoc)
    refused = CS.refused_entries(adoc)
    # Every priced entry is written on its own; one that cannot be
    # priced is reported AFTER the write (re-audit A2-0240: a single
    # unpriceable network fee used to hold back the owner's fully
    # priced gifts and payments, and left an old crypto_sends.tt).
    status = CS.write_tt(Path(adoc["tt_file"]),
                         CS.render_tt(acct, entries, report["country"]))
    if refused:
        raise CS.RefusedDecision(
            f"inputs/{acct}/{CS.MANIFEST_NAME}: "
            + "; ".join(e["refused"] for e in refused)
            + f" (inputs/{acct}/{CS.TT_NAME} {status} without it)")
    if unpriced:
        _fee = [e["id"] for e in unpriced if e.get("network_fee")]
        _dec = [e["id"] for e in unpriced if not e.get("network_fee")]
        _exc = CS.UnpricedSends(
            "no fair value for " + ", ".join(e["id"] for e in unpriced)
            + " (the price lookup failed or TAXJSON_OFFLINE is set and "
              "the price is not cached) — NOT booked. Re-run online, or "
              f"give the value per coin in {report['base_currency']}: "
            + "; ".join(
                ([f"`taxjson crypto-sends {acct} --set {i}="
                  f"{_disposing_word(report['country']).replace('/', '|')}"
                  f" --price P`" for i in _dec[:1]] if _dec else [])
                + ([f"`taxjson crypto-sends {acct} --set {i}=fee "
                    f"--price P` (the network fee hidden in a send that "
                    f"arrived short)" for i in _fee[:1]] if _fee else []))
            + f". inputs/{acct}/{CS.TT_NAME} {status} with the "
              f"{len(entries)} priced line(s).")
        _exc.dups = CS.duplicate_lines(root / "inputs" / acct, entries)
        _exc.status = status
        raise _exc
    return status, CS.duplicate_lines(root / "inputs" / acct, entries)


def _send_decisions(country: str) -> List[str]:
    """The crypto-sends decisions the project's country accepts (a US
    project refuses `gift`, lib/country COMMAND_COUNTRY
    "crypto-sends:gift"; US-SEND-02)."""
    from taxjson.lib import crypto_sends as CS
    return [d for d in CS.DECISIONS
            if command_country_problem("crypto-sends", country, d) is None]


def _disposing_word(country: str) -> str:
    """'gift/payment' in Canada, 'payment' in the US: the decisions that
    write a sale (audit A2-1283, A2-1285, A2-1329)."""
    from taxjson.lib import crypto_sends as CS
    return "/".join(d for d in _send_decisions(country)
                    if d in CS.DISPOSING)


def _dup_warning(acct: str, dups: List[Dict[str, Any]]) -> List[str]:
    """One line per hand-written .tt line that books a send the
    generated crypto_sends.tt also books — both file names, the send
    and its timestamp. Nothing is deleted: the owner picks the line."""
    from taxjson.lib import crypto_sends as CS
    out = []
    for d in dups:
        when = (d["timestamp"] if d["same_time"]
                else f"{d['timestamp'][:10]} (the hand-written line has "
                     f"another date or time, or a near quantity)")
        if d["id"].endswith("-fee"):
            out.append(
                f"{d['file']} line {d['line']} and inputs/{acct}/"
                f"{CS.TT_NAME} both sell {CS.fmt_qty(d['quantity'])} "
                f"{d['symbol']} on {when} (the network fee {d['id']}, "
                f"booked from the send that arrived short) — that "
                f"disposition is counted twice. Delete the hand-written "
                f"line.")
            continue
        out.append(
            f"{d['file']} line {d['line']} and inputs/{acct}/{CS.TT_NAME} "
            f"both sell {CS.fmt_qty(d['quantity'])} {d['symbol']} on "
            f"{when} (send {d['id']}) — that disposition is counted "
            f"twice. Delete the hand-written line (crypto_sends.tt is "
            f"generated from sends.json), or, to keep it, record the send "
            f"as `self`: `taxjson crypto-sends {acct} --set "
            f"{d['id']}=self`.")
    return out


def _transfers_accounts(cfg: Dict[str, Any]) -> List[str]:
    """Accounts with `transfers = true`: their TRANSFER rows are in the
    books, so they keep no transfer sidecar."""
    return [n for n, a in (cfg.get("accounts") or {}).items()
            if (a or {}).get("transfers")]


def _crypto_sends_problems(name: str, adoc: Dict[str, Any]) -> List[str]:
    """What the run must not book silently for crypto account `name`
    (each a WARNING; `run --strict` stops on any): a saved gift/payment
    the automatic pairing overrode (re-audit A2-0004). (A US move
    between two crypto accounts is carried by the blended crypto pass,
    US-CRYPTO-05 — no longer a problem, A2-0003.)"""
    out = []
    for o in adoc.get("overridden") or []:
        out.append(
            f"inputs/{name}/sends.json saves {o['id']} ({o['summary']}) as "
            f"`{o['decision']}`, but that send now pairs with an arrival "
            f"— {o['arrival']} — so it is booked as your own move and the "
            f"{o['decision']} is NOT booked. If that arrival is unrelated: "
            f"`taxjson crypto-sends {name} --set {o['id']}={o['decision']} "
            f"--unpair`; if the pairing is right: `taxjson crypto-sends "
            f"{name} --set {o['id']}=self`.")
    return out


def _stage_crypto_sends(root: Path, name: str, interactive: bool,
                        strict: bool = False) -> None:
    """`taxjson run` hook for a crypto account, right after the parse:
    prompt for undecided sends at a TTY (else one note line), then
    refresh the generated crypto_sends.tt from the saved decisions.

    What the books then lack or hold twice — a decided gift/payment
    that cannot be written (no fair value, a malformed sends.json), a
    hand-written .tt line that sells a send the generated file sells
    too — goes to work/<acct>_crypto_sends.diag (UNBOOKED / ATTENTION
    lines: the account .sum DIAGNOSTICS and the checklist's run-clean
    step read them), and `run --strict` stops on it and on an undecided
    send (A2-0112, A2-0127, A2-0362)."""
    from taxjson.lib import crypto_sends as CS
    cfg = _soft_config(root)
    cache = root / "work"
    _diag = cache / f"{name}_crypto_sends.diag"
    # Another crypto account not parsed yet, or parsed before its
    # export changed (a `run --account` subset): its arrivals are
    # unknown or stale, so a send to it would look like a gift. Don't
    # ask, and say so (re-audit A2-0077). A full run parses every
    # crypto account before this stage (cmd_run), so this is rare.
    files = _crypto_broker_files(root, cfg)
    unparsed = CS.stale_evidence(cache, files,
                                 skip=[name] + _transfers_accounts(cfg))
    # (prefix, message): UNBOOKED for a declared disposition the run
    # could not book, ATTENTION for the rest — written to
    # work/<acct>_crypto_sends.diag for the .sum and run-clean.
    _problems: List[Tuple[str, str]] = []
    _dups: List[str] = []
    # Said and kept in the .sum, but not a --strict stop: a coin priced
    # under its default Yahoo id while the price cache holds a numbered
    # id of its ticker (the CRYPTO line to add is in the message).
    _price_fn = CS.yahoo_usd_price(root)
    try:
        report = CS.build_report(root, cfg, files, _price_fn,
                                 want=name, exports_only=True)
        adoc = report["accounts"].get(name)
        if adoc is None:
            _diag.unlink(missing_ok=True)
            return
        if adoc["undecided"] and interactive and not unparsed:
            if CS.prompt_undecided(adoc["sends"], Path(adoc["manifest"]),
                                   allow_gift=command_country_problem(
                                       "crypto-sends",
                                       _country(cfg.get("settings")),
                                       "gift") is None):
                report = CS.build_report(root, cfg, files, _price_fn,
                                         want=name, exports_only=True)
                adoc = report["accounts"][name]
        if unparsed:
            _problems.append((ATTENTION_PREFIX,
                f"the transfer evidence of {'; '.join(unparsed)} is not "
                f"current, so a send to it may look unmatched (or a "
                f"network fee be missed) — run without --account."))
        if adoc["undecided"]:
            # A US donor's gift is not a sale (US-SEND-02; audit A2-0721,
            # A2-0740, A2-1286): the US note names payments only.
            _ctry = _country(cfg.get("settings"))
            _decs = " / ".join(_send_decisions(_ctry))
            _why = ("a payment is a sale at fair value; a gift is not a "
                    "sale for a US donor" if _ctry == "usa" else
                    "a gift or payment is a disposition at fair value")
            _say("note", f"{adoc['undecided']} crypto send(s) not yet "
                 f"classified as {_decs}",
                 f"`taxjson crypto-sends {name}` lists them ({_why}).",
                 indent="  ")
            if strict and not unparsed:
                # A pending decision, like a pending election: a send
                # that may be a disposition is not in the books (A2-0362).
                _diag.unlink(missing_ok=True)
                _die(f"--strict: {name}: {adoc['undecided']} crypto "
                     f"send(s) not yet classified as {_decs} — aborting",
                     f"Decide each with `taxjson crypto-sends {name} "
                     f"--set ID=...`.")
        if adoc.get("orphans"):
            _say("note", f"inputs/{name}/{CS.MANIFEST_NAME} has "
                 f"{len(adoc['orphans'])} decision(s) for send ids that "
                 f"no longer exist ({', '.join(adoc['orphans'][:3])}"
                 f"{' ...' if len(adoc['orphans']) > 3 else ''})",
                 f"The inputs or local_timezone changed? They are "
                 f"ignored; `taxjson crypto-sends {name}` lists the "
                 f"current ids.", indent="  ")
        _problems += [(ATTENTION_PREFIX, w)
                      for w in _crypto_sends_problems(name, adoc)]
        try:
            status, dups = _crypto_sends_tt(root, name, report)
        except CS.UnpricedSends as e:
            status, dups = getattr(e, "status", ""), getattr(e, "dups", [])
            # A declared disposition the run could not book (R1-104).
            _problems.append((UNBOOKED_PREFIX, str(e)))
        if status == "written":
            _step(f"Writing crypto sends inputs/{name}/{CS.TT_NAME}")
        elif status == "removed":
            _step(f"Removing crypto sends inputs/{name}/{CS.TT_NAME}")
        # Booked twice (A2-0127): --strict stops, the .sum says so.
        _dups = _dup_warning(name, dups)
    except CS.RefusedDecision as e:
        # A saved decision the country refuses (a US gift): not booked,
        # and the run stops until sends.json says what it was.
        _diag.unlink(missing_ok=True)
        _die(f"{name}: crypto sends: {e}")
    except ValueError as e:
        # A decided gift/payment that cannot be written is a missing
        # disposition: the .sum DIAGNOSTICS carries it (A2-0112).
        tt = root / "inputs" / name / CS.TT_NAME
        if tt.exists():
            # The old generated file was written from decisions that can
            # no longer be read: it may book a send since reclassified
            # (gift -> self), or a gift a US project refuses (US-SEND-02).
            # Booking it on a guess is worse than stopping (audit A2-0415).
            _diag.unlink(missing_ok=True)
            _die(f"{name}: crypto sends: {e}",
                 f"The generated inputs/{name}/{CS.TT_NAME} was written "
                 f"from the earlier decisions and is not booked on a "
                 f"guess — fix the cause above (the decisions are in "
                 f"inputs/{name}/{CS.MANIFEST_NAME}), or delete "
                 f"{CS.TT_NAME} to run without the decided sales, and "
                 f"run again.")
        msg = (f"{e} The decided gift(s)/payment(s) it names are NOT "
               f"booked"
               + (f"; the previous inputs/{name}/{CS.TT_NAME} is still "
                  f"booked as it was" if tt.exists() else "")
               + ". `run --strict` refuses this.")
        _problems.append((UNBOOKED_PREFIX, msg))
    for _p, w in _problems:
        _echo_captured(f"{_p} {name}: crypto sends: {w}", indent="",
                       file=sys.stderr)
    for w in _dups:
        _echo_captured(f"{ATTENTION_PREFIX} {w}", indent="",
                       file=sys.stderr)
    _problems += [(ATTENTION_PREFIX, w) for w in _dups]
    # (a stand-in price function, as in tests, has no .attention)
    _id_notes = [f"crypto id: {w}"
                 for w in getattr(_price_fn, "attention", ())]
    for w in _id_notes:
        _echo_captured(f"{ATTENTION_PREFIX} {name}: crypto sends: {w}",
                       indent="", file=sys.stderr)
    if _problems or _id_notes:
        _diag.write_text("".join(f"{p} {name}: crypto sends: {m}\n"
                                 for p, m in _problems + [
                                     (ATTENTION_PREFIX, w)
                                     for w in _id_notes]),
                         encoding="utf-8")
    else:
        _diag.unlink(missing_ok=True)
    if strict and _problems:
        _die(f"--strict: {name}: crypto sends: {len(_problems)} "
             f"problem(s) above would leave the books wrong — aborting")


def ib_foreign_roc_mode(settings: Dict[str, Any]) -> str:
    """How the IB parser books an issuer-designated '(Return of
    Capital)' from a non-Canadian issuer: lib/country.foreign_roc_mode
    (the one resolver `run` and tax-logic share). Canada: [settings]
    foreign_return_of_capital, default "dividend" (ITA s.90(1)). USA:
    always "acb" (IRC s.301(c)(2); the key is Canada-only and refused
    in a US project — audit S013-01, partition INPUTS-02)."""
    from taxjson.lib.country import CountryError, foreign_roc_mode
    _country(settings)
    try:
        return foreign_roc_mode(settings)
    except CountryError as e:
        _die(str(e))


def _apply_override_log(corp_json: Path, log: Path, account: str) -> None:
    """Rename corp-action rows the way the security overrides renamed
    the same broker's parsed rows ((symbol, currency) -> new symbol).
    A pair the overrides renamed for some rows and not others is
    ambiguous (two securities share the broker's spelling): a corporate
    action on it is refused rather than booked on a guess."""
    import json as _json
    if not log.exists() or not corp_json.exists():
        return
    try:
        doc = _json.loads(log.read_text(encoding="utf-8"))
        corp = _json.loads(corp_json.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return
    renamed = {k: v for k, v in (doc.get("renamed") or {}).items() if v}
    kept = set(doc.get("kept") or [])
    if not renamed:
        return
    changed = False
    for t in corp.get("transactions", []) or []:
        cur = str(t.get("currency") or "").upper()
        for fld in ("symbol", "symbol_new"):
            sym = t.get(fld) or ""
            key = f"{sym}|{cur}"
            if key not in renamed:
                continue
            targets = renamed[key]
            if len(targets) > 1 or key in kept:
                _die(f"{account}: a corporate action on {sym} ({cur}), "
                     f"but a ticker.map EXTRACT line renames some "
                     f"{sym} rows (to {', '.join(targets)}) and not "
                     f"others — two securities share that spelling, so "
                     f"the event cannot be assigned. Record it with a "
                     f".tt file (and `taxjson elect {account} --set "
                     f"<event>=ignore`).")
            t[fld] = targets[0]
            changed = True
    if changed:
        from taxjson.lib.safe_write import write_atomic
        write_atomic(corp_json,
                     _json.dumps(corp, indent=2, sort_keys=True) + "\n")


def _config_has_distributions() -> bool:
    """True when the project's taxjson.toml has [[distributions]]
    entries (checked by every config reader — lib/project_tables)."""
    if _CONFIG_PATH is None or not _CONFIG_PATH.is_file():
        return False
    try:
        return bool(tomllib.loads(_read_config_text(_CONFIG_PATH))
                    .get("distributions"))
    except Exception:                               # noqa: BLE001
        return False


# Project-root files the per-account stages read (their content is part
# of each account's input fingerprint; taxjson.toml is added there too).
_PROJECT_ROOT_INPUTS = ("ticker.map", "missing_history.json",
                        "phantoms.json")
# phantoms.json: the old name of missing_history.json, still read (one
# NOTE per run asks to rename it; lib/missing_history).


def _is_empty_manifest(path: Path) -> bool:
    """An elections manifest with no elections — the file the corp stage
    creates on an account's first run — is the same as none, so its
    appearance does not invalidate the --fast cache."""
    import json as _json
    try:
        return _json.loads(path.read_text(encoding="utf-8")) == {
            "elections": {}}
    except (OSError, ValueError):
        return False


def _unreadable_project_inputs(root: Path) -> List[str]:
    """Project-root input names that exist as a symlink whose target is
    missing (or loops), or as a directory — never "absent" (A2-0313)."""
    import os
    out = []
    for name in _PROJECT_ROOT_INPUTS:
        p = root / name
        if p.is_symlink() and not p.exists():
            try:
                tgt = os.readlink(p)
            except OSError:
                tgt = "?"
            out.append(f"{name} is a symlink to {tgt}, which does not "
                       f"exist (or loops)")
        elif p.is_dir():
            out.append(f"{name} is a directory, not a file")
    return out


def _refuse_legacy_project_files(root: Path) -> None:
    """Stop (exit 2) while the project still holds an old per-purpose
    file whose contents now live in ticker.map / taxjson.toml
    (yf_ticker.map, distributions.map, ...): it is no longer read, and
    running on without it would silently drop its rules. Only `taxjson
    migrate` (which moves them) runs past this."""
    from taxjson.lib.migrate import legacy_files, legacy_message
    names = legacy_files(root)
    if names:
        _die_input(legacy_message(names))


def cmd_migrate(args: argparse.Namespace) -> None:
    """`taxjson migrate [--dry-run]`: move an old project's per-purpose
    files into ticker.map (QUOTE / CRYPTO / EXTRACT / T1135 lines) and
    taxjson.toml ([estimate] amt_carryover, [carryover] claimed,
    [[capital_gains_dividends]], [[distributions]]) — appended, never
    rewritten — and rename each old file to <name>.migrated. A leftover
    tv_exchange.map (the removed TradingView export) is only renamed.
    Refuses (exit 2, nothing written) when a file cannot be converted or
    the target already holds a conflicting entry."""
    from taxjson.lib import migrate as M
    root = Path(args.dir).resolve()
    try:
        pl = M.plan(root)
    except M.MigrateError as e:
        _die_input(str(e), "Nothing was changed.")
    if not pl.names:
        print("taxjson migrate: nothing to migrate in this project")
        for _ln in _out_wrap(f"None of {', '.join(M.LEGACY_FILES)} is "
                             f"here.", indent="  "):
            print(_ln)
        return
    dry = bool(getattr(args, "dry_run", False))
    print(f"taxjson migrate{' --dry-run' if dry else ''}: {root}")
    from taxjson.lib.out import labelled as _labelled
    for ln in pl.summary(dry):
        for _ln in _out_wrap(_labelled(ln), indent="  ", hang="    "):
            print(_ln)
    if dry:
        if pl.map_append:
            print("\n  would append to ticker.map:")
            for ln in pl.map_append.strip("\n").splitlines():
                print(f"    {ln}")
        if pl.toml_text is not None:
            import difflib
            print("\n  would change taxjson.toml:")
            for ln in difflib.unified_diff(
                    pl.toml_before.splitlines(), pl.toml_text.splitlines(),
                    "taxjson.toml", "taxjson.toml (migrated)", lineterm="",
                    n=1):
                print(f"    {ln}")
        print("\n  dry run: nothing was written")
        return
    try:
        M.apply(pl)
    except OSError as e:
        _die_input(f"could not write the migration: {e}")
    print("\nDone.")
    for _ln in _out_wrap(
            "Review ticker.map and taxjson.toml and commit them (in a git "
            "repository, `git rm` the old files too); delete the "
            "*.migrated files once you are satisfied; run `taxjson run` to "
            "rebuild.", indent="  "):
        print(_ln)


def _refuse_unreadable_project_inputs(root: Path) -> None:
    """Die when a project-root input exists as a name but cannot be read.
    Every config reader calls it, so no command (scan, sanity, harvest,
    fees, ...) builds as if ticker.map or missing_history.json were
    absent (re-audit A2-0401 / A2-0144; `run` since A2-0313). Also
    refuses a project holding both missing_history.json and its old
    name phantoms.json (which one is current cannot be guessed), and
    says once per run that a lone phantoms.json should be renamed."""
    _refuse_legacy_project_files(root)
    _missing_history_path(root)
    _unreadable = _unreadable_project_inputs(root)
    if _unreadable:
        # exit 2: inputs that cannot be read (re-audit A2-0164, A2-1438)
        _die_input("project file(s) that exist but cannot be read — fix or "
             "remove each; nothing was run:\n    "
             + "\n    ".join(_unreadable))


def _inputs_fingerprint(paths: List[Path]) -> str:
    """One line per existing file: name, size and SHA-256 of the
    content (mtimes deliberately left out — see R1-253)."""
    lines = []
    for p in sorted(set(paths), key=str):
        try:
            data = p.read_bytes()
        except OSError:
            continue
        # The legacy phantoms.json is keyed by its new name: renaming
        # it (same content) is not an input change.
        _n = ("missing_history.json" if p.name == "phantoms.json"
              else p.name)
        lines.append(f"{_n} {len(data)} "
                     f"{hashlib.sha256(data).hexdigest()}")
    return "\n".join(lines) + "\n"


def stage_account(name: str, acfg: Dict[str, Any], settings: Dict[str, Any],
                  inputs_dir: Path, cache: Path, reports_dir: Path,
                  rates: Path, ticker_map: Optional[Path],
                  security_overrides: Optional[Path],
                  force: bool,
                  incomplete_history: Optional[Path] = None,
                  no_input: bool = False,
                  strict: bool = False,
                  parse_only: bool = False,
                  ) -> Optional[Dict[str, Path]]:
    """Full per-account pipeline. Returns {base, gains, sum} paths, or None
    when the account has no inputs yet (a configured-but-unpopulated account,
    e.g. straight after `taxjson init`) — that's a warn-and-skip, not a fatal
    error, so the other accounts still run. `parse_only`: stop after the
    broker parse (returns None) — cmd_run parses every crypto account
    first so each one's sends pair against current arrivals."""
    acct_dir = inputs_dir / name
    if not acct_dir.exists():
        # Once per run: the first pass stages the account too.
        _say_once(("no-dir", name), "warning",
                  f"no inputs dir for account '{name}' (inputs/{name}); "
                  f"skipping", prog=_PROG)
        return None

    base_currency = settings["base_currency"]
    country = _normalize_country(settings["country"])
    year = settings["year"]
    # Country-aware default: CRA times dispositions on SETTLEMENT date;
    # the IRS recognizes on the TRADE date. An explicit config wins.
    tax_date = _tax_date(settings)
    is_crypto = acfg.get("crypto", False)
    is_taxable = acfg.get("type", "sheltered") == "taxable"
    include_transfers = acfg.get("transfers", False)

    _grouped_raw, _detected = group_inputs_detailed(acct_dir)
    grouped = _split_generic_groups(_grouped_raw)
    if not grouped and not input_files(acct_dir, ".tt"):
        # Say why a folder holding only a positions report has no books.
        _pos_only = [d for d in _detected if d.positions]
        if _pos_only:
            _report_detection(name, _pos_only, cache)
        _details = []
        if (cache / f"{name}_base.json").exists():
            # Inputs emptied but artifacts persist: every aggregate
            # keeps counting the account's OLD books with only this
            # line as the signal (2026-09 audit).
            _details.append(
                f"Its work/ artifacts from previous runs STILL EXIST and "
                f"are still counted by sum/fees/reports — delete "
                f"work/{name}_* and reports/{name}* if the account is "
                f"truly gone.")
        _say_once(("no-inputs", name),
                  "warning", f"no CSVs or .tt files in inputs/{name}; "
                  f"skipping account '{name}'", *_details, prog=_PROG)
        return None
    # Path-selection cross-check (KNOWN_ISSUES "crypto-vs-equity path"):
    # the pipeline split keys on the account's `crypto` flag alone, so a
    # kr_/cb_ file dropped into an equity account was routed through the
    # equity path (no fill-crypto → $0 FMVs) and an equity CSV in a
    # crypto account went through merge (no ticker-map/corp-actions) —
    # both silently. A mismatch is always a config or filing error;
    # refuse loudly.
    _CRYPTO_BROKERS = {"coinbase", "kraken"}
    _mismatched = ({b for b in grouped if b in _CRYPTO_BROKERS}
                   if not is_crypto else
                   {b for b in grouped if b not in _CRYPTO_BROKERS})
    if _mismatched:
        flag = "crypto = true" if is_crypto else "no crypto flag"
        _how = {d.path: d.reason for d in _detected}
        from taxjson.lib.out import one_line as _one_line
        _which = ", ".join(f"inputs/{name}/{_one_line(p.name)} "
                           f"({b}: {_how.get(p, '?')})"
                           for b in sorted(_mismatched)
                           for p in grouped[b])
        _die(f"account '{name}' has {flag} in taxjson.toml but its inputs "
             f"contain {', '.join(sorted(_mismatched))} files",
             f"The {'equity' if is_crypto else 'crypto'} data would be "
             f"routed through the wrong pipeline: {_which}.",
             "Move the files to an account of the matching type, or fix "
             "the account's `crypto` flag.")
    # .tt-only accounts (hand-maintained records — the documented .tt
    # use case) used to be skipped here with a misleading "no CSVs"
    # warning before the .tt conversion stage ever ran: the whole book
    # silently vanished from every report at exit 0 (REVIEW #20).

    cache.mkdir(parents=True, exist_ok=True, mode=0o700)
    _kind = (f"{'taxable' if is_taxable else 'sheltered'}"
             f"{', crypto' if is_crypto else ''}")
    if parse_only:
        # Read first so moves between your accounts pair across them.
        _step(f"{name}  ({_kind}, first pass: "
              f"{'sends' if is_crypto else 'transfers'} between your "
              f"accounts)")
    else:
        _step(f"{name}  ({_kind})")
    # How each input CSV was routed: one line per file (owner request —
    # detection must be visible, never a silent file-name guess).
    _report_detection(name, _detected, cache)

    # Deletion-blindness guard (FUZZ #J): mtime deps only cover files
    # that EXIST — deleting an input CSV left its trades in the cached
    # books under --fast (the broker group's parsed JSON looked fresh
    # against the remaining, older CSVs). Persist the account's input
    # membership; add/remove bumps the manifest's mtime and re-runs the
    # parse + merge. Content-compare first so an unchanged listing
    # never dirties the cache.
    src_manifest = cache / f"{name}_sources.list"
    # Parser option (IB foreign ROC): in the manifest so a toggle re-parses.
    _froc_acb = ib_foreign_roc_mode(settings) == "acb"
    from taxjson.lib.country import futures_settle_mode
    _fut_next = futures_settle_mode(settings) == "next_day"
    # Membership covers EVERY input kind that feeds the merge — CSVs and
    # .tt files alike. Listing only CSVs left a deleted .tt's
    # transactions in the cached books under --fast (its converted JSON
    # dropped out of `sources`, so the merge output looked fresh against
    # every remaining dep).
    _map_entries = []
    for _c in _generic_files(grouped):
        _sc = _c.with_name(_c.name + ".toml")
        _m = _sc if _sc.exists() else _c.parent / "generic.toml"
        # Record WHICH mapping is effective per file: deleting a
        # sidecar switches the file to the shared mapping without any
        # surviving dep getting newer — the FUZZ #J deletion-blindness
        # class, closed here by making the resolution part of the
        # manifest content.
        _map_entries.append(f"map/{_c.name}={_m.name if _m.exists() else '-'}")
    src_txt = "\n".join(sorted(
        [f"{broker}/{p.name}" for broker, csvs in grouped.items()
         for p in csvs]
        + [f"tt/{p.name}" for p in input_files(acct_dir, ".tt")]
        + _map_entries
        + (["setting/foreign_return_of_capital=acb"] if _froc_acb else [])
        + (["setting/futures_settle=next_day"] if _fut_next else [])
        # Income dating overrides move ROC dates (the ACB) and income
        # years: a change re-runs the books.
        + [f"setting/income_dating={' '.join(income_dating_flags(settings))}"]
        * bool(income_dating_flags(settings))
        # The crypto parsers date UTC stamps in this zone: a change
        # re-parses.
        + ([f"setting/local_timezone={settings['local_timezone']}"]
           if is_crypto and settings.get("local_timezone") else [])
        # Moves between your own accounts (US-BASIS-05): the legs file
        # going away must rebuild the books.
        + ([f"moves/{name}{OWN_MOVES_SUFFIX}"]
           if (cache / f"{name}{OWN_MOVES_SUFFIX}").is_file() else []))) \
        + "\n"
    if _read_work_stamp(src_manifest) != src_txt:
        _write_work_stamp(src_manifest, src_txt)
    # Content, not just membership: `run --fast` compared mtimes only,
    # so a CSV replaced by a corrected export carrying an OLDER mtime
    # (cp -p, rsync -a, unzip) — or a ticker.map restored the same way
    # — kept the previous parse at exit 0 (R1-253, R1-294). A digest of
    # every input and project-root map file; when it changes, the
    # sources manifest (a dep of every parse/corp/merge stage) is
    # touched so the rebuild cascades.
    _fp_file = cache / f"{name}_inputs.fingerprint"
    _fp_txt = _inputs_fingerprint(
        [p for csvs in grouped.values() for p in csvs]
        + list(input_files(acct_dir, ".tt"))
        + [_c.with_name(_c.name + ".toml")
           for _c in _generic_files(grouped)]
        + [acct_dir / "generic.toml"]
        + [inputs_dir.parent / _m for _m in _PROJECT_ROOT_INPUTS]
        # The elections manifest (and its legacy work/ copy), a crypto
        # account's sends.json and taxjson.toml itself change the books
        # too: restored with an older mtime they kept the previous
        # election / setting under --fast (A2-0224, A2-0985, A2-1229).
        + [_m for _m in (acct_dir / "manifest.json",
                         cache / f"{name}_manifest.json")
           if not _is_empty_manifest(_m)]
        + [acct_dir / "sends.json"]
        + ([_CONFIG_PATH] if _CONFIG_PATH is not None else []))
    if _read_work_stamp(_fp_file) != _fp_txt:
        _write_work_stamp(_fp_file, _fp_txt)
        import os as _os
        _os.utime(src_manifest)

    # 1. brokerage parse per broker. Questrade last: its internal symbol
    # codes are resolved from the other exports' transfers and names
    # (stage_symbol_codes), this account's included.
    _parsed_by: Dict[str, Path] = {}
    _codes_state = cache / f"{name}{_symbol_codes_suffix()}"
    if "questrade" not in grouped or is_crypto:
        _codes_state.unlink(missing_ok=True)
    from taxjson.lib import listing_suffix as _LS
    for _b in _LS.CURRENCY_SUFFIX_BROKERS:
        if _b not in grouped or is_crypto:
            _LS.state_path(cache, name, _b).unlink(missing_ok=True)
    # A broker that names a listing from the row currency alone (lib/
    # listing_suffix) after the ones that name it: its listings are
    # read from their rows (stage_listing_suffix).
    for broker, csvs in sorted(grouped.items(),
                               key=lambda kv: (kv[0] in
                                               _LS.CURRENCY_SUFFIX_BROKERS,
                                               kv[0] == "questrade")):
        out = cache / f"{name}_{broker}.json"
        # ticker_map dep: a parser's identity hint the map now answers
        # is dropped (taxjson-brokerage --ticker-map, A2-1056).
        deps = (list(csvs) + [src_manifest]
                + ([security_overrides] if security_overrides else [])
                + ([ticker_map] if ticker_map else []))
        _codes_args: List[str] = []
        if broker == "questrade" and not is_crypto:
            # Rewritten only when the inference changes: a dep.
            stage_symbol_codes(name, csvs, inputs_dir.parent, cache,
                               _codes_state)
            deps.append(_codes_state)
            _codes_args = ["--symbol-codes", str(_codes_state)]
        if broker == "ib" and not is_crypto:
            # The project's other IB accounts: a one-contract-id ticker
            # change is dated from all of them (review 2 #4); their
            # statements are deps.
            _ibp, _ibp_deps = stage_ib_project(name, inputs_dir.parent,
                                               cache)
            deps += [_ibp] + _ibp_deps
            if _ibp_deps:
                _codes_args += ["--project-statements", str(_ibp)]
        if broker in _LS.CURRENCY_SUFFIX_BROKERS and not is_crypto:
            # The listings read from the evidence (a dep, rewritten only
            # when they change).
            _ls_state = stage_listing_suffix(name, broker, csvs,
                                             inputs_dir.parent, cache)
            deps.append(_ls_state)
            _codes_args += ["--listing-fixes", str(_ls_state)]
        if _is_generic_group(broker):
            # A mapping edit must rebuild the parse like a CSV edit.
            for _c in csvs:
                _sc = _c.with_name(_c.name + ".toml")
                _m = _sc if _sc.exists() else _c.parent / "generic.toml"
                if _m.exists():
                    deps.append(_m)
        if force or needs_rebuild(out, *deps):
            # --strict: a schema ERROR (negative trade net, zero split
            # ratio, a notional that contradicts the row's declared
            # contract multiplier ...) stops the run instead of
            # scrolling past as a warning into the filed numbers.
            cmd = _cmd("taxjson-brokerage") + ["--account", name,
                                               "--brokerage",
                                               "generic"
                                               if _is_generic_group(broker)
                                               else broker,
                                               "--strict",
                                               "--account-type",
                                               "taxable" if is_taxable
                                               else "sheltered"]
            cmd += _brokerage_account_flags(acfg)
            # Always explicit: the parser's own default is the neutral
            # cost reduction; s.90(1) is the Canadian project's choice
            # (partition INPUTS-03).
            cmd += ["--country", country, "--foreign-roc",
                    "acb" if _froc_acb else "dividend"]
            if _fut_next:
                cmd += ["--futures-settle", "next_day"]
            if isinstance(year, int):
                # An export's own timestamp vs the year (RBC "as of",
                # S063-22).
                cmd += ["--tax-year", str(year)]
            if ticker_map:
                cmd += ["--ticker-map", str(ticker_map)]
            cmd += _codes_args
            if rates and Path(rates).is_file() and Path(rates).stat().st_size:
                # A stablecoin fill valued in CAD/EUR is checked against
                # the peg through these rates (A2-0590; a warning only,
                # so not a rebuild dep).
                cmd += ["--rates", str(rates)]
            _sidecar = out.with_name(out.stem + "_transfers.json")
            if include_transfers:
                cmd.append("--transfers")
            else:
                # Custody evidence sidecar: excluded TRANSFER rows are
                # kept queryable (`taxjson transfers`) instead of
                # silently deleted — a depot flip or broker migration
                # is exactly what explains a confusing position later.
                cmd += ["--transfers-out", str(_sidecar)]
            if security_overrides:
                cmd += ["--security-overrides", str(security_overrides),
                        "--override-log",
                        str(out.with_name(out.stem + ".overrides"))]
            cmd += [str(p) for p in csvs]
            # The first pass (transfers / sends between your accounts)
            # parsed this account in this run: the same command over
            # the same bytes is the same parse — taken as it is, its
            # messages already shown under the first pass.
            _reads = _parse_reads(
                cmd, acct_dir,
                [d for d in deps if d != src_manifest]
                + ([Path(rates)] if rates else [])
                + ([security_overrides] if security_overrides else []))
            if not _reused_parse(out, _reads):
                from taxjson.lib.brokerages.detect import DISPLAY_NAMES
                _step(f"Reading {len(csvs)} "
                      + (f"{DISPLAY_NAMES.get(broker, broker)} "
                         if len(grouped) > 1 else "")
                      + ("file" if len(csvs) == 1 else "files"))
                if include_transfers:
                    # transfers=false -> true toggle: a stale sidecar
                    # would be consumed ALONGSIDE the now-in-book rows
                    # (double-counted by the transfers view and the
                    # holdings evidence flips) — round-five audit.
                    _sidecar.unlink(missing_ok=True)
                if not security_overrides:
                    out.with_name(out.stem + ".overrides").unlink(
                        missing_ok=True)
                _PARSED_THIS_RUN.pop(out, None)
                run_to_file(cmd, out)
                _PARSED_THIS_RUN[out] = (_reads, _parse_outputs(out))
                # Surface per-file transaction counts (and any 0-tx
                # warnings) inline so the user can sanity-check at a
                # glance that each CSV contributed the expected number
                # of rows.
                echo_parse_stats(out, csvs)
        # Outside the rebuild branch on purpose: `run --strict --fast`
        # on a cached parse must hit the same gate.
        if strict and unbooked_lines(out):
            _die(f"--strict: {name}: {broker} input has event(s) the "
                 f"parser could not book — aborting",
                 f"See the UNBOOKED warning above (also in "
                 f"work/{out.name}.diag).")
        _parsed_by[broker] = out
    # The sources keep the folder's broker order.
    parsed: List[Path] = [_parsed_by[b] for b in grouped]

    # A non-empty export that parsed to 0 transactions (a renamed
    # header, a kr_-named file that is not a Kraken ledger) drops that
    # whole file from the books. Read from the persisted .diag on EVERY
    # run — cached or not — so the console warning and the --strict
    # gate cannot be skipped by a warm cache (R1-247).
    _empty_files: List[str] = []
    for _out in parsed:
        _d = _out.with_name(_out.name + ".diag")
        try:
            _lines = _d.read_text(errors="replace").splitlines()
        except OSError:
            continue
        for _ln in _lines:
            _m = _ZERO_TX_RE.match(_ln.strip())
            if _m:
                _empty_files.append(_m.group(1))
    if _empty_files:
        _which = ", ".join(f"inputs/{name}/{f}" for f in _empty_files)
        if strict:
            _die(f"--strict: {name}: {_which} parsed to 0 transactions",
                 "Every row in it would be missing from the books. Check "
                 "the file's header/format (or its name: cb_/kr_/"
                 "coinbase/kraken route it to a crypto parser), or remove "
                 "it from inputs/.")
        for _f in _empty_files:
            # Once per run: the first pass reads the account too.
            _say_once(("empty", name, _f), "warning",
                      f"{name}: inputs/{name}/{_f} parsed to 0 "
                      f"transactions — NONE of its rows are in the books",
                      "Check the file's header/format (or its name: cb_/"
                      "kr_/coinbase/kraken route it to a crypto parser); "
                      "`run --strict` refuses this.", prog=_PROG)

    if parse_only:
        # The transfer evidence of an export REMOVED from inputs/ must
        # not pair or book anything in this run (re-audit A2-1026; the
        # sweep below removes the rest of its artifacts).
        for _b in ("kraken", "coinbase"):
            _side = cache / f"{name}_{_b}_transfers.json"
            if _b not in grouped and _side.exists():
                _side.unlink()
                _say("note", f"removed stale work/{_side.name} (its input "
                     f"files are gone)", indent="  ", file=sys.stdout)
        return None

    # 1a. Two listings of one security joined by their transfer journal
    # (CA-XLIST-01 / US-XLIST-01): from here on the account's stages
    # read the effective map (ticker.map plus the joins' TOBASE lines).
    if not is_crypto:
        ticker_map = stage_cross_listings(name, settings, cache, ticker_map)
    elif _dated_effective_lines(cache):
        # A ticker change declared in a .tt file (a coin's new ticker)
        # reaches the crypto books through the effective map too.
        ticker_map = stage_cross_listings(name, settings, cache, ticker_map)

    # 1b. crypto sends: an outgoing transfer that never arrived on
    # another exchange is a gift, a payment, or a move to your own
    # wallet — only the owner knows. Ask at a TTY, then (re)generate
    # inputs/<acct>/crypto_sends.tt BEFORE the .tt stage below reads
    # the account's .tt files, so the decisions book in this run.
    if is_crypto and not include_transfers:
        _stage_crypto_sends(inputs_dir.parent, name,
                            interactive=not (no_input
                                             or not sys.stdin.isatty()),
                            strict=strict)

    # 2. corp-actions per equity broker. taxjson-corp-actions requires
    # --manifest when multiple CSVs are passed, so always provide one.
    corp_files: List[Path] = []
    corp_brokers = sorted(b for b in grouped if b in CORP_ACTION_BROKERS)
    if not is_crypto and corp_brokers and not _country_has_corp_rules(country):
        # No election rules for this jurisdiction, so the stage below is
        # skipped — but broker parsers (RBC in particular) still SKIP
        # merger/CIL rows on the assumption that corp-actions consumes
        # them. With neither owner, those share movements would silently
        # vanish from the books. Say so loudly.
        _say("warning", f"country={country!r} has no corp-action "
             f"election rules — merger/reorg rows in "
             f"{', '.join(corp_brokers)} files for account {name!r} are "
             f"NOT processed",
             "RBC merger rows are skipped by the parser, so any "
             "reorganization's share movements will be MISSING from this "
             "account's books; record them manually via a .tt file.",
             prog=_PROG)
    if not is_crypto and _country_has_corp_rules(country):
        manifest_path = _resolve_manifest(acct_dir, cache, name, create=True)
        _corp_step = False
        for broker, csvs in grouped.items():
            if broker not in CORP_ACTION_BROKERS:
                continue
            out = cache / f"{name}_{broker}_corp.json"
            # src_manifest dep: deleting a CSV must dirty the corp
            # stage too, or its rows from the deleted file live on
            # (2026-09 audit — the parse/merge stages had this dep,
            # the corp stage was missed).
            # rates dep: a cross-currency exchange's legs are valued
            # at the event-date rate (one fair value for both legs).
            # ticker_map dep: a temporary code the map now renames is
            # no longer warned about (S072-03).
            # symbol-codes dep (Questrade): a chain under an internal
            # code books under the listing that record resolves it to
            # (GitHub issue #4).
            _corp_codes = (_codes_state if broker == "questrade"
                           and _codes_state.exists() else None)
            if force or needs_rebuild(out, *csvs, manifest_path,
                                      src_manifest, rates,
                                      *([ticker_map] if ticker_map
                                        else []),
                                      *([_corp_codes] if _corp_codes
                                        else [])):
                if not _corp_step:
                    _step("Processing corporate actions")
                    _corp_step = True
                cmd = _cmd("taxjson-corp-actions") + [
                    "--account-name", name,
                    "--country", country,
                    "--brokerage", broker,
                    "--manifest", str(manifest_path),
                    "--rates", str(rates),
                    "--base-currency", base_currency,
                ] + (["--ticker-map", str(ticker_map)] if ticker_map
                     else []) + (["--symbol-codes", str(_corp_codes)]
                                 if _corp_codes else []) + (
                    # Asked all the same; the prompt says no tax
                    # depends on it.
                    [] if is_taxable else ["--sheltered"])
                # Interactive by default: corp-actions prompts for the tax
                # election (taxable vs rollover) on stderr and reads the
                # answer from stdin. Without a TTY (or with --no-input) it
                # writes the pending elections as JSON and exits 3 — the
                # GUI/headless path: resolve via `taxjson elect --set`,
                # re-run.
                non_interactive = no_input or not sys.stdin.isatty()
                pending_path = cache / f"{name}_pending_elections.json"
                if non_interactive:
                    cmd += ["--no-input",
                            "--pending-json", str(pending_path)]
                cmd += [str(p) for p in csvs]
                pending_path.unlink(missing_ok=True)   # stale from last run
                try:
                    run_to_file(cmd, out,
                                interactive=not non_interactive)
                except subprocess.CalledProcessError as e:
                    if e.returncode == 3 and pending_path.exists():
                        raise PendingElectionsError(name, pending_path)
                    raise
            # ticker.map EXTRACT lines renamed this broker's
            # trade rows; the corp-action rows of the same security must
            # follow, or a merger consumed an empty un-overridden pool
            # while the real position stayed put (S004-00).
            _apply_override_log(out, cache / f"{name}_{broker}.overrides",
                                name)
            # The corp stage's own UNBOOKED lines (a Questrade DIS chain
            # that nets a removal, a lapse it cannot book) follow the
            # parse stage's contract: echoed on every run, refused by
            # --strict. They used to reach only the .diag and the .sum
            # (A2-0211, the S015-02 twin).
            for _ln in unbooked_lines(out):
                _echo_captured(_ln)
            if strict and unbooked_lines(out):
                _die(f"--strict: {name}: {broker} corporate actions hold "
                     f"event(s) taxjson could not book — aborting",
                     f"See the UNBOOKED warning above (also in "
                     f"work/{out.name}.diag).")
            corp_files.append(out)
        _warn_zero_value_spinoffs(name, is_taxable, corp_files, cache)

    # 3. starting-position .tt files. Their converted JSON lives in its
    # own `<acct>_tt_<stem>` namespace: `<acct>_<stem>` collided with
    # the broker parse (`questrade.tt` overwrote <acct>_questrade.json,
    # silently dropping every CSV trade) and with pipeline
    # intermediates like <acct>_base.json (R1-116).
    tt_jsons: List[Path] = []
    from taxjson.lib.config_check import RESERVED_NAME_SUFFIXES
    # Two .tt files whose names differ only in the suffix's case
    # (start.tt / start.TT) convert to ONE work file: the second
    # overwrote the first and its trades vanished (re-audit A2-0399).
    _tt_by_out: Dict[str, str] = {}
    for tt in input_files(acct_dir, ".tt"):
        _o = tt_json_path(cache, name, tt.name).name
        if _o in _tt_by_out:
            _die(f"inputs/{name}/{_tt_by_out[_o]} and inputs/{name}/"
                 f"{tt.name} convert to the same work file ({_o})",
                 "One would overwrite the other's rows. Rename one (or "
                 "merge the two).")
        _tt_by_out[_o] = tt.name
    for tt in input_files(acct_dir, ".tt"):
        _stem = tt.stem.lower()
        _clash = next((x for x in RESERVED_NAME_SUFFIXES
                       if _stem.endswith(x)), None)
        if _clash:
            # work/<acct>_tt_msft_gains.json read as the gains book of a
            # spurious account "<acct>_tt_msft" in `sum`, its fees counted
            # twice (S037-15): the artifact roles come from file names.
            _die(f"inputs/{name}/{tt.name}: a .tt file name may not end "
                 f"in {_clash!r}",
                 "Its converted JSON would read as a pipeline artifact (a "
                 "spurious extra account in the reports). Rename it, e.g. "
                 f"{tt.stem[:-len(_clash)] + _clash.replace('_', '-')}.tt")
        out = tt_json_path(cache, name, tt.name)
        if force or needs_rebuild(out, tt, src_manifest):
            # The name as the .tt warnings name it (_echo_tt_totals).
            from taxjson.lib.brokerages.base import shown_name as _shown
            _step(f"Reading {_shown(tt)}")
            run_to_file(_cmd("taxjson-convert-tt") + ["--account-name", name, str(tt)],
                        out)
        # A line whose total is not its qty x price +/- fee: the total is
        # booked as written. Read from the persisted .diag on EVERY run,
        # cached or not (as the 0-transaction check), shown on the
        # console and refused by --strict (QA F2: the warning reached only
        # the .sum DIAGNOSTICS).
        _echo_tt_totals(name, tt, out, strict)
        tt_jsons.append(out)

    # Broker groups REMOVED from inputs/: their parsed JSON, .diag and
    # corp files would otherwise persist forever — stale .diag lines in
    # every .sum, dead fees counted by `taxjson-fees-sum --cache`, dead
    # sources fed to the audit (2026-09 audit).
    _present = {f"{name}_{b}" for b in grouped} \
        | {f"{name}_{b}_corp" for b in grouped} \
        | ({f"{name}_{b}_transfers" for b in grouped}
           if not include_transfers else set()) \
        | {tt_json_path(cache, name, tt.name).stem
           for tt in input_files(acct_dir, ".tt")} \
        | {f"{name}_tt-journal_transfers"}      # lib/dated_events
    # Prefix-sibling guard: for account `m`, the glob also matches
    # account `m_extra`'s artifacts — deleting those every run
    # destroyed m_extra's parsed books and (worse) its elections
    # manifest, the one artifact documented as NOT rebuildable
    # (2026-09 adversarial audit). Skip any stem that belongs to a
    # LONGER configured account name, and never touch manifests.
    _sibling_prefixes = []
    try:
        for _other in (_soft_config(acct_dir.parent.parent)
                       .get("accounts") or {}):
            if _other != name and _other.startswith(f"{name}_"):
                _sibling_prefixes.append(f"{_other}_")
    except Exception:
        pass
    for _stale in cache.glob(f"{name}_*.json"):
        _stem = _stale.name[:-len(".json")]
        if _stem in _present:
            continue
        if any(_stale.name.startswith(_pre)
               for _pre in _sibling_prefixes):
            continue
        _sfx = _stale.name[len(name):]
        if any(_sfx.endswith(x) for x in
               ("_base.json", "_gains.json", "_gains_wash.json",
                "_raw.json", "_raw_base.json", "_raw_gains.json",
                "_raw_base_gains.json", "_merged.json", "_sorted.json",
                "_filled.json", "_mapped.json", "_report.json",
                "_pending_elections.json", "_manifest.json",
                TRANSFER_COSTS_SUFFIX,
                "_blend.diag", OWN_MOVES_SUFFIX)):
            continue
        # A parsed-source artifact with no surviving input group.
        for _victim in (_stale, _stale.with_name(_stale.name + ".diag")):
            if _victim.exists():
                _victim.unlink()
                _say("note", f"removed stale work/{_victim.name} (its "
                     f"input files are gone)", indent="  ",
                     file=sys.stdout)

    sources = tt_jsons + parsed + corp_files
    # Shares that arrived by transfer from outside the books: booked at
    # the broker's stated book value, or said to have no cost
    # (lib/transfer_in, CA-ACB-TRANSFER-BV / US-BASIS-TRANSFER-BV).
    if is_taxable and not is_crypto and not include_transfers:
        _tc_had = (cache / f"{name}{TRANSFER_COSTS_SUFFIX}").exists()
        _tc = stage_transfer_arrivals(name, inputs_dir.parent, cache,
                                      tt_jsons, country)
        if _tc is not None:
            sources = sources + [_tc]
        elif _tc_had:
            # The bookings went away (a .tt line now covers them): no
            # surviving dep is newer, so `run --fast` must be told to
            # merge again (the FUZZ #J deletion-blindness class).
            import os as _os
            _os.utime(src_manifest)
    # A US project's moves between your own taxable accounts, written by
    # `taxjson run` before the accounts' books (stage_own_account_moves;
    # US-BASIS-05): their TRANSFER legs are part of this account's books.
    _own_moves = cache / f"{name}{OWN_MOVES_SUFFIX}"
    if is_taxable and not include_transfers and _own_moves.is_file():
        sources = sources + [_own_moves]

    # 4. merge → base.json (crypto path differs: needs fill-crypto mid-stream)
    base_json = cache / f"{name}_base.json"
    if is_crypto:
        _refuse_crypto_openings(name, tt_jsons)
        merged = cache / f"{name}_merged.json"
        # src_manifest is a dep here for the same reason it is on the
        # equity merge2 below: deleting an entire broker group (e.g. the
        # only kr_*.csv) removes its parsed JSON from `sources`, and
        # without the manifest nothing newer remains to dirty `merged`.
        if force or needs_rebuild(merged, *sources, src_manifest):
            _step("Merging the exports")
            run_to_file(_cmd("taxjson-merge") + [str(p) for p in sources], merged)
        sorted_ = cache / f"{name}_sorted.json"
        if force or needs_rebuild(sorted_, merged):
            _step("Sorting, de-duplicating")
            run_to_file(_cmd("taxjson-sort") + ["--dedup", str(merged)], sorted_)
        # ticker.map GLOBAL/DELETE apply to crypto books too — the
        # README's contract is "every stage", but this path has no
        # merge2, so a Coinbase ETH2→ETH consolidation silently split
        # pools (2026-09 audit). Mapping runs BEFORE the price fill:
        # FMV lookups keyed by a dead alias (ETH2) either fetched the
        # wrong asset's price or left $0 basis (adversarial audit).
        # TOBASE/JOURNAL stay equity-only.
        mapped = sorted_
        if ticker_map:
            mapped = cache / f"{name}_mapped.json"
            if force or needs_rebuild(mapped, sorted_, ticker_map):
                _step("Mapping tickers")
                run_to_file(_cmd("taxjson-ticker-map") + [
                    str(sorted_), "--map", str(ticker_map),
                    "--global-only", "--kind", "crypto",
                    "--country", country], mapped)
        elif (cache / f"{name}_mapped.json").exists():
            (cache / f"{name}_mapped.json").unlink()
        filled = cache / f"{name}_filled.json"
        # The project ticker.map's CRYPTO lines (README) are resolved
        # from the project, never the cwd: `-C <proj>` from anywhere
        # used to ignore them (and a map in the cwd leaked into other
        # projects). Their state (content, or absence) is a rebuild dep
        # through a stamp that changes only when they do, so `run
        # --fast` re-prices after a CRYPTO line is added, edited, or
        # deleted. fill-crypto also reads a ticker.map in its input
        # file's folder (work/), later wins: that one is part of the
        # stamp too (re-audit A2-0585).
        from taxjson.lib.ticker_map import side_rules_in as _side_in
        _cparts = []
        for _cdir in (inputs_dir.parent, mapped.parent):
            try:
                _crules = sorted(_side_in([_cdir]).crypto.items())
                _cparts.append(("sha256:" + hashlib.sha256(
                    repr(_crules).encode()).hexdigest()) if _crules
                    else "absent")
            except (OSError, ValueError):
                _cparts.append("unreadable")
        _cstate = (_cparts[0] if _cparts[1] == "absent"
                   else " ".join(_cparts))
        _cstamp = cache / f"{name}_crypto_ticker_map.state"
        if (_read_work_stamp(_cstamp) or "").strip() != _cstate:
            _write_work_stamp(_cstamp, _cstate + "\n")
        if force or needs_rebuild(filled, mapped, _cstamp):
            _step("Looking up crypto prices")
            run_to_file(_cmd("taxjson-fill-crypto") + [
                "--project-root", str(inputs_dir.parent), str(mapped)],
                filled)
        # A coin priced under an id that looks wrong (no CRYPTO line
        # while the price cache holds a numbered id of the ticker, or
        # Yahoo closes far off the coin's own trade prices): console,
        # every run, --fast included (from the persisted .diag).
        from taxjson.bin.fill_crypto_prices import (
            ATTENTION_CRYPTO_ID as _ATT_CID)
        echo_attention_lines(filled,
                             prefix=_ATT_CID[len(ATTENTION_PREFIX) + 1:])
        if force or needs_rebuild(base_json, filled, rates):
            _step(f"Converting currency to {base_currency}")
            run_to_file(_cmd("taxjson-convert-currency") + [
                str(filled), "--to", base_currency, "--rates", str(rates),
                "--country", country,
            ], base_json)
        # The crypto path has no merge2 stage, so it never validates its
        # output. Run taxjson-validate explicitly and persist the report
        # as a .diag so crypto.sum carries an OK:/error line like the
        # merge2-validated equity accounts.
        validate_diag = cache / f"{name}_validate.diag"
        from taxjson.lib.dispatch import run_cmd as _run_cmd
        # --require-prices: a row fill-crypto could not price is an
        # ERROR here (R1-105), not a silent $0 income/cost.
        # Run from work/ on the bare file name: the report is copied into
        # reports/<name>.sum, and an absolute path put the user's home
        # directory (their OS user name) in every crypto report (S037-18).
        vres = _run_cmd(_cmd("taxjson-validate") + ["--require-prices",
                                                    base_json.name],
                        capture_output=True, cwd=str(base_json.parent))
        report = (vres.stdout or "") + (vres.stderr or "")
        if report.strip():
            validate_diag.write_text(report, encoding="utf-8")
        elif validate_diag.exists():
            validate_diag.unlink()
        # Quiet on success (the report is in the .diag → .sum); only
        # surface to the console if validation actually failed.
        if vres.returncode != 0:
            # `report` is text (run_cmd captures with text=True);
            # stderr.buffer.write(str) raised TypeError and crashed the
            # run instead of printing the report.
            _echo_stage_stderr(report)
            if strict:
                _die(f"--strict: {name}: validation ERROR(s) in the "
                     f"crypto books — aborting")
            _say("warning", f"{name}: validation ERROR(s) in the crypto "
                 f"books — numbers may be wrong",
                 f"Details: reports/{name}.sum DIAGNOSTICS (or "
                 f"work/{validate_diag.name}).", indent="  ")
    else:
        cmd = _cmd("taxjson-merge2") + [
            "--sort", "--dedup", "--require-inputs",
            "--to", base_currency, "--rates", str(rates), "--validate",
            "--country", country,
        ]
        if year:
            # An opening snapshot that would leave out a sale of the
            # tax year is refused (lib/opening, CA-OPEN-03).
            cmd += ["--year", str(year)]
        if ticker_map:
            cmd += ["--map", str(ticker_map)]
        cmd += [str(p) for p in sources]
        # Non-cash fund distributions (reinvested capital-gains dists /
        # late-published ROC factors) never appear in broker CSVs;
        # taxjson.toml's [[distributions]] turn them into ADJUST rows.
        # Taxable books only — sheltered ACB is moot. (taxjson.toml is
        # every stage's implicit dep — needs_rebuild.)
        _apply_dists = is_taxable and _config_has_distributions()
        deps = list(sources) + [rates, src_manifest] \
            + ([ticker_map] if ticker_map else []) \
            + ([incomplete_history]
               if _apply_dists and incomplete_history else [])
        if force or needs_rebuild(base_json, *deps):
            _step("Sorting, de-duplicating, mapping tickers, converting "
                  "currency")
            if not _apply_dists:
                run_to_file(cmd, base_json)
            else:
                # ONE atomic publish for merge2 + apply-distributions:
                # publishing merge2's output first and adjusting
                # in-place meant a failed/interrupted apply left a
                # fresh-but-unadjusted base that every later --fast
                # run trusted — the ADJUST rows silently vanished
                # until an unrelated rebuild (2026-09 audit).
                _stage = base_json.with_name(base_json.name + ".stage")
                try:
                    run_to_file(cmd, _stage)
                    _step("Applying [[distributions]] from taxjson.toml")
                    from taxjson.lib.dispatch import run_cmd as _run_cmd_d
                    _dres = _run_cmd_d(
                        _cmd("taxjson-apply-distributions") + [
                            str(_stage), "--config", str(_CONFIG_PATH),
                            "--account", name,
                            # Record-date balance = holder of record,
                            # i.e. the SETTLED position in BOTH
                            # countries: a market fact, not the tax-
                            # year date basis (a US project's trade
                            # tax_date credited a buy traded on the
                            # record date — partition INPUTS-10).
                            "--date-basis", "settle",
                            "--country", country]
                        # Keys go through the same ticker.map renames
                        # as the book (S025-22).
                        + (["--ticker-map", str(ticker_map)]
                           if ticker_map else [])
                        # Size record-date balances WITH the
                        # missing-history openings the gains stage synthesizes (S000-08).
                        + (["--incomplete-history",
                            str(incomplete_history)]
                           if incomplete_history else []),
                        capture_output=True)
                    if _dres.stderr:
                        _echo_stage_stderr(_dres.stderr)
                    if _dres.returncode != 0:
                        sys.exit(exit_text(f"taxjson run: apply-distributions "
                                           f"failed for {name} (see above)."))
                    _stage.replace(base_json)
                    # Publish the stage's diagnostics under the name
                    # every reader uses — the --strict gate and the
                    # .sum banner read <name>_base.json.diag, and a
                    # validation ERROR hidden in the .stage.diag
                    # sailed past --strict (2026-09 audit).
                    _sdiag = _stage.with_name(_stage.name + ".diag")
                    _bdiag = base_json.with_name(base_json.name
                                                 + ".diag")
                    if _sdiag.exists():
                        _sdiag.replace(_bdiag)
                    else:
                        _bdiag.unlink(missing_ok=True)
                finally:
                    _stage.unlink(missing_ok=True)
                    _stage.with_name(_stage.name + ".diag").unlink(
                        missing_ok=True)
        # Hard validation ERRORs must be VISIBLE, not archaeology: they
        # previously lived only in the raw .diag (FUZZ #M). This check
        # runs OUTSIDE the rebuild branch on purpose — the persisted
        # .diag describes the cached books too, and gating it on a
        # rebuild let `run --strict --fast` on unchanged-but-invalid
        # books skip the gate entirely and publish reports at exit 0
        # (the crypto path's unconditional validate never had the
        # hole). The warn-only default still completes the run.
        _diag = base_json.with_name(base_json.name + ".diag")
        if _diag.exists():
            _dtxt = _diag.read_text(errors="replace")
            import re as _re
            _m = _re.search(r"validation: (\d+) error", _dtxt)
            if _m and int(_m.group(1)) > 0:
                if strict:
                    # --strict (KNOWN_ISSUES "per-account validation is
                    # non-fatal"): a CI/cron run must not publish a
                    # wrong .sum at exit 0.
                    _die(f"--strict: {name}: {_m.group(1)} validation "
                         f"ERROR(s) in the merged books — aborting",
                         f"Details: work/{_diag.name}.")
                _say("warning", f"{name}: {_m.group(1)} validation "
                     f"ERROR(s) in the merged books — numbers may be "
                     f"wrong", f"Details: reports/{name}.sum DIAGNOSTICS "
                     f"(or work/{_diag.name}).", indent="  ")

    # Cross-file dedup ambiguities (bin/taxjson_sort.plan_dedup, audit
    # R1-296): echoed from the persisted .diag on EVERY run, cached or
    # not — a row booked once (or twice) on a guess must not scroll by.
    echo_attention_lines(cache / f"{name}_sorted.json" if is_crypto
                         else base_json, prefix="dedup: ")
    # A ticker.map rename to a bare symbol (audit A2-0304).
    echo_attention_lines(base_json, prefix="ticker.map: ")
    # An opening snapshot leaving the account's earlier rows of its
    # symbols out of the books (lib/opening, CA-OPEN-03).
    if not is_crypto:
        echo_attention_lines(base_json, prefix="opening: ")
    # A split booked twice with a rounded ratio (A2-0070): one event,
    # applied once — on the console, so the manual line gets deleted.
    if not is_crypto:
        echo_attention_lines(base_json, prefix="split: ")

    # 5. gains
    gains_json = cache / f"{name}_gains.json"
    traces = cache / f"{name}_gains.traces"
    cmd = _cmd("taxjson-gains") + [
        "--country", country, "--year", str(year),
        "--tax-date", tax_date,
        "--full-traces", str(traces),
    ]
    wash_flags = _wash_flags(is_taxable, is_crypto, country)
    cmd += wash_flags
    if "--no-wash" in wash_flags:
        # A rule of the run, not of the account: said once.
        _say_once("no-crypto-wash", "note",
                  "wash-sale rule NOT applied to crypto",
                  "The IRS treats crypto as property, not a security "
                  "(§1091 does not reach it); losses are allowed in full.",
                  indent="  ", file=sys.stdout)
    cmd += option_timing_flags(settings)
    cmd += income_dating_flags(settings)
    cmd += _locked_year_flags(cache.parent, settings)
    if is_crypto:
        # Spot coins cannot be short: a sale with nothing held is
        # missing history, said as ATTENTION (re-audit A2-0137).
        cmd.append("--spot-crypto")
    # Project-wide missing-history opening balances (from
    # `find-missing-history --write-missing-history`). load_missing_history filters by (symbol, account), so passing
    # the whole file to every account's gains run is safe — non-matching pairs
    # are ignored. A rebuild dependency so editing the file re-runs gains.
    gains_deps = [base_json] + _lock_files(cache.parent, settings)
    if incomplete_history is not None:
        cmd += ["--incomplete-history", str(incomplete_history)]
        gains_deps.append(incomplete_history)
    cmd.append(str(base_json))
    if force or needs_rebuild(gains_json, *gains_deps):
        _step("Calculating capital gains")
        run_to_file(cmd, gains_json)
    # The gains stage's ATTENTION lines, from the persisted .diag on
    # EVERY run, cached or not: a broker-coded CLOSING row the books
    # cannot back (audit A2-0006), an unapplied basis adjustment
    # (A2-0199), income a record date moves across a year end (A2-0073,
    # A2-0229), a missing_history.json entry on a real short or a written
    # option (A2-0637 / A2-0639). One call covers all — but the positions
    # that go short: the run lists those once, after every account's
    # books, the ones that bear on the tax year one by one and the rest
    # in one line (_report_short_positions).
    echo_attention_lines(gains_json, exclude="short: ", once=True)
    _SHORT_SOURCES.append((name, base_json, gains_json,
                           is_taxable and not is_crypto))
    # A short where none can exist (a registered account, spot crypto,
    # a sale the broker codes CLOSING): missing history the numbers
    # depend on — --strict refuses (re-audit A2-0395 / A2-0137 / A2-1223).
    _shorts = _attention_short_lines(gains_json)
    if _shorts and strict:
        echo_attention_lines(gains_json, prefix="short: ", once=True)
        _die(f"--strict: {name}: {len(_shorts)} position(s) go short where "
             f"none can exist — history is missing",
             "A registered account, spot crypto, or a sale the broker "
             "codes closing: see the Short position warnings above. Spot "
             "crypto and registered accounts cannot be short.")
    if is_taxable:
        _warn_expired_open_options(name, gains_json, cache, year,
                                   tax_date=_tax_date_basis(settings))

    # 5b. Raw holdings: merge + sort + dedup, NO currency conversion and
    # NO validation; then gains with no options. The same ticker.map is
    # passed, but with no --to the merge applies only GLOBAL renames and
    # DELETEs — TOBASE consolidations are skipped, so cross-listings like
    # SAMPLM.US / SAMPLM.TO stay separate per actual listing. JOURNAL pairs are
    # netted later, at the export aggregation (post-gains — they can't be
    # merged pre-gains without a mixed-currency ACB pool).
    #
    # Emitted as a TOML holdings handoff. Skipped for crypto.
    if not is_crypto:
        raw_json = cache / f"{name}_raw.json"
        # src_manifest: deleting a .tt from a .tt-only account (no CSV
        # group left to cascade the change) kept its positions in the
        # raw holdings under --fast (S037-22) — the same dep merge2 has.
        raw_deps = (list(sources) + [src_manifest]
                    + ([ticker_map] if ticker_map else []))
        if force or needs_rebuild(raw_json, *raw_deps):
            raw_cmd = _cmd("taxjson-merge2") + ["--sort", "--dedup",
                                                 "--country", country]
            if ticker_map:
                raw_cmd += ["--map", str(ticker_map)]
            raw_cmd += [str(p) for p in sources]
            run_to_file(raw_cmd, raw_json, capture_diag=False)
        # Idempotent: rewrites only rows still in another currency (also
        # a raw merge an earlier version left behind).
        for _ln in _raw_align_adjust_currency(raw_json, rates,
                                              base_currency):
            _say("note", _ln, indent="  ")
        mixed = _raw_mixed_currency_symbols(raw_json)
        if mixed:
            # Unrepresentable in a native-currency book (cross-currency
            # rollover rename, or a foreign-currency cost adjustment with
            # no rate on file): skip the raw view rather than kill the
            # run. The converted books, gains, wash and .sum reports
            # above are complete and authoritative.
            _say("warning", f"raw holdings skipped for '{name}': "
                 f"{', '.join(mixed)} would pool mixed currencies",
                 "A cross-currency rollover rename, or a cost adjustment "
                 "or corporate-action row in another currency with no "
                 f"exchange rate on file. reports/{name}_holdings.toml "
                 "was NOT refreshed this run.", indent="  ")
            # The native books of an EARLIER run (before the rollover
            # rows arrived) would otherwise keep serving `taxjson gains`
            # without the rolled-over disposition (2026-09 audit S037-23).
            for _stale in (cache / f"{name}_raw_gains.json",
                           cache / f"{name}_raw_base.json",
                           cache / f"{name}_raw_base_gains.json"):
                if _stale.exists():
                    _stale.unlink()
                    _say("note", f"removed stale work/{_stale.name}",
                         indent="  ")
        else:
            raw_gains = cache / f"{name}_raw_gains.json"
            # missing_history.json applies to the native books too:
            # without it holdings.toml listed
            # every listed pair as a SHORT, and `taxjson gains` showed a
            # tainted sale as a realized gain (audit A2-0111 / A2-0305,
            # R1-275 / R1-322). A pair spelled with a TOBASE target the
            # native books do not use simply has no rows here.
            _ph_raw = (["--incomplete-history", str(incomplete_history)]
                       if incomplete_history is not None else [])
            _ph_deps = ([incomplete_history]
                        if incomplete_history is not None else [])
            if force or needs_rebuild(raw_gains, raw_json, *_ph_deps):
                # Match the country to the rest of the pipeline (it is
                # required; it used to default to Canada, and the US
                # raw-holdings inventory would aggregate FIFO lots as a
                # Canadian-style ACB blended pool — wrong total_cost per
                # symbol on the holdings.toml handoff.
                run_to_file(_cmd("taxjson-gains") + [
                    "--country", country,
                ] + option_timing_flags(settings)
                    + income_dating_flags(settings) + _ph_raw
                    + [str(raw_json)],
                            raw_gains, capture_diag=False)
            # Base-currency companion: convert the SAME raw merge to the base
            # currency (per-transaction FX, no ticker consolidation — so symbols
            # stay per-listing and line up 1:1 with raw_gains) then re-run gains.
            # This yields a base-currency ACB per holding (computed by the gains
            # engine at acquisition-date rates), which the holdings export embeds
            # as base_total_cost / base_cost_per_share so downstream tools can see
            # whether a position is in a gain or loss in base-currency terms.
            raw_base_json = cache / f"{name}_raw_base.json"
            if force or needs_rebuild(raw_base_json, raw_json, rates):
                # capture_diag here (unlike the other raw stages): convert-currency
                # emits its --default-rate FX-fallback summary on stderr, and a
                # silently-defaulted rate would corrupt base_total_cost. Persisting
                # it to the .diag surfaces any missing-rate fallback in the .sum.
                run_to_file(_cmd("taxjson-convert-currency") + [
                    str(raw_json), "--to", base_currency, "--rates", str(rates),
                    "--country", country,
                ], raw_base_json)
            raw_base_gains = cache / f"{name}_raw_base_gains.json"
            if force or needs_rebuild(raw_base_gains, raw_base_json,
                                      *_ph_deps):
                run_to_file(_cmd("taxjson-gains") + [
                    "--country", country,
                ] + option_timing_flags(settings)
                    + income_dating_flags(settings) + _ph_raw
                    + [str(raw_base_json)],
                            raw_base_gains, capture_diag=False)
            # Machine-readable holdings handoff (TOML) for live-pricing /
            # trading tools. A journal between two listings (Norbert's
            # gambit) moves its units by its transfer legs — the broker's
            # rows or a .tt JOURNAL line's (lib/dated_events); a legacy
            # ticker.map JOURNAL line no longer nets the listings here.
            holdings_toml = reports_dir / f"{name}_holdings.toml"
            # Snapshot the existing holdings.toml so the post-export diff
            # has a baseline. First-run / no-prior-snapshot cases produce
            # no diff (correct behaviour — there's nothing to compare to).
            prev_holdings = cache / f"{name}_holdings_prev.toml"
            if holdings_toml.exists():
                # (a fresh file: never written through a symlink at the
                # snapshot's name — security review M1)
                from taxjson.lib.safe_write import write_atomic
                write_atomic(prev_holdings, holdings_toml.read_bytes())
            elif prev_holdings.exists():
                # Stale snapshot from a prior run whose output was wiped;
                # discard so we don't diff against an out-of-date baseline.
                prev_holdings.unlink()
            # --futures: include futures positions (taxjson-export excludes
            # them by default). A holdings handoff should reflect everything
            # actually held, futures included.
            export_cmd = _cmd("taxjson-export") + [
                "--holdings-toml", "--account-name", name, "--futures",
                "--country", country,
            ]
            if ticker_map:
                export_cmd += ["--map", str(ticker_map)]
                # Evidenced depot flips: the per-broker transfer
                # sidecars prove which quantities journaled between a
                # security's listings — the holdings view applies
                # exactly those (a JOURNAL map line stays for
                # intrinsically fungible classes like SAMPLF).
                for _sc in sorted(cache.glob(f"{name}_*_transfers.json")):
                    if any(_sc.name.startswith(_pre)
                           for _pre in _sibling_prefixes):
                        continue     # another account's sidecar
                    if _sc.name.startswith(f"{name}_tt_"):
                        continue     # a converted .tt, not a sidecar
                    export_cmd += ["--transfer-evidence", str(_sc)]
            export_cmd += ["--base-gains", str(raw_base_gains),
                           "--base-currency", base_currency,
                           "--trades", str(raw_json)]
            export_cmd.append(str(raw_gains))
            run_to_file(export_cmd, holdings_toml, capture_diag=False)
            _wrote(holdings_toml, reports_dir.parent, "holdings")
            # Surface quantity changes vs the prior run so the user can
            # sanity-check trades at a glance (e.g. "I didn't expect SAMPLG
            # to move — did I import the wrong file?"). Silent on the
            # first run (no baseline) and silent when nothing changed.
            maybe_print_holdings_diff(prev_holdings, holdings_toml)

    # 6. summary — assembled in a .part sidecar and renamed on success, so a
    # failing sub-report can't leave a truncated .sum that `taxjson sum`
    # then serves (same atomicity contract as run_to_file).
    sum_path = reports_dir / f"{name}.sum"
    sum_path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    _wrote(sum_path, reports_dir.parent)
    from taxjson.lib.safe_write import atomic_open
    with atomic_open(sum_path, binary=True) as out:
        # The pre-blend baseline: the cross-account passes' notes
        # (written after this file) go in <name>_wash.sum.
        out.write(_diagnostics_banner(cache, name, post_pass=False))
        out.write(run_capture(_cmd("taxjson-sum-gains")
                              + (["--staking"] if is_crypto else [])
                              + ["--country", country]
                              + [str(gains_json)]))
        out.write(run_capture(_cmd("taxjson-sum-income") + [
            "--year", str(year), "--country", country,
        ] + income_dating_flags(settings) + [str(base_json)]))
        if not is_crypto:
            # The portfolio-snapshot report is equity-specific; crypto skips it.
            out.write(run_capture(_cmd("taxjson-export") + [
                "--report", "--futures", str(gains_json),
            ]))

    # Machine twin of the text reports (ADDITIVE — the .sum bytes above are
    # untouched): the structured aggregates `taxjson sum` and future
    # consumers read instead of re-deriving them from the gains JSON.
    try:
        from taxjson.lib.report_model import (build_account_report,
                                              load_report_json)
        report_json = cache / f"{name}_report.json"
        _base_rows = load_report_json(base_json).get(
            "transactions", [])
        from taxjson.lib.safe_write import write_atomic
        write_atomic(report_json, _json_dumps_report(build_account_report(
                load_report_json(gains_json), name, basis="pre-wash",
                base_transactions=_base_rows,
                rules=_income_rules(settings))))
    except Exception as e:                      # advisory artifact only
        _say("warning", f"could not write {name}_report.json: {e}",
             prog=_PROG)

    return {"base": base_json, "gains": gains_json, "sum": sum_path}


def _income_rules(settings: Dict[str, Any]):
    """The project's lib/income_dating rules (country + overrides)."""
    from taxjson.lib.income_dating import IncomeRules
    return IncomeRules.from_settings(settings)


def _json_dumps_report(payload) -> str:
    import json as _json
    return _json.dumps(payload, indent=2, sort_keys=True) + "\n"


def _diagnostics_banner(cache: Path, account: str, *,
                        post_pass: bool = True,
                        blended: bool = False) -> bytes:
    """A DIAGNOSTICS section for the top of a .sum file, or empty bytes
    when the account's pipeline stages produced no warnings/notes."""
    diag = collect_diagnostics(cache, account, post_pass=post_pass,
                               blended=blended)
    if not diag:
        return b""
    rule = "=" * 70
    return (f"{rule}\n DIAGNOSTICS — {account}  "
            f"(parser/merge warnings; not part of the tax totals)\n{rule}\n"
            f"{diag}\n{rule}\n\n").encode()


def _wash_rule_words(settings: Dict[str, Any]) -> str:
    """The country's loss-denial rule, plural, for a console step."""
    return ("wash sales" if _country(settings) in ("us", "usa")
            else "superficial losses")


def stage_wash_pass(name: str, settings: Dict[str, Any], cache: Path, reports_dir: Path,
                    sheltered_base: Path,
                    incomplete_history: Optional[Path] = None) -> None:
    """Re-run gains with --sheltered to apply cross-account wash sale."""
    _step(f"Checking {name} for {_wash_rule_words(settings)} with the "
          f"sheltered accounts")
    base_json = cache / f"{name}_base.json"
    wash_gains = cache / f"{name}_gains_wash.json"
    wash_traces = cache / f"{name}_gains_wash.traces"
    cmd = _cmd("taxjson-gains") + [
        "--taxable",
        "--country", _normalize_country(settings["country"]),
        "--year", str(settings["year"]),
        "--tax-date", _tax_date(settings),
        "--sheltered", str(sheltered_base),
        "--full-traces", str(wash_traces),
    ]
    cmd += option_timing_flags(settings)
    cmd += income_dating_flags(settings)
    cmd += _locked_year_flags(cache.parent, settings)
    # Same missing-history opening balances as the main gains pass — without
    # this the wash-adjusted books (which `taxjson wash-sales` PREFERS when
    # present) were computed on different books than <account>.sum.
    if incomplete_history is not None:
        cmd += ["--incomplete-history", str(incomplete_history)]
    cmd.append(str(base_json))
    run_to_file(cmd, wash_gains)
    _LOSS_CONTEXT_GAINS.append(wash_gains)
    _render_wash_outputs(name, settings, cache, reports_dir,
                         wash_gains, base_json)


# The gains files of this run's passes WITH the sheltered context (the
# blended passes, a crypto account's wash pass): their
# `transfers_in_loss_windows` make the run's one transfer warning.
_LOSS_CONTEXT_GAINS: List[Path] = []


def _say_transfer_windows(settings: Dict[str, Any]) -> None:
    """ONE warning per run (CA-SL-16 / US-WASH-23): every transfer-in
    the books keep as a move between accounts, not a purchase, that sits
    inside a taxable loss's 30-day window — gathered from this run's
    loss-context passes (lib/pipeline.transfers_in_loss_windows)."""
    import json as _json
    from taxjson.lib.pipeline import transfer_window_message
    items: List[Dict[str, Any]] = []
    seen = set()
    for p in _LOSS_CONTEXT_GAINS:
        try:
            doc = _json.loads(p.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        for x in (doc.get("transfers_in_loss_windows") or []
                  if isinstance(doc, dict) else []):
            if not isinstance(x, dict):
                continue
            k = (x.get("account"), x.get("symbol"), x.get("date"),
                 x.get("qty"))
            if k not in seen:
                seen.add(k)
                items.append(x)
    _LOSS_CONTEXT_GAINS.clear()
    if not items or ("xferwin",) in _SHOWN_THIS_RUN:
        return
    # Once per run, as the engine echoes are (_echo_captured once): a
    # failed stage's echo of a pass's own line is not shown after it.
    _SHOWN_THIS_RUN.add(("xferwin",))
    items.sort(key=lambda r: (str(r.get("date")), str(r.get("account")),
                              str(r.get("symbol"))))
    head, details, _legacy = transfer_window_message(
        items, _normalize_country(settings["country"]))
    _say("warning", head, *details, indent="  ", file=sys.stdout)


def _render_wash_outputs(name: str, settings: Dict[str, Any], cache: Path,
                         reports_dir: Path, wash_gains: Path,
                         base_json: Path, *, blended: bool = False
                         ) -> None:
    """The .sum + report.json rendering for one account's wash-adjusted
    gains — shared by the per-account (crypto) and blended (equity)
    passes."""
    wash_sum = reports_dir / f"{name}_wash.sum"
    # .part + rename: a failing sub-report must not truncate the .sum.
    from taxjson.lib.safe_write import atomic_open
    with atomic_open(wash_sum, binary=True) as out:
        out.write(_diagnostics_banner(cache, name, blended=blended))
        _is_c = bool(((_soft_config(cache.parent).get("accounts")
                       or {}).get(name) or {}).get("crypto"))
        out.write(run_capture(_cmd("taxjson-sum-gains")
                              + (["--staking"] if _is_c else [])
                              + ["--country", _normalize_country(
                                  settings["country"])]
                              + [str(wash_gains)]))
        out.write(run_capture(_cmd("taxjson-sum-income") + [
            "--year", str(settings["year"]),
            "--country", _normalize_country(settings["country"]),
        ] + income_dating_flags(settings) + [str(base_json)]))
        out.write(run_capture(_cmd("taxjson-export") + [
            "--report", "--futures", str(wash_gains),
        ]))

    # Rebuild the machine twin from the wash-adjusted gains: report.json
    # must carry the same basis the query commands resolve to (they prefer
    # <name>_gains_wash.json), or `taxjson sum`'s fast path would serve
    # pre-wash aggregates next to a "wash-adjusted" banner.
    try:
        from taxjson.lib.report_model import (build_account_report,
                                              load_report_json)
        report_json = cache / f"{name}_report.json"
        _base_rows = load_report_json(base_json).get(
            "transactions", [])
        from taxjson.lib.safe_write import write_atomic
        write_atomic(report_json, _json_dumps_report(build_account_report(
                load_report_json(wash_gains), name,
                basis="wash-adjusted",
                base_transactions=_base_rows,
                rules=_income_rules(settings))))
    except Exception as e:                      # advisory artifact only
        _say("warning", f"could not write {name}_report.json: {e}",
             prog=_PROG)
    _wrote(wash_sum, reports_dir.parent)


# A custody move's two legs (out of one account, into another) post a
# few days apart at most.
_OWN_MOVE_DAYS = 10


TRANSFER_COSTS_SUFFIX = "_transfer_costs.json"


def _symbol_codes_suffix() -> str:
    from taxjson.lib.symbol_codes import SUFFIX
    return SUFFIX


def _symbol_codes_state(root: Path, name: str) -> Optional[Path]:
    """work/<name>_symbol_codes.state when the run wrote one (lib/
    symbol_codes): what the corp-action extraction books a Questrade
    chain under an internal code as — `taxjson elect` and `--redo`
    extract exactly as the run does."""
    p = Path(root) / "work" / f"{name}{_symbol_codes_suffix()}"
    return p if p.is_file() else None


def stage_ib_project(name: str, root: Path, cache: Path
                     ) -> Tuple[Path, List[Path]]:
    """work/<name>_ib_project.state: the project's OTHER securities
    accounts' IB statements ({"account": name, "accounts": {label:
    [paths]}}), passed to the IB parse as --project-statements: a ticker
    change IB shows as one contract id under two symbols is the
    security's, dated from every account's rows (review 2 #4). Returns
    (the state, those statements: deps of the parse; none when no other
    account has an IB statement — then the parse gets no
    --project-statements). Written only when it changes, and kept with
    `"accounts": {}` when the last other statement goes: the state is
    always a dep, so `run --fast` re-parses then too (third pre-release
    review, 6)."""
    import json as _json
    from taxjson.lib.brokerages.detect import detect
    out = cache / f"{name}_ib_project.state"
    others: Dict[str, List[str]] = {}
    deps: List[Path] = []
    for label, acfg in sorted((_soft_config(root).get("accounts")
                               or {}).items()):
        if (label == name or not isinstance(acfg, dict)
                or acfg.get("crypto")):
            continue
        acct_dir = root / "inputs" / label
        if not acct_dir.is_dir():
            continue
        found = []
        for csv in input_files(acct_dir, ".csv"):
            try:
                det = detect(csv)
            except Exception:                      # noqa: BLE001
                continue        # that account's own stage names it
            if det.broker == "ib" and not det.positions:
                found.append(csv)
        if found:
            others[label] = [str(p) for p in found]
            deps.extend(found)
    text = _json.dumps({"account": name, "accounts": others}, indent=1,
                      sort_keys=True) + "\n"
    if _read_work_stamp(out) != text:
        _write_work_stamp(out, text)
    return out, deps


def stage_symbol_codes(name: str, csvs: List[Path], root: Path,
                       cache: Path, out: Path) -> Path:
    """work/<name>_symbol_codes.state: the Questrade internal codes of
    this account that its own rows do not resolve, inferred from the
    project's other exports (lib/symbol_codes: a paired transfer out,
    else a unique name match; a ticker.map rule for the code wins).
    Written only when it changes — it is a dep of the Questrade parse,
    which books the codes under their tickers and says so in one note."""
    from taxjson.lib import symbol_codes as SC
    from taxjson.lib.brokerages.questrade import (QuestradeBrokerage,
                                                  journal_codes,
                                                  scan_code_uses)
    try:
        uses = scan_code_uses(csvs)
    except Exception:                              # noqa: BLE001
        uses = []           # the parse itself names a broken export
    try:
        by_journal = journal_codes(csvs)
    except Exception:                              # noqa: BLE001
        by_journal = {}     # the parse itself names a broken export
    result: Dict[str, Any] = {"resolved": {}, "unresolved": {}}
    if uses:
        accounts = [n for n, c in (_soft_config(root).get("accounts")
                                   or {}).items()
                    if isinstance(c, dict) and not c.get("crypto")]
        outs, names = SC.project_evidence(
            cache, accounts or [name], receiving=(name, "questrade"))
        named = _ticker_map_named(root)
        helper = QuestradeBrokerage()

        def listing_ok(listing: str, cur: str) -> bool:
            return helper.apply_currency_suffix(listing, cur) == listing

        def mapped(code: str) -> bool:
            # ANY ticker.map rule naming the code (a rename, DELETE,
            # DISTINCT, a dated RENAME) wins — the test the parser
            # applies too (base.ticker_map_names), so the record, the
            # books and `taxjson transfers` agree.
            return any(helper.apply_currency_suffix(code, cur) in named
                       for cur in sorted({"USD", "CAD"}
                                         | {c for u in uses
                                            if u.code == code
                                            for c in u.currencies}))
        result = SC.resolve(uses, outs, names, listing_ok=listing_ok,
                            mapped=mapped,
                            code_listing=helper.apply_currency_suffix)
    if by_journal:
        # Codes a BRW journal leg of this account names (the parser
        # books them so): recorded for `taxjson transfers`; a ticker.map
        # rule naming the code wins here too.
        named_j = _ticker_map_named(root)
        _h = QuestradeBrokerage()
        for code, r in sorted(by_journal.items()):
            if any(_h.apply_currency_suffix(code, c) in named_j
                   for c in ("USD", "CAD", r.get("currency") or "USD")):
                result.setdefault("mapped", {})[code] = {
                    "how": "ticker.map", "evidence": "ticker.map rule"}
            else:
                result["resolved"][code] = dict(r)
    text = SC.state_text(name, result)
    if _read_work_stamp(out) != text:
        _write_work_stamp(out, text)
    return out


# The currency-suffix groups staged this run: {(work dir, account):
# {broker: csvs}} (stage_listing_suffix; the first pass re-reads a group
# whose listings changed once every account is parsed).
_LISTING_GROUPS: Dict[Tuple[Path, str], Dict[str, List[Path]]] = {}


def _listing_suffix_text(name: str, broker: str, csvs: List[Path],
                         root: Path, cache: Path) -> str:
    """The state text stage_listing_suffix writes (lib/listing_suffix)."""
    from taxjson.lib import listing_suffix as LS
    scan = LS.SCANNERS[broker](csvs)
    result: Dict[str, Any] = {"corrected": {}, "kept": {}}
    if scan.cands:
        accounts = [n for n, c in (_soft_config(root).get("accounts")
                                   or {}).items()
                    if isinstance(c, dict) and not c.get("crypto")]
        ev = LS.project_evidence(cache, accounts or [name],
                                 receiving=(name, broker))
        # ANY ticker.map line naming the listing (a rename either way,
        # DELETE, DISTINCT, a dated RENAME, and a lookup line: QUOTE,
        # T1135, an EXTRACT target ...) wins: `DISTINCT ROOT.US ROOT.TO`
        # keeps the row currency's listing, and a line written for the
        # listing as filed keeps meaning what it says.
        named = {str(x).upper()
                 for x in _ticker_map_named(root, lookups=True)}
        result = LS.resolve(scan, ev, account=name, broker=broker,
                            mapped=lambda s: s in named)
        # The TOBASE line of a correction's transfer journal, as the
        # join will read it (the explicit lines `ticker-map --suggest`
        # shows).
        from taxjson.lib.cross_listings import tobase_direction
        base = str(((_soft_config(root).get("settings") or {})
                    .get("base_currency")) or "").upper() or None
        for r in result["corrected"].values():
            o = str((r.get("pair") or {}).get("symbol") or "")
            if o and o != r["symbol"]:
                r["join"] = list(tobase_direction(o, r["symbol"], base))
    return LS.state_text(name, broker, result)


def stage_listing_suffix(name: str, broker: str, csvs: List[Path],
                         root: Path, cache: Path) -> Path:
    """work/<name>_<broker>_listing_suffix.state: the symbols of this
    group whose listing suffix came from the row currency alone and that
    the project's other books name as the other listing (lib/
    listing_suffix, tax-logic CA-XLIST-02 / US-XLIST-02). Written only
    when it changes — it is a dep of the parse, which books every row of
    such a symbol under that listing (--listing-fixes)."""
    from taxjson.lib import listing_suffix as LS
    out = LS.state_path(cache, name, broker)
    _LISTING_GROUPS.setdefault((cache.resolve(), name), {})[broker] = \
        list(csvs)
    text = _listing_suffix_text(name, broker, csvs, root, cache)
    if _read_work_stamp(out) != text:
        _write_work_stamp(out, text)
    return out


def _listing_suffix_stale(root: Path, cache: Path) -> List[str]:
    """The accounts whose listing evidence changed after every account
    was parsed (an account parsed before the one holding its evidence)."""
    from taxjson.lib import listing_suffix as LS
    out: List[str] = []
    for (c, name), groups in sorted(_LISTING_GROUPS.items()):
        if c != cache.resolve():
            continue
        for broker, csvs in sorted(groups.items()):
            text = _listing_suffix_text(name, broker, csvs, root, cache)
            if _read_work_stamp(LS.state_path(cache, name, broker)) != text:
                out.append(name)
                break
    return out


def _ticker_map_named(root: Path, lookups: bool = False) -> frozenset:
    """Every symbol a rule of the project's ticker.map names
    (taxjson_ticker_map.named_symbols; `lookups`: a lookup line's symbol
    too); empty without a map. A map that does not parse is refused by
    `taxjson run` up front."""
    tm = root / "ticker.map"
    if not tm.is_file():
        return frozenset()
    from taxjson.bin.taxjson_ticker_map import (_parse_map_file,
                                                named_symbols)
    try:
        return named_symbols(_parse_map_file(tm)[0], lookups=lookups)
    except (OSError, ValueError):
        return frozenset()


def _accounts_with_symbol_codes(inputs_dir: Path,
                                accounts: Dict[str, Any]) -> List[str]:
    """The equity accounts whose Questrade exports hold internal codes
    their own rows do not resolve: `taxjson run` parses every other
    account first, so the inference sees their transfers and names."""
    from taxjson.lib.brokerages.detect import detect
    from taxjson.lib.brokerages.questrade import scan_code_uses
    out = []
    for n, c in accounts.items():
        if not isinstance(c, dict) or c.get("crypto"):
            continue
        qt = []
        for csv in input_files(inputs_dir / n, ".csv"):
            try:
                if detect(csv).broker == "questrade":
                    qt.append(csv)
            except Exception:                      # noqa: BLE001
                continue    # the account's own stage reports the file
        try:
            if qt and scan_code_uses(qt):
                out.append(n)
        except Exception:                          # noqa: BLE001
            continue
    return out


def _transfer_key(root: Path):
    """The security a transfer row moves, after ticker.map's undated
    renames (the books are mapped by the merge stage; the transfer
    evidence is not)."""
    tm = root / "ticker.map"
    renames: Dict[str, str] = {}
    if tm.is_file():
        try:
            from taxjson.bin.taxjson_ticker_map import (load_map_file,
                                                        merge_renames)
            import contextlib as _cl
            import io as _io
            with _cl.redirect_stderr(_io.StringIO()):
                renames = merge_renames(load_map_file(tm), to_base=True)
        except (OSError, ValueError):
            renames = {}
    from taxjson.bin.taxjson_ticker_map import map_symbol

    def key(sym: str) -> str:
        s = str(sym or "").strip()
        return map_symbol(s, renames).upper() if renames else s.upper()
    return key


def transfer_arrivals(root: Path, cache: Path,
                      accounts: Optional[Dict[str, Any]] = None):
    """[transfer_in.Arrival] of every taxable equity account (the
    shares that arrived by transfer from outside the books), each
    marked covered when its account's converted .tt rows account for
    it. Read from work/ (the sidecars and the converted .tt files)."""
    from taxjson.lib import transfer_in as TI
    if accounts is None:
        accounts = _soft_config(root).get("accounts") or {}
    names = [n for n, c in accounts.items()
             if isinstance(c, dict) and c.get("type") == "taxable"
             and not c.get("crypto") and not c.get("transfers")]
    if not names:
        return []
    key = _transfer_key(root)
    # The taxable legs of the in-kind moves the run booked (lib/in_kind,
    # written to work/in_kind.json): a withdrawal's in leg is a purchase
    # at fair market value, not an arrival; a contribution's out leg
    # cancels nothing.
    _ik = in_kind_taxable_legs(cache)
    # The .tt JOURNAL legs too: a journal inside one account cancels
    # within its own pair (TI.own_journal_legs), with the broker's leg a
    # one-legged line stands beside — never another account's arrival
    # (pre-release review H1).
    found = TI.arrivals([r for r in TI.sidecar_rows(cache, names,
                                                    declared=True)
                         if _leg_ident(r[0], r[2]) not in _ik], key=key)
    tt_rows: Dict[str, List[Dict[str, Any]]] = {}
    import json as _json
    for n in {a.account for a in found}:
        rows: List[Dict[str, Any]] = []
        for tt in input_files(root / "inputs" / n, ".tt"):
            p = tt_json_path(cache, n, tt.name)
            try:
                doc = _json.loads(p.read_text(encoding="utf-8"))
            except (OSError, ValueError):
                continue
            rows += [t for t in (doc.get("transactions") or [])
                     if isinstance(t, dict)]
        tt_rows[n] = rows
    TI.mark_covered(found, tt_rows, key=key)
    # A missing_history.json entry is the user's own answer for the
    # position (cost unknown, reported by hand): it wins over the
    # broker's book value.
    from taxjson.lib.first_run import read_missing_history_pairs
    from taxjson.lib.missing_history import missing_history_path
    TI.mark_missing_history(found, read_missing_history_pairs(
        missing_history_path(root, note=False)))
    return found


def stage_transfer_arrivals(name: str, root: Path, cache: Path,
                            tt_jsons: List[Path], country: str
                            ) -> Optional[Path]:
    """The acquisitions a taxable account's books take for shares that
    arrived by transfer at a STATED book value
    (work/<name>_transfer_costs.json, a source of the books; None when
    there are none), and one ATTENTION line per kind of uncovered
    arrival — every run, so a fixed one (a .tt line covering it) goes
    quiet. tt_jsons: this account's converted .tt files, already
    written."""
    from taxjson.lib import transfer_in as TI
    out = cache / f"{name}{TRANSFER_COSTS_SUFFIX}"
    # In-kind moves to and from your registered accounts first: they
    # decide which transfer rows are not arrivals (lib/in_kind).
    _ik_rows = in_kind_state(root, cache, _soft_config(root)
                             .get("settings") or {}).rows.get(name, [])
    try:
        found = [a for a in transfer_arrivals(root, cache)
                 if a.account == name]
    except Exception as e:                          # noqa: BLE001
        _say("warning", f"transfer-ins not checked ({type(e).__name__}: "
             f"{e})", indent="  ")
        found = []
    rows = TI.booked_rows(found) + _ik_rows
    for ln in TI.attention_lines(found, country):
        _echo_captured(f"{ATTENTION_PREFIX} {ln}")
    if not rows:
        out.unlink(missing_ok=True)
        return None
    import json as _json
    text = _json.dumps({"transactions": rows,
                        # No source_brokerage: the fees report counts
                        # broker trades only (these are not trades).
                        "metadata": {"kind": "transfer_book_value",
                                     "account": name}},
                       indent=2, sort_keys=True) + "\n"
    try:
        same = out.read_text(encoding="utf-8") == text
    except OSError:
        same = False
    if not same:
        write_text_atomic(out, text)
    return out


IN_KIND_FILE = "in_kind.json"


def _leg_ident(account: str, t: Dict[str, Any]) -> Tuple[str, str, str, float]:
    """A transfer row's identity (lib/in_kind.Leg.ident)."""
    try:
        q = round(float(t.get("quantity") or 0.0), 8)
    except (TypeError, ValueError):
        q = 0.0
    return (account, str(t.get("symbol") or ""),
            str(t.get("date") or "")[:10], q)


def in_kind_taxable_legs(cache: Path) -> Set[Tuple[str, str, str, float]]:
    """The taxable transfer rows the last run's booked in-kind moves
    account for (work/in_kind.json)."""
    import json as _json
    try:
        doc = _json.loads((cache / IN_KIND_FILE).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return set()
    out = set()
    for m in (doc.get("moves") or []) if isinstance(doc, dict) else []:
        leg = m.get("taxable_leg") if isinstance(m, dict) else None
        if m.get("booked") and isinstance(leg, list) and len(leg) == 4:
            try:
                out.add((str(leg[0]), str(leg[1]), str(leg[2]),
                         round(float(leg[3]), 8)))
            except (TypeError, ValueError):
                continue
    return out


class _InKindState:
    """The in-kind moves of one run (lib/in_kind): the moves, the
    INKIND-line problems, the taxable accounts' booked rows, and the
    transfer rows possibly moved in kind in parts (lib/in_kind.in_parts)."""

    def __init__(self, moves=None, problems=None, rows=None, parts=None):
        self.moves = list(moves or [])
        self.problems = list(problems or [])
        self.rows: Dict[str, List[Dict[str, Any]]] = dict(rows or {})
        self.parts = list(parts or [])


# {work dir: _InKindState} — computed once per run (cmd_run clears it).
_IN_KIND_THIS_RUN: Dict[Path, _InKindState] = {}


def _in_kind_plans(accounts: Dict[str, Any], country: str) -> Dict[str, str]:
    """account -> "" (a taxable equity account whose transfer rows are
    kept out of the books) or its plan (a registered equity account)."""
    plans: Dict[str, str] = {}
    for n, c in (accounts or {}).items():
        if not isinstance(c, dict) or c.get("crypto"):
            continue
        if c.get("type") == "taxable":
            if not c.get("transfers"):
                plans[n] = ""
        elif c.get("type", "sheltered") == "sheltered":
            plans[n] = _account_plan(n, c, country)
    return plans


def _registered_transfer_rows(names: List[str], cache: Path
                              ) -> List[Tuple[str, str, Dict[str, Any]]]:
    """(account, broker, TRANSFER row) of registered accounts: the
    transfer sidecars (transfers = false) and the parsed exports'
    in-book TRANSFER rows (transfers = true), both before the books'
    currency conversion — the .tt JOURNAL legs included (the caller
    settles each journal inside its account: TI.movable_rows)."""
    import json as _json
    from taxjson.lib import transfer_in as TI
    rows = list(TI.sidecar_rows(cache, names, declared=True))
    longer = sorted(names, key=len, reverse=True)
    for n in names:
        others = [o for o in longer if o != n and o.startswith(f"{n}_")]
        for p in sorted(cache.glob(f"{n}_*.json")):
            if any(p.name.startswith(f"{o}_") for o in others):
                continue
            try:
                doc = _json.loads(p.read_text(encoding="utf-8"))
            except (OSError, ValueError):
                continue
            md = doc.get("metadata") if isinstance(doc, dict) else None
            # A broker parse (taxjson-brokerage's output) only.
            if (not isinstance(md, dict) or not md.get("format_version")
                    or not md.get("source_brokerage")
                    or md.get("kind")):
                continue
            broker = p.name[len(n) + 1:-len(".json")]
            for t in doc.get("transactions") or []:
                if (isinstance(t, dict) and t.get("action") == "TRANSFER"
                        and t.get("symbol") and t.get("account") == n):
                    rows.append((n, broker, t))
    return rows


def _inkind_lines(root: Path, names: List[str]
                  ) -> Tuple[List[Tuple[str, Dict[str, Any]]], List[str]]:
    """((account, INKIND line), problems) from the .tt files of the
    taxable accounts `names`."""
    from taxjson.bin.taxjson_convert_tt import parse_inkind_line
    from taxjson.lib.brokerages.base import shown_name
    from taxjson.lib.cli_diag import read_text_utf8
    out: List[Tuple[str, Dict[str, Any]]] = []
    problems: List[str] = []
    for n in names:
        for tt in input_files(root / "inputs" / n, ".tt"):
            try:
                text = read_text_utf8(tt)
            except (OSError, ValueError):
                continue
            for i, line in enumerate(text.splitlines(), 1):
                if "INKIND" not in line:
                    continue
                try:
                    ln = parse_inkind_line(line, f"{shown_name(tt)}:{i}")
                except ValueError as e:
                    problems.append(f"{e} — ignored")
                    continue
                if ln is not None:
                    out.append((n, ln))
    return out, problems


def _in_kind_close(root: Path, cache: Path):
    """The close lookup lib/in_kind.value uses: Yahoo's close on the
    move's date through the price chain (ticker.map QUOTE spelling, else
    the derived one), cached in work/.close_cache.json; TAXJSON_OFFLINE
    serves the cache only."""
    from taxjson.lib import in_kind as IK
    from taxjson.lib import price_chain as PC
    try:
        quote = PC.load_yf_map([root])
    except Exception:                               # noqa: BLE001
        quote = {}

    def close(m):
        q = quote.get(m.key)
        if q is not None and abs(float(q[1]) - 1.0) > 1e-9:
            return None             # a merged ticker's ratio: not a close
        ysym = q[0] if q is not None else PC.yf_symbol_for(m.key)
        if not ysym or PC.is_crypto_symbol(m.key):
            return None
        try:
            return PC.close_on(m.key, ysym, m.date,
                               cache_path=cache / ".close_cache.json")
        except PC.OfflineCloseMissing as e:
            raise IK.CloseUnavailable(str(e))
    return close


def in_kind_state(root: Path, cache: Path, settings: Dict[str, Any]
                  ) -> _InKindState:
    """The in-kind moves between your taxable and registered accounts
    (lib/in_kind; tax-logic CA-INKIND-* / US-INKIND-*), computed once per
    run from the transfer evidence in work/ (every equity account is
    parsed before any books are merged) and the taxable accounts' .tt
    INKIND lines; written to work/in_kind.json. A move that cannot be
    valued because TAXJSON_OFFLINE hides the close stops the run."""
    key_dir = cache.resolve()
    st = _IN_KIND_THIS_RUN.get(key_dir)
    if st is not None:
        return st
    from taxjson.lib import in_kind as IK
    from taxjson.lib.brokerages.detect import DISPLAY_NAMES
    cfg = _soft_config(root)
    accounts = cfg.get("accounts") or {}
    country = _normalize_country(settings.get("country")
                                 or (cfg.get("settings") or {})
                                 .get("country") or "canada")
    plans = _in_kind_plans(accounts, country)
    taxable = sorted(n for n, p in plans.items() if not p)
    registered = sorted(n for n, p in plans.items() if p)
    st = _InKindState()
    _IN_KIND_THIS_RUN[key_dir] = st
    if not taxable:
        (cache / IN_KIND_FILE).unlink(missing_ok=True)
        return st
    from taxjson.lib import transfer_in as TI
    key = _transfer_key(root)
    rows = list(TI.sidecar_rows(cache, taxable, declared=True))
    if registered:
        rows += _registered_transfer_rows(registered, cache)
    # A journal inside one account (its legs' pair id, a .tt JOURNAL
    # line) is never an in-kind move (pre-release review H1).
    rows = TI.movable_rows(rows)
    legs = IK.legs(rows, plans, key=key)
    lines, problems = _inkind_lines(root, taxable)
    own, declared = IK.line_legs(lines, legs, key=key)
    pairing = IK.pair_all(legs, own=own, declared=declared)
    moves = pairing.moves
    problems += IK.apply_lines(moves, lines, legs, key=key)
    st.parts = IK.in_parts(pairing)
    IK.decide(moves, country)
    IK.value(moves, _in_kind_close(root, cache),
             broker_names=DISPLAY_NAMES)
    st.moves, st.problems = moves, problems
    st.rows = IK.booked_rows(moves, country)
    import json as _json
    p = cache / IN_KIND_FILE
    if moves or problems or st.parts:
        text = _json.dumps({"metadata": {"kind": "in_kind_moves"},
                            "moves": [m.as_dict() for m in moves],
                            "problems": problems,
                            "in_parts": [
                                {"leg": list(g.ident()),
                                 "plan_legs": [list(h.ident())
                                               for h in hs]}
                                for g, hs in st.parts]},
                           indent=2, sort_keys=True) + "\n"
        try:
            same = p.read_text(encoding="utf-8") == text
        except OSError:
            same = False
        if not same:
            cache.mkdir(parents=True, exist_ok=True)
            write_text_atomic(p, text)
    else:
        p.unlink(missing_ok=True)
    offline = [m for m in moves if m.problem == "offline"]
    if offline:
        _die(f"{len(offline)} in-kind move(s) between your taxable and "
             f"registered accounts cannot be valued: TAXJSON_OFFLINE is "
             f"set and the close cache has no price for the date",
             *[f"{m.kind} {m.pair_text()}: {m.quantity:g} {m.symbol} on "
               f"{m.date} — add to a .tt file in inputs/"
               f"{m.taxable.account}/: INKIND {m.date} {m.symbol} "
               f"{(-m.quantity if m.kind == IK.CONTRIBUTION else m.quantity):g} "
               f"{m.taxable.currency or 'CAD'} <price per share>"
               for m in offline],
             "Or unset TAXJSON_OFFLINE to look the close up (an "
             "estimate). docs/getting-started.md, step 5c.")
    return st


def stage_in_kind_context(root: Path, cache: Path, settings: Dict[str, Any],
                          sheltered_base: Optional[Path]) -> Optional[Path]:
    """The loss-rule context (work/sheltered_base.json): each booked
    in-kind contribution's plan acquisition is a purchase for s.54 /
    §1091 whatever the transfer policy (CA-INKIND-04), and a withdrawal
    leg the context lacks is the plan's disposal (lib/in_kind.
    mark_sheltered). With no registered book in the project the context
    is written for those rows alone. Returns the context's path (None
    when there is none)."""
    from taxjson.lib import in_kind as IK
    st = in_kind_state(root, cache, settings)
    if not any(m.booked for m in st.moves):
        return sheltered_base
    import json as _json
    p = sheltered_base or (cache / "sheltered_base.json")
    if sheltered_base is None and p.exists():
        return None             # a previous run's context (--account)
    doc: Dict[str, Any] = {"transactions": []}
    if sheltered_base is not None:
        try:
            doc = _json.loads(p.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            return sheltered_base
    rows = doc.get("transactions") if isinstance(doc, dict) else None
    if not isinstance(rows, list):
        return sheltered_base
    n = IK.mark_sheltered(rows, st.moves, key=_transfer_key(root),
                          currency=str(settings.get("base_currency")
                                       or "").upper())
    if not n:
        return sheltered_base
    write_text_atomic(p, _json.dumps(doc, indent=2, sort_keys=True))
    from taxjson.lib.dispatch import run_cmd as _run_cmd
    vres = _run_cmd(_cmd("taxjson-validate") + [str(p)],
                    capture_output=True)
    if vres.returncode != 0:
        _echo_stage_stderr((vres.stdout or "") + (vres.stderr or ""))
        _die("the sheltered book with the in-kind contributions marked "
             "failed validation (details above)",
             "Check the transfer rows `taxjson transfers` labels "
             "in-kind, or value them with a .tt INKIND line.")
    return p


def _say_listing_spellings(root: Path) -> None:
    """The ticker.map lines that pair a bare ticker with a share listing
    where the books hold the ticker's US listing, not the bare symbol
    (taxjson_ticker_map.listing_spelling_notes): a DISTINCT line also
    keeps the US listing apart (Info); a rename-type line joins nothing
    (Warning naming the line to write). Advisory: never fatal."""
    tm = root / "ticker.map"
    if not tm.is_file():
        return
    try:
        from taxjson.bin.taxjson_ticker_map import listing_spelling_notes
        from taxjson.lib.cli_diag import read_text_utf8
        from taxjson.lib.ticker_map_suggest import books_symbols
        infos, warns = listing_spelling_notes(
            read_text_utf8(tm), tm.name, books_symbols(root))
    except Exception:                               # noqa: BLE001
        return
    for m in infos:
        _say_once(("spelling", m), "note", m, prog=_PROG)
    for m in warns:
        _say_once(("spelling", m), "warning", m, prog=_PROG)


def _say_xlist_losses(root: Path, cfg: Dict[str, Any], cache: Path, *,
                      strict: bool = False) -> None:
    """A loss on one listing and a purchase of another listing of the
    same root under an equal name within 30 days (lib/xlist_loss_radar,
    tax-logic CA-XLIST-05 / US-XLIST-04): one Warning per pair naming the
    TOBASE and DISTINCT lines that answer it, the findings written to
    work/xlist_loss_radar.state (`ticker-map --suggest`, `scan`);
    `strict`: a pair the map does not answer stops the run. Advisory: a
    failure to read the books is never fatal."""
    from taxjson.lib import xlist_loss_radar as XR
    from taxjson.lib.country import settings_country
    country = settings_country(cfg.get("settings") or {})
    try:
        found = XR.analyze(root, cfg)
    except Exception as e:                          # noqa: BLE001
        _say("warning", f"the cross-listing loss check failed: {e}",
             prog=_PROG)
        return
    state = cache / XR.STATE
    text = XR.state_text(found, country)
    if _read_work_stamp(state) != text:
        _write_work_stamp(state, text)
    if not found:
        return
    for f in found[:XR.RADAR_SHOWN]:
        head, details = XR.message(f.record(), country)
        _say_once(("xlist-loss", f.loss_symbol, f.other_symbol), "warning",
                  head, *details, indent="  ", file=sys.stdout)
    if len(found) > XR.RADAR_SHOWN:
        # The rest counted in one line (third pre-release review,
        # finding 9: one Warning per pair flooded the console).
        head, details = XR.more_message(len(found) - XR.RADAR_SHOWN,
                                        country)
        _say_once(("xlist-loss-more",), "warning", head, *details,
                  indent="  ", file=sys.stdout)
    if strict:
        _die(f"--strict: {len(found)} possible "
             f"{XR._kind(country, len(found))} across listings (warning "
             f"above) — aborting",
             "Add the TOBASE line (one security) or the DISTINCT line (two) "
             "to ticker.map.")


def _say_in_kind(root: Path, cache: Path, settings: Dict[str, Any], *,
                 strict: bool = False) -> None:
    """ONE warning per run: each in-kind move booked (accounts, symbol,
    quantity, date, value and its source, the gain or the denied loss
    from the books) and each one not booked (CA-INKIND-* /
    US-INKIND-*). `strict`: a move not booked stops the run."""
    st = _IN_KIND_THIS_RUN.get(cache.resolve())
    if st is None:
        return
    from taxjson.lib import in_kind as IK
    pm = IK.parts_message(st.parts)
    if pm is not None and ("inkind-parts",) not in _SHOWN_THIS_RUN:
        _SHOWN_THIS_RUN.add(("inkind-parts",))
        _say("warning", pm[0], *pm[1], indent="  ", file=sys.stdout)
        if strict:
            _die(f"--strict: {len(st.parts)} transfer row(s) of a taxable "
                 f"account possibly in-kind in parts (warning above)",
                 "Answer each with a .tt INKIND line (the move's value, "
                 "or plan=own); nothing else was changed.")
    if ("inkind",) in _SHOWN_THIS_RUN:
        return
    from taxjson.lib.report_model import resolve_gains_files
    import json as _json
    docs = []
    for _a, p in resolve_gains_files(cache).items():
        try:
            docs.append(_json.loads(p.read_text(encoding="utf-8")))
        except (OSError, ValueError):
            continue
    key = _transfer_key(root)
    res = IK.contribution_results(docs, key=key)
    msg = IK.message(st.moves, st.problems, res,
                     _normalize_country(settings["country"]),
                     str(settings.get("base_currency") or "").upper())
    if msg is None:
        return
    _SHOWN_THIS_RUN.add(("inkind",))
    _say("warning", msg[0], *msg[1], indent="  ", file=sys.stdout)
    _unbooked = [m for m in st.moves if not m.booked]
    if strict and (_unbooked or st.problems):
        _die(f"--strict: {len(_unbooked) + len(st.problems)} in-kind "
             f"move(s) or INKIND line(s) not booked (warning above)",
             "Value each with a .tt INKIND line, or fix the transfer "
             "rows; nothing else was changed.")


def _sidecar_transfer_rows(names: List[str], cache: Path
                           ) -> List[Tuple[str, Dict[str, Any]]]:
    """(account, TRANSFER row) of every `names` account's transfer
    sidecars (transfers = false keeps TRANSFER rows out of the books),
    less the legs of a journal inside one account (a broker's journal
    pair, a .tt JOURNAL line: lib/transfer_in.movable_rows) — a journal
    never pairs with another account's leg (pre-release review H1)."""
    from taxjson.lib import transfer_in as TI
    rows = []
    for n, _b, t in TI.movable_rows(TI.sidecar_rows(cache, names,
                                                    declared=True)):
        try:
            if abs(float(t.get("quantity") or 0)) > 1e-9:
                rows.append((n, t))
        except (TypeError, ValueError):
            continue
    return rows


def _custody_pairing(names: List[str], cache: Path
                     ) -> Tuple[List[Dict[str, Any]], List[Dict[str, Any]]]:
    """(moves, unpaired): moves of a security between two of these
    accounts, read from the transfer sidecars — an outbound leg in one
    account paired with inbound legs of the same symbol in ONE other
    account, within _OWN_MOVE_DAYS: one leg of the same quantity, else
    two that add up to it (a delivery in two parts). `unpaired`: the
    outbound legs left over that still have an inbound leg of the
    symbol in another of the accounts inside the window — they look
    like a move whose quantities do not pair."""
    from datetime import date as _date
    rows = _sidecar_transfer_rows(names, cache)

    def _d(t):
        try:
            return _date.fromisoformat(str(t.get("date"))[:10])
        except ValueError:
            return None

    def _near(t, u):
        da, db = _d(t), _d(u)
        return (da is not None and db is not None
                and abs((db - da).days) <= _OWN_MOVE_DAYS)
    ins = [(n, t) for n, t in rows if float(t["quantity"]) > 0]
    outs = sorted(((n, t) for n, t in rows if float(t["quantity"]) < 0),
                  key=lambda e: (str(e[1].get("date")), e[0]))
    used: set = set()
    moves: List[Dict[str, Any]] = []
    left = []
    for a, t in outs:
        q = -float(t["quantity"])
        cands = [i for i, (b, u) in enumerate(ins)
                 if i not in used and b != a
                 and u.get("symbol") == t.get("symbol") and _near(t, u)]
        pick = next(([i] for i in cands
                     if abs(float(ins[i][1]["quantity"]) - q) <= 1e-6),
                    None)
        if pick is None:
            for x in range(len(cands)):
                for y in range(x + 1, len(cands)):
                    i, j = cands[x], cands[y]
                    if (ins[i][0] == ins[j][0]
                            and abs(float(ins[i][1]["quantity"])
                                    + float(ins[j][1]["quantity"]) - q)
                            <= 1e-6):
                        pick = [i, j]
                        break
                if pick:
                    break
        if pick is None:
            left.append((a, t))
            continue
        used.update(pick)
        for i in pick:
            b, u = ins[i]
            moves.append({"symbol": t["symbol"],
                          "qty": float(u["quantity"]), "from": a, "to": b,
                          "date_out": str(t.get("date")),
                          "date_in": str(u.get("date"))})
    unpaired = []
    for a, t in left:
        near = [(b, u) for i, (b, u) in enumerate(ins)
                if i not in used and b != a
                and u.get("symbol") == t.get("symbol") and _near(t, u)]
        if near:
            unpaired.append({
                "symbol": t["symbol"], "qty": -float(t["quantity"]),
                "from": a, "date_out": str(t.get("date")),
                "ins": [(b, float(u["quantity"]), str(u.get("date")))
                        for b, u in near]})
    return moves, unpaired


def own_account_custody_moves(names: List[str], cache: Path
                              ) -> List[Dict[str, Any]]:
    """Moves of a security between two of these accounts (the paired
    legs of _custody_pairing)."""
    return _custody_pairing(names, cache)[0]


OWN_MOVES_SUFFIX = "_own_moves.json"


def _move_legs(moves: List[Dict[str, Any]], currency: str = ""
               ) -> Dict[str, List[Dict]]:
    """{account: [TRANSFER lot_move rows]}: each move as an out leg in
    the sender and an in leg in the receiver at the same moment (the
    earlier of the two dates; securities at the start of that day), the
    pair told apart from any other by its numbered description."""
    from taxjson.lib.core import LOT_MOVE_TYPE
    out: Dict[str, List[Dict]] = {}
    for k, m in enumerate(sorted(
            moves, key=lambda m: (m["date"], m.get("time") or "",
                                  m["symbol"], m["from"], m["to"],
                                  m["qty"])), 1):
        desc = (f"own-account move #{k}: {m['from']} -> {m['to']} "
                f"(basis and purchase dates carried)")
        for acct, q in ((m["from"], -m["qty"]), (m["to"], m["qty"])):
            out.setdefault(acct, []).append({
                "action": "TRANSFER", "type": LOT_MOVE_TYPE,
                "date": m["date"], "date_settle": m["date"],
                "time": m.get("time") or "00:00:00",
                "symbol": m["symbol"], "quantity": float(q),
                "price": 0.0, "net_amount": 0.0, "currency": currency,
                "account": acct, "description": desc})
    return out


def stage_own_account_moves(root: Path, cfg: Dict[str, Any],
                            settings: Dict[str, Any], cache: Path, *,
                            strict: bool = False) -> List[Dict[str, Any]]:
    """US projects (tax-logic US-BASIS-05, US-CRYPTO-05): a move between
    two of your own TAXABLE accounts is not a sale — the moved lots keep
    their basis and purchase dates, and the US books keep lots per
    account, so the run carries them. Securities pair from the transfer
    sidecars; coins from the crypto-sends pairing. Each account gets
    work/<account>_own_moves.json, a source of its books: the TRANSFER
    legs the US engine books as a lot move (the blended pass hands the
    sender's FIFO lots to the receiver). Legs that look like a move but
    do not pair are said as ATTENTION (--strict stops). Canada pools
    the ACB across the accounts (s.47): no legs, nothing to say.
    Returns the moves."""
    from taxjson.lib.country import basis_pooled_across_accounts
    accounts = cfg.get("accounts") or {}
    taxable = [n for n, c in accounts.items()
               if (c or {}).get("type") == "taxable"
               and not (c or {}).get("transfers")]
    moves: List[Dict[str, Any]] = []
    unpaired: List[Dict[str, Any]] = []
    if not basis_pooled_across_accounts(_country(settings)):
        equity = [n for n in taxable if not accounts[n].get("crypto")]
        crypto = [n for n in taxable if accounts[n].get("crypto")]
        if len(equity) >= 2:
            em, unpaired = _custody_pairing(equity, cache)
            for m in em:
                m["date"] = min(m["date_out"][:10], m["date_in"][:10])
                m["time"] = "00:00:00"
            moves += em
        if len(crypto) >= 2:
            from taxjson.lib import crypto_sends as CS
            try:
                moves += CS.own_moves(root, cfg, crypto,
                                      _crypto_broker_files(root, cfg))
            except ValueError as e:
                _say("warning", f"crypto moves between your accounts not "
                     f"paired: {e}", indent="  ")
        moves = _mapped_moves(moves, root)
    from taxjson.lib.country import home_currency
    legs = _move_legs(moves, str(settings.get("base_currency")
                                 or home_currency(_country(settings))
                                 ).upper())
    import json as _json
    for n in accounts:
        p = cache / f"{n}{OWN_MOVES_SUFFIX}"
        rows = legs.get(n) if n in taxable else None
        if not rows:
            if p.exists():
                p.unlink()
            continue
        text = _json.dumps({"transactions": rows,
                            "metadata": {"kind": "own_account_moves",
                                         "account": n}},
                           indent=2, sort_keys=True) + "\n"
        try:
            same = p.read_text(encoding="utf-8") == text
        except OSError:
            same = False
        if not same:
            cache.mkdir(parents=True, exist_ok=True)
            p.write_text(text, encoding="utf-8")
    from taxjson.lib.out import show as _show, width as _ow
    for m in moves:
        _mv = (f"own-account move: {m['symbol']} {m['qty']:g} "
               f"{m['from']} -> {m['to']} ({m['date']}): not a sale — "
               f"the lots' basis and purchase dates go to {m['to']}.")
        if _ow(sys.stdout) > 0:
            # The run's console: a message, flush-left.
            _show(_out_wrap("Info: " + _mv[:1].upper() + _mv[1:], hang=""),
                  sys.stdout)
            continue
        for _ln in _out_wrap(_mv, indent="  ", hang="    "):
            print(_ln)
    for u in unpaired:
        ins = ", ".join(f"{q:g} into {b} ({d})" for b, q, d in u["ins"])
        _say("attention", f"{u['symbol']}: {u['qty']:g} moved out of "
             f"{u['from']} ({u['date_out']}) and {ins} look like a move "
             f"between your own accounts, but the quantities do not pair",
             f"The lots are NOT carried: {u['from']} keeps them and the "
             f"receiving account's sales read as a short. Check the "
             f"transfer rows (`taxjson transfers`) and report those sales "
             f"by hand (US-BASIS-05).", indent="  ")
    if unpaired and strict:
        _die(f"--strict: {len(unpaired)} transfer(s) between your own "
             f"taxable accounts that do not pair (warning above) — "
             f"aborting")
    return moves


def _mapped_moves(moves: List[Dict[str, Any]], root: Path
                  ) -> List[Dict[str, Any]]:
    """The moves' symbols through ticker.map's undated renames (the
    books are mapped by the merge stage; the transfer evidence is not)."""
    tm = root / "ticker.map"
    if not moves or not tm.is_file():
        return moves
    try:
        from taxjson.bin.taxjson_ticker_map import (load_map_file,
                                                    map_symbol,
                                                    merge_renames)
        import contextlib as _cl
        import io as _io
        with _cl.redirect_stderr(_io.StringIO()):
            renames = merge_renames(load_map_file(tm), to_base=True)
    except (OSError, ValueError):
        return moves
    return [dict(m, symbol=map_symbol(m["symbol"], renames)) for m in moves]


def stage_blended_wash_pass(names: List[str],
                            settings: Dict[str, Any], cache: Path,
                            reports_dir: Path,
                            sheltered_base: Optional[Path],
                            incomplete_history: Optional[Path] = None,
                            tag: str = "blend",
                            no_wash: bool = False,
                            spot_crypto: bool = False,
                            strict: bool = False
                            ) -> None:
    """ONE combined gains run over every taxable equity account, split
    back into the per-account `<name>_gains_wash.json` artifacts.
    `tag="cryptoblend"` runs the same pass over a Canadian project's
    crypto accounts (ITA s.47 averaging and the superficial-loss rule
    reach identical crypto held on different exchanges) with its own
    dot-prefixed intermediates.

    This is what makes the canonical (filed-from) numbers correct for
    multi-account books: Canada's ACB blends across all non-registered
    accounts (ITA s.47 — the engine's symbol-global pools do this
    naturally on a combined input) and US §1091 wash matching spans
    accounts while FIFO basis stays per account (--per-account-basis).
    Single-account projects produce identical numbers by construction.
    The per-account `<name>.sum` stays the isolated pre-blend baseline —
    comparing the pair shows exactly what blending changed."""
    _us = _normalize_country(settings["country"]) in ("us", "usa")
    _what = "crypto" if tag != "blend" else "taxable"
    if no_wash:
        _step(f"Carrying lots across {_what} accounts ({', '.join(names)})")
    elif _us:
        _step(f"Checking wash sales across {_what} accounts "
              f"({', '.join(names)})")
    else:
        _step(f"Pooling cost and checking superficial losses across "
              f"{_what} accounts ({', '.join(names)})")
    # Dot-prefixed intermediates: pathlib globs DO match leading dots
    # (`*_base.json` matches `.blend_base.json`), so every discovery
    # site — resolve_gains_files and the radar/missing-history fallback
    # globs — must ALSO filter `startswith(".")` explicitly. A visible
    # name here (or a glob site without the dot filter) would be
    # discovered as a spurious account and every aggregate would
    # double-count.
    combined_base = cache / f".{tag}_base.json"
    run_to_file(_cmd("taxjson-merge") + [
        str(cache / f"{n}_base.json") for n in names], combined_base)
    combined_wash = cache / f".{tag}_gains_wash.json"
    wash_traces = cache / f".{tag}_gains_wash.traces"
    country = _normalize_country(settings["country"])
    cmd = _cmd("taxjson-gains") + [
        "--taxable",
        "--country", country,
        "--year", str(settings["year"]),
        "--tax-date", _tax_date(settings),
        "--full-traces", str(wash_traces),
    ]
    if _normalize_country(country) in ("us", "usa"):
        cmd.append("--per-account-basis")
    if no_wash:
        # A US project's crypto accounts (§1091 does not reach digital
        # assets): blended only so moves between them carry their lots.
        cmd.append("--no-wash")
    if spot_crypto:
        cmd.append("--spot-crypto")
    if sheltered_base is not None and not no_wash:
        cmd += ["--sheltered", str(sheltered_base)]
    cmd += option_timing_flags(settings)
    cmd += income_dating_flags(settings)
    cmd += _locked_year_flags(cache.parent, settings)
    if incomplete_history is not None:
        cmd += ["--incomplete-history", str(incomplete_history)]
    cmd.append(str(combined_base))
    run_to_file(cmd, combined_wash)
    if sheltered_base is not None and not no_wash:
        _LOSS_CONTEXT_GAINS.append(combined_wash)
    # A wash-sale basis add that reaches a sale in a filed year (US-WASH-22)
    # is decided only here, across accounts: on the console.
    from taxjson.lib.pipeline import ATTENTION_WASH_LOCKED
    echo_attention_lines(combined_wash,
                         prefix=ATTENTION_WASH_LOCKED[len("ATTENTION: "):],
                         once=True)
    # A move between your own accounts that the sender's lots cannot
    # back (US-BASIS-05): on the console, and --strict stops.
    echo_attention_lines(combined_wash, prefix="own-account move: ",
                         once=True)
    _mv = [ln for ln in _diag_lines(combined_wash)
           if ln.startswith(ATTENTION_PREFIX + " own-account move: ")]
    if _mv and strict:
        _die(f"--strict: {len(_mv)} move(s) between your own accounts "
             f"the sending account's lots do not cover (warning above) "
             f"— aborting")
    # The blended run's stderr lands in .blend_gains_wash.json.diag —
    # dot-prefixed, so collect_diagnostics' {account}_*.diag glob can
    # never surface it, and it is the ONLY pass that sees --sheltered
    # (its NOTEs explain the filed numbers). Mirror it into a per-
    # account diag each blended account's .sum banner picks up
    # (2026-09 audit).
    _blend_diag = combined_wash.with_name(combined_wash.name + ".diag")
    for name in names:
        _mirror = cache / f"{name}_{tag}.diag"
        if _blend_diag.exists() and _blend_diag.stat().st_size:
            _mirror.write_text(_blend_diag.read_text(errors="replace"),
                               encoding="utf-8")
        else:
            _mirror.unlink(missing_ok=True)
    for name in names:
        wash_gains = cache / f"{name}_gains_wash.json"
        # The split writes no .diag: a single-account wash pass's old
        # one would otherwise stay in this account's banner (S038-20).
        wash_gains.with_name(wash_gains.name + ".diag").unlink(
            missing_ok=True)
        run_to_file(_cmd("taxjson-split-gains") + [
            str(combined_wash), "--account", name,
            "--base", str(cache / f"{name}_base.json"),
        ], wash_gains, capture_diag=False)
        _render_wash_outputs(name, settings, cache, reports_dir,
                             wash_gains, cache / f"{name}_base.json",
                             blended=True)
    # Conservation check: the splitter apportions blended inventory
    # rows by each account's BASE-book balance, which does not include
    # missing-history (OPENING_BALANCE) shares synthesized in-memory
    # from missing_history.json — those shares silently vanish from every
    # per-account holding. Compare Σ per-account qty vs the blended
    # row and say so instead of staying silent.
    try:
        import json as _json
        for _msg in _blend_conservation_gaps(
                _json.loads(combined_wash.read_text(encoding="utf-8")),
                [_json.loads((cache / f"{name}_gains_wash.json")
                             .read_text(encoding="utf-8"))
                 for name in names]):
            _echo_captured(f"{_PROG}: warning: {_msg}", indent="",
                           file=sys.stderr, source=False)
    except (OSError, ValueError, AttributeError):
        pass


def _blend_conservation_gaps(blended_doc: Dict[str, Any],
                             split_docs: List[Dict[str, Any]]) -> List[str]:
    """One message per blended inventory row whose per-account split
    does not add back up to it (the blended-pass conservation check —
    pinned by tests, G1-13)."""
    blended_inv = {r.get("symbol"): float(r.get("qty") or 0.0)
                   for r in (blended_doc.get("inventory") or [])
                   if not r.get("account")}
    split_sums: Dict[str, float] = {}
    for doc in split_docs:
        for r in (doc.get("inventory") or []):
            if r.get("blended_pool"):
                split_sums[r.get("symbol")] = (
                    split_sums.get(r.get("symbol"), 0.0)
                    + float(r.get("qty") or 0.0))
    out: List[str] = []
    for sym, total in sorted(blended_inv.items()):
        got = split_sums.get(sym, 0.0)
        # Name the direction (audit A2-0021/A2-0074: an EXCESS was
        # reported as 'only ... under-report' and blamed on the
        # missing-history openings).
        if total - got > 1e-4:
            out.append(f"blended {sym} holds {total:g} but the per-account "
                       f"split accounts for only {got:g} — "
                       f"{total - got:g} short. Shares from missing_history.json "
                       f"cannot be attributed to an account; otherwise a "
                       f"rename or split of {sym} is read differently by "
                       f"the per-account walk. Per-account holdings "
                       f"under-report by the gap.")
        elif got - total > 1e-4:
            out.append(f"blended {sym} holds {total:g} but the per-account "
                       f"split accounts for {got:g} — {got - total:g} MORE "
                       f"than the pool. Check the renames and splits of "
                       f"{sym} (and any ticker reused after a rename). "
                       f"Per-account holdings over-report by the excess.")
    return out


# The watchlist exports (Seeking Alpha *_SA.csv, FastGraph *_FG.csv,
# TradingView *_TV.txt) an earlier version wrote to reports/exports/ and
# this one no longer does: an outdated copy would read as current, so a
# full run removes them, and the folder once nothing else is in it.
_RETIRED_EXPORTS: Tuple[str, ...] = ("*_SA.csv", "*_FG.csv", "*_TV.txt")


def _sweep_retired_exports(reports_dir: Path) -> None:
    """Remove the retired watchlist exports (_RETIRED_EXPORTS) an earlier
    run left in reports/exports/, then the folder if that empties it — in
    one line. A file of the user's own there (another name) is kept, and
    so is the folder."""
    exports_dir = reports_dir / "exports"
    if not exports_dir.is_dir() or exports_dir.is_symlink():
        return
    gone = 0
    for pattern in _RETIRED_EXPORTS:
        for p in sorted(exports_dir.glob(pattern)):
            if p.is_file() or p.is_symlink():
                p.unlink()
                gone += 1
    try:
        exports_dir.rmdir()
        removed_dir = True
    except OSError:          # not empty: the user's own files stay
        removed_dir = False
    if not gone and not removed_dir:
        return
    what = (f"{gone} old watchlist file(s) in "
            f"{reports_dir.name}/exports/")
    if removed_dir:
        what += " and the folder"
    _say("note", f"removed {what} (the Seeking Alpha / FastGraph / "
         f"TradingView exports were removed)", indent="  ",
         file=sys.stdout)


def _duplicate_input_files(inputs_dir: Path,
                           accounts: Dict[str, Any]) -> List[List[str]]:
    """Groups of input files (inputs/<account>/*.csv|.tt) with identical
    content that sit under two or more DIFFERENT configured accounts —
    a copied export books every row twice, and parsers whose rows carry
    no broker account (Kraken, a .tt, an IB dividend) had no check at all
    (audit A2-0366). Whitespace-only files are ignored. Each group lists
    `account/file` names."""
    import hashlib
    by_hash: Dict[str, List[Tuple[str, str]]] = {}
    for name in sorted(accounts or {}):
        d = inputs_dir / name
        for p in input_files(d, ".csv") + input_files(d, ".tt"):
            try:
                data = p.read_bytes()
            except OSError:
                continue
            if not data.strip():
                continue
            by_hash.setdefault(hashlib.sha256(data).hexdigest(), []).append(
                (name, f"{name}/{p.name}"))
    return [[f for _a, f in grp] for grp in by_hash.values()
            if len({a for a, _f in grp}) > 1]


def _duplicate_crypto_exports(cache: Path, names: List[str]) -> List[str]:
    """One line per pair of crypto accounts whose parsed exchange rows
    share transaction ids: the same export filed under two accounts is
    booked twice (re-audit A2-0569; the per-account dedup only sees one
    account). Exchange ids are unique per row (Coinbase IDs, Kraken
    txids; a content hash when the export has none)."""
    import json as _json
    ids: Dict[str, Dict[str, str]] = {}
    for n in names:
        mine: Dict[str, str] = {}
        for b in ("coinbase", "kraken"):
            p = cache / f"{n}_{b}.json"
            try:
                doc = _json.loads(p.read_text(encoding="utf-8"))
            except (OSError, ValueError):
                continue
            for t in doc.get("transactions") or []:
                if t.get("id"):
                    mine[str(t["id"])] = b
        ids[n] = mine
    out = []
    for i, a in enumerate(names):
        for b in names[i + 1:]:
            both = set(ids.get(a, {})) & set(ids.get(b, {}))
            if both:
                ex = sorted({ids[a][k] for k in both})
                out.append(
                    f"crypto accounts {a} and {b} hold {len(both)} "
                    f"identical {'/'.join(ex)} row(s) (the same "
                    f"transaction ids): the same export is in both "
                    f"inputs/{a}/ and inputs/{b}/, so its trades are "
                    f"booked twice. Keep it in one account.")
    return out


def _warn_shared_broker_accounts(bases: List[Tuple[str, Path]]) -> int:
    """One broker account's export in TWO taxjson accounts books every
    row twice (audit A2-0293, A2-0630). The rows carry their broker
    account (hashed, `source_account`); name each pair of taxjson
    accounts that share one, with the count of identical rows."""
    import json
    seen: Dict[str, Dict[str, set]] = {}
    for name, base in bases:
        try:
            rows = json.loads(Path(base).read_text()).get("transactions")
        except (OSError, ValueError, AttributeError):
            continue
        per: Dict[str, set] = {}
        for t in rows or ():
            if isinstance(t, dict) and t.get("source_account"):
                # The id hashes the taxjson account label: compare the
                # row's content instead.
                per.setdefault(t["source_account"], set()).add(
                    (t.get("date"), t.get("action"), t.get("symbol"),
                     t.get("quantity"), t.get("net_amount")))
        seen[name] = per
    names = sorted(seen)
    shared = 0
    for i, a in enumerate(names):
        for b in names[i + 1:]:
            for h in sorted(set(seen[a]) & set(seen[b])):
                shared += 1
                same = len(seen[a][h] & seen[b][h])
                _say("attention", f"the same broker account (#{h[:6]}) "
                     f"feeds two taxjson accounts, {a} and {b} ({same} "
                     f"identical row(s))",
                     "Every row of it is booked in BOTH. Put each broker "
                     "account's exports under ONE inputs/<account>/ "
                     "folder.", indent="  ", file=sys.stdout)
    return shared


def _warn_cross_taxable_overlap(taxable_bases: List[Tuple[str, Path]],
                                settings: Dict[str, Any]) -> None:
    """Loud caveat for the KNOWN_ISSUES multi-account gap: when the SAME
    security appears in two or more TAXABLE accounts, the per-account
    fan-out computes legally wrong numbers — Canada's ACB must blend
    across all non-registered accounts (ITA s. 47), and US §1091 wash
    matching between two taxable accounts is not performed. This was
    entirely silent before; the run now names the overlapping symbols.
    This function only detects the overlap; the blended pass (the
    per-kind blended wash run) computes the blended numbers."""
    import json as _json
    if len(taxable_bases) < 2:
        return
    by_symbol: Dict[str, set] = {}
    for name, base in taxable_bases:
        try:
            doc = _json.loads(Path(base).read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        for t in doc.get("transactions", []):
            # A position moved in kind into the account (a declared
            # TRANSFER) is held there too (re-audit A2-1231).
            if t.get("action") in ("BUYSELL", "ASSIGN", "OPENING_BALANCE",
                                   "TRANSFER"):
                sym = (t.get("symbol") or "").strip()
                if sym:
                    by_symbol.setdefault(sym, set()).add(name)
    overlap = sorted(s for s, accts in by_symbol.items() if len(accts) > 1)
    if not overlap:
        return
    country = _country(settings)
    consequence = (
        "the blended pass matches US §1091 wash sales across accounts "
        "(FIFO basis stays per account)"
        if country in ("us", "usa") else
        "the blended pass computes their ACB across all non-registered "
        "accounts (ITA s. 47)")
    shown = ", ".join(overlap[:8]) + (
        f" (+{len(overlap) - 8} more)" if len(overlap) > 8 else "")
    _say("note", f"{shown} traded in more than one TAXABLE account",
         f"{consequence[0].upper()}{consequence[1:]}. The wash-adjusted "
         f"artifacts (<account>_wash.sum — the canonical filing numbers) "
         f"carry the blended figures; the per-account <account>.sum "
         f"baseline stays isolated, so the pair shows what blending "
         f"changed.", prog=_PROG)


def _wash_preferred_gains(p: Path) -> Path:
    """The gains file the cross reports should read for a taxable
    account: the wash-adjusted twin when it exists and is at least as
    fresh, else the plain file. Same basis as the query twins —
    ccd-sum/leaps-sum resolve the wash-adjusted files, so building
    reports/ccd.rpt and leaps.rpt from pre-wash inputs made them
    disagree whenever a wash adjustment touched an option disposition.
    Freshness-guarded so a stale wash file from an older run (e.g. an
    account the wash pass no longer covers) can't shadow the
    just-rebuilt gains."""
    w = p.with_name(p.name.replace("_gains.json", "_gains_wash.json"))
    return w if (w.exists() and p.exists()
                 and w.stat().st_mtime >= p.stat().st_mtime) else p


def stage_cross_reports(all_gains: List[Path],
                        taxable_equity_base: List[Path],
                        sheltered_base: Optional[Path],
                        reports_dir: Path,
                        ticker_map: Optional[Path] = None,
                        missing_history: Optional[Path] = None,
                        *, country: str) -> None:
    if not all_gains:
        return
    _step(f"Writing cross-account reports to "
          f"{_out_relpath(reports_dir, reports_dir.parent)}/")
    run_to_file(_cmd("taxjson-ccd-gains") + [str(p) for p in all_gains],
                reports_dir / "ccd.rpt", capture_diag=False)
    run_to_file(_cmd("taxjson-leaps-gains") + [str(p) for p in all_gains],
                reports_dir / "leaps.rpt", capture_diag=False)
    if taxable_equity_base:
        # --sheltered adds the cross-account (registered-repurchase) column to
        # the radar, but it's optional: same-account superficial-loss detection
        # runs without it, so the radar still generates for a taxable-only
        # project that defines no registered account.
        sheltered_arg = (["--sheltered", str(sheltered_base)]
                         if sheltered_base else [])
        for tb in taxable_equity_base:
            # Strip only the trailing "_base": replace() removed EVERY
            # "_base", so account a_base_x wrote account a_x's radar
            # (S038-10).
            stem = (tb.name[:-len("_base.json")]
                    if tb.name.endswith("_base.json") else tb.stem)
            # --json-out: structured sidecar next to the .rpt (harvest
            # --radar reads it and computes countdowns at its own time).
            run_to_file(_cmd("taxjson-wash-radar") + [
                "--taxable", str(tb),
                "--json-out", str(reports_dir / f"wash_radar_{stem}.json"),
                "--account", stem,
            ] + _radar_engine_args([tb], missing_history, country)
                + sheltered_arg, reports_dir / f"wash_radar_{stem}.rpt",
                capture_diag=False)
        if len(taxable_equity_base) > 1:
            # Cross-account radar: a loss sold in one taxable account
            # with a rebuy in another IS a wash/superficial trigger
            # (the blended engine disallows it), but each per-account
            # sidecar sees only its own book. One combined run over
            # all taxable bases writes the sidecar harvest's ADVISORY
            # reads — matching what the engine will actually do. The
            # per-account files stay as the same-account views.
            run_to_file(_cmd("taxjson-wash-radar") + [
                "--taxable", *[str(tb) for tb in taxable_equity_base],
                "--json-out",
                str(reports_dir / "wash_radar_COMBINED.json"),
                "--account", "COMBINED",
            ] + _radar_engine_args(taxable_equity_base, missing_history,
                                   country)
                + sheltered_arg, reports_dir / "wash_radar_COMBINED.rpt",
                capture_diag=False)
        else:
            # Down to one taxable account: a leftover COMBINED pair
            # from an earlier multi-account state would shadow the
            # fresh per-account sidecar in harvest forever.
            for _ext in (".json", ".rpt"):
                _p = reports_dir / f"wash_radar_COMBINED{_ext}"
                if _p.exists():
                    _p.unlink()
        # Cross-listing lint: flag any root on both .TO and .US that the radar
        # would treat as two securities but maybe shouldn't (a TOBASE that
        # didn't consolidate, or a newly-traded interlisting missing from the
        # map). Advisory only — never fails the run.
        cmd = _cmd("taxjson-lint-crosslistings") + [
            "--taxable", *[str(tb) for tb in taxable_equity_base],
        ] + sheltered_arg
        if ticker_map:
            cmd += ["--map", str(ticker_map)]
        run_to_file(cmd, reports_dir / "crosslistings.rpt", capture_diag=False)


def stage_fees(cache: Path, settings: Dict[str, Any], rates: Path,
               reports_dir: Path) -> None:
    """Trading-fee report by brokerage, converted to the base currency for a
    cross-broker comparison. Reads the parsed per-broker JSONs in the cache
    (the only place the brokerage tag survives), year-scoped to the tax year."""
    _wrote(reports_dir / "fees.rpt", reports_dir.parent, "fees report")
    # capture_diag=True: taxjson-fees-sum emits FX default-rate fallback and
    # skipped-file warnings on stderr; persist them to the .diag so a silently
    # wrong rate can't slip through (the report body carries them too).
    _tm = cache.parent / "ticker.map"
    run_to_file(_cmd("taxjson-fees") + [
        "--cache", str(cache),
        "--year", str(settings["year"]),
        "--to", settings["base_currency"], "--rates", str(rates),
    ] + (["--ticker-map", str(_tm)] if _tm.exists() else []),
        reports_dir / "fees.rpt")


# ---------------------------------------------------------------- entry points

def _missing_history_path(root: Path) -> Path:
    """The project's missing-history file: missing_history.json, or the
    legacy phantoms.json when only that exists (it is read, with one
    rename NOTE per run). The path may not exist — callers test
    .exists(). Dies (exit 2) when both names exist."""
    from taxjson.lib.missing_history import (MissingHistoryFileConflict,
                                              missing_history_path)
    try:
        return missing_history_path(root)
    except MissingHistoryFileConflict as e:
        _die_input(str(e))
        raise                                   # (unreachable)


def _refuse_unknown_missing_history_accounts(mh_file: Path,
                                             accounts: Dict[str, Any]
                                             ) -> None:
    """missing_history.json is keyed by account LABEL. An entry whose account is
    not in [accounts] (the account was renamed or removed) used to be
    skipped silently — its opening vanished and the filed gain changed
    (audit S021-05: a pure relabel moved a book by tens of thousands).
    Refuse the run and name each stale label with a suggestion."""
    import difflib
    from taxjson.lib.missing_history import load_missing_history
    try:
        pairs = load_missing_history(mh_file)
    except (OSError, ValueError) as e:
        _die(f"{mh_file.name}: {e}")
    stale: Dict[str, List[str]] = {}
    for sym, acct in sorted(pairs):
        if acct not in accounts:
            stale.setdefault(acct, []).append(sym)
    if not stale:
        return
    known = sorted(accounts)
    lines = []
    for acct, syms in sorted(stale.items()):
        near = difflib.get_close_matches(acct, known, n=1, cutoff=0.0)
        hint = f" — did you rename it to {near[0]!r}?" if near else ""
        more = f" (+{len(syms) - 5} more)" if len(syms) > 5 else ""
        lines.append(f"  {acct!r}: {len(syms)} entr"
                     f"{'y' if len(syms) == 1 else 'ies'} "
                     f"({', '.join(syms[:5])}{more}){hint}")
    _die(f"{mh_file.name} names account(s) that are not in taxjson.toml "
         f"[accounts] ({', '.join(known) or 'none'})",
         *[f"- {ln.strip()}" for ln in lines],
         "Those openings would be skipped and the gains would change "
         "silently. Edit the \"account\" of each entry to the current "
         "account name (or delete the entries if the account is gone), "
         "then run again.")


def _warn_year_without_activity(year: Any, bases: List[Path]) -> None:
    """Warn when no row of this run's books is dated in [settings]
    year. A typo'd in-range year (2015 for 2025) built all-zero filing
    totals with exit 0 and no word (R1-256)."""
    import json as _json
    if not year or not bases:
        return
    ys = str(year)
    lo = hi = None
    for b in bases:
        try:
            txs = _json.loads(Path(b).read_text(encoding="utf-8")).get(
                "transactions", [])
        except (OSError, ValueError, AttributeError):
            return                   # unreadable: other checks say so
        for t in txs:
            for d in (str(t.get("date") or "")[:10],
                      str(t.get("date_settle") or "")[:10]):
                if d.startswith(ys):
                    return
                if len(d) == 10:
                    lo = d if lo is None or d < lo else lo
                    hi = d if hi is None or d > hi else hi
    if lo is None:
        return                       # empty books: said elsewhere
    _say("warning", f"no transaction in any account's books is dated {ys} "
         f"(the books run {lo} to {hi})",
         f"Every {ys} filing total will be 0. Is [settings] year in "
         f"taxjson.toml right?", prog=_PROG)


_RUN_LOCK_FH = None


def _acquire_run_lock(cache: Path) -> None:
    """Hold an exclusive lock on work/.run.lock for the life of this
    process (released by the OS when it exits, however it exits). A
    second `taxjson run` in the same project refuses in one line.
    Where advisory locks are unavailable (no fcntl) runs are not
    serialized, as before."""
    global _RUN_LOCK_FH
    if _RUN_LOCK_FH is not None:
        return                          # `taxjson run run` chains
    try:
        import fcntl
    except ImportError:                 # pragma: no cover — Windows
        return
    try:
        fh = open(cache / ".run.lock", "a+", encoding="utf-8")
    except OSError:
        return
    try:
        fcntl.flock(fh.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
    except OSError:
        fh.close()
        _die("another `taxjson run` is in progress in this project",
             "Wait for it to finish (or stop it), then re-run. Nothing "
             "was run.")
    _RUN_LOCK_FH = fh


def cmd_run(args: argparse.Namespace) -> None:
    # Full rebuild is the DEFAULT: stale cached artifacts must never
    # feed a filing decision. `--fast` opts back into the mtime cache.
    args.force = not getattr(args, "fast", False)
    _DETECTION_SHOWN.clear()            # each run lists its inputs once
    _PARSED_THIS_RUN.clear()
    _SHOWN_THIS_RUN.clear()
    _LOSS_CONTEXT_GAINS.clear()
    _XLIST_THIS_RUN.clear()
    _DATED_THIS_RUN.clear()
    _DATED_SETTLED.clear()
    _IN_KIND_THIS_RUN.clear()
    _SHORT_SOURCES.clear()
    root = Path(args.dir).resolve()
    cfg = load_config(root)
    # Register the config path globally so every `needs_rebuild` call
    # picks it up as an implicit dependency. Touching taxjson.toml
    # (e.g. bumping `year` for a new tax season, switching country,
    # adding a source_currency) now invalidates cached outputs.
    global _CONFIG_PATH
    _CONFIG_PATH = root / "taxjson.toml"
    settings = cfg.get("settings", {})
    accounts = cfg.get("accounts", {})
    if _country(settings) == "usa":
        _say("note", *_US_EXPERIMENTAL_NOTE)
    _since_warn = _grant_since_warning(settings, root, accounts)
    if _since_warn:
        # (a crypto-only project writes no options — nothing to warn about)
        _say("warning", *_split_msg(_since_warn), prog=_PROG)

    # Orphaned artifacts from RENAMED/REMOVED accounts: work/ files
    # keep matching the discovery globs (resolve_gains_files, fees
    # --cache, the audit's --source scan), so a renamed account was
    # counted TWICE in every aggregate (2026-09 audit). Loud, with the
    # exact fix — not auto-deleted (the user may want the history).
    from taxjson.lib.checklist import orphan_work_accounts
    _orphans = orphan_work_accounts(root, accounts)
    if _orphans:
        _say("warning", f"work/ carries artifacts for account(s) not in "
             f"taxjson.toml: {', '.join(_orphans)}",
             "These are STILL COUNTED by sum/fees/wash tools (a renamed "
             "account is counted twice). Delete work/<name>_* and "
             "reports/<name>* for each, or restore the account in the "
             "config.", prog=_PROG)
        if getattr(args, "strict", False):
            # Every aggregate would count them twice (A2-1165).
            _die("--strict: work/ carries artifacts for account(s) not in "
                 f"taxjson.toml: {', '.join(_orphans)} — aborting")
    if not accounts:
        _die("no [accounts.*] sections in taxjson.toml")
    # Warnings FIRST: a typo'd `yeer = 2025` must show its did-you-mean
    # before the "missing year" death it causes.
    for msg in validate_config(cfg, root / "inputs"):
        _say("warning", *_split_msg(f"taxjson.toml: {msg}"), prog=_PROG)
    _fnote = _fetch_plugin_note(cfg)
    if _fnote:
        _say("note", *_split_msg(f"taxjson.toml: {_fnote}"), prog=_PROG)
    for required in ("year", "country"):
        if required not in settings:
            _die(f"missing [settings] {required} in taxjson.toml")
    if not settings.get("base_currency"):
        # Unset means the country's currency, as every other command
        # reads it (INPUTS-07; re-audit A2-0712: only `run` refused it).
        settings["base_currency"] = _base(settings)

    inputs_dir = root / "inputs"
    cache = root / "work"
    reports_dir = root / "reports"
    # work/ or reports/ that is a FILE, or a project directory that
    # cannot be written, tracebacked — reports/ only after every stage
    # had rewritten work/, leaving the two out of step (S038-17).
    for _d in (cache, reports_dir):
        try:
            _d.mkdir(parents=True, exist_ok=True, mode=0o700)
        except OSError as e:
            _die(f"cannot use {_d.name}/: "
                 + ("it exists and is not a directory"
                    if isinstance(e, FileExistsError) or _d.is_file()
                    else (e.strerror or str(e))),
                 "Nothing was run.")
        import os as _os_mod
        if not _os_mod.access(_d, _os_mod.W_OK | _os_mod.X_OK):
            _die(f"cannot write to {_d.name}/", "Nothing was run.")
    # One run per project at a time: the stages write fixed work/ names,
    # so a cron `watch` racing an interactive run crashed one of them
    # with a FileNotFoundError on a shared .part file (A2-0778).
    _acquire_run_lock(cache)
    # --fast trusts cached stages only when they were built by THIS code
    # (content, not mtimes — S039-03). The stamp is removed now and
    # rewritten when the run completes, so a run that stops half-way
    # never vouches for stages it did not rebuild.
    _code_stamp = cache / _CODE_STAMP
    _code_fp = _package_fingerprint()
    if not args.force:
        _old_fp = (_read_work_stamp(_code_stamp) or "").strip()
        if _old_fp != _code_fp:
            _step("Rebuilding everything: taxjson's code changed since the "
                  "cached stages were built (or no complete run recorded "
                  "it); --fast applies from the next run")
            args.force = True
    _drop_work_file(_code_stamp)
    # A project map that exists as a NAME but cannot be opened (a
    # dangling or looping symlink) read as "absent": the run exited 0
    # with other gains (audit A2-0313). Absent and unreadable differ.
    _refuse_unreadable_project_inputs(root)
    # A leftover tv_exchange.map (the removed TradingView export) stops
    # nothing — nothing reads it — but is named once per run.
    from taxjson.lib.migrate import retired_file_note, retired_files
    _retired = retired_files(root)
    if _retired:
        _say("note", *_split_msg(retired_file_note(_retired)),
             prog=_PROG)
    # ticker.map — one keyword-prefixed symbol-rule file. GLOBAL renames
    # apply everywhere; TOBASE consolidations apply only in the main
    # (to-base) merge; JOURNAL pairs also net in the holdings export;
    # DELETE nukes a ticker. Each merge/export stage requests its subset.
    ticker_map = root / "ticker.map"
    ticker_map_arg = ticker_map if ticker_map.exists() else None
    if ticker_map_arg:
        # A line the loader cannot parse DROPS its rule, and a dropped
        # TOBASE/GLOBAL/JOURNAL rule moves ACB pools and the Schedule 3
        # gain; its warning used to reach only reports/*.sum while the
        # run (even --strict) exited 0 (S009-03). Refuse up front.
        from taxjson.bin.taxjson_ticker_map import map_file_problems
        try:
            _tm_problems = map_file_problems(ticker_map)
        except OSError as e:        # not UTF-8 (S053-06)
            # An input that cannot be read: exit 2, one line naming it
            # (A2-0163, A2-1438 — the EXTRACT lines live here now).
            from taxjson.lib.cli_diag import describe_input_error
            _die_input(describe_input_error(e))
        if _tm_problems:
            _die(f"{len(_tm_problems)} ticker.map problem(s)",
                 *[f"- {p}" for p in _tm_problems],
                 "A malformed line's rule would be silently dropped, and "
                 "contradictory rules (a cycle, two targets for one "
                 "symbol, a DISTINCT pair the renames pool) have no "
                 "single meaning; either changes ACB pools and gains. Fix "
                 "the line (KEYWORD FROM TO, separated by spaces; notes "
                 "after `#`) or delete it.")
    # Dated events: the .tt JOURNAL / RENAME lines of every account
    # (lib/dated_events), checked up front; ticker.map's legacy JOURNAL
    # and dated RENAME lines still work, said once.
    _tmap_parsed = None
    if ticker_map_arg:
        from taxjson.bin.taxjson_ticker_map import _parse_map_file
        try:
            _tmap_parsed = _parse_map_file(ticker_map)[0]
        except (OSError, ValueError):
            _tmap_parsed = None
        from taxjson.lib.dated_events import legacy_note
        _legacy = legacy_note(_tmap_parsed)
        if _legacy:
            _say("warning", _legacy[0], *_legacy[1], prog=_PROG)
    _read_dated_events(root, accounts, _tmap_parsed)
    # ticker.map EXTRACT lines — description-keyed ticker corrections
    # for securities the currency->exchange suffix mislabels. The parse
    # stage gets the map as taxjson-brokerage --security-overrides when
    # it has any (a malformed one was refused above with the rest of
    # the map's problems).
    sec_overrides_arg = None
    if ticker_map_arg:
        from taxjson.lib.ticker_map import read_side_rules
        _side = read_side_rules(ticker_map)
        if _side.extract:
            sec_overrides_arg = ticker_map
        if _side.retired:
            # TRADINGVIEW lines: the export they fed was removed. Ignored
            # (never an error — an older project may still carry them);
            # said once per run.
            _say("note", f"{ticker_map.name} has {len(_side.retired)} "
                 f"TRADINGVIEW line(s) ({', '.join(_side.retired)})",
                 "TradingView export removed; delete these lines (they "
                 "are ignored).", prog=_PROG)
    # missing_history.json — optional project-wide list of (symbol,
    # account) pairs sold with no purchase in the files (bought before
    # the data; from `find-missing-history --write-missing-history`). Its
    # old name phantoms.json is still read, with a rename NOTE.
    # Auto-detected at the root like ticker.map; when present it feeds
    # every account's gains run via --incomplete-history.
    mh_file = _missing_history_path(root)
    mh_arg = mh_file if mh_file.exists() else None
    if mh_arg:
        _refuse_unknown_missing_history_accounts(mh_arg, accounts)
    # Deletion detection: needs_rebuild compares mtimes of EXISTING inputs,
    # so removing the file left cached gains — built WITH its openings —
    # looking fresh forever. Track application with a marker; on removal,
    # bump the base files' mtimes so every gains stage rebuilds clean.
    # (.phantoms_applied: the marker's old name, in older work/ dirs.)
    _ph_marker = cache / ".missing_history_applied"
    _ph_marker_old = cache / ".phantoms_applied"
    if mh_arg:
        _step(f"Reading {mh_file.name} (openings for sales with no "
              f"purchase in the files)")
        cache.mkdir(parents=True, exist_ok=True, mode=0o700)
        _ph_marker.write_text(str(mh_file))
        _ph_marker_old.unlink(missing_ok=True)
    elif _ph_marker.exists() or _ph_marker_old.exists():
        _step("missing_history.json removed: rebuilding the gains built "
              "with it")
        _ph_marker.unlink(missing_ok=True)
        _ph_marker_old.unlink(missing_ok=True)
        import os as _os
        # (*_raw.json too: the native raw-gains pass applies the
        # missing-history openings since A2-0111 and depends on
        # that file.)
        for _f in [*cache.glob("*_base.json"), *cache.glob("*_raw.json")]:
            _os.utime(_f)
        # [[distributions]] ADJUSTs in the taxable base books were
        # sized WITH the missing-history openings (S000-08): drop those books
        # so the merge stage rebuilds them, not just the gains.
        if cfg.get("distributions"):
            for _n, _c in accounts.items():
                if isinstance(_c, dict) and _c.get("type") == "taxable":
                    (cache / f"{_n}_base.json").unlink(missing_ok=True)

    # Same deletion-blindness class for the project-root map file:
    # needs_rebuild only sees deps that EXIST, so deleting ticker.map
    # left its renames and ticker fixes in the cached books under --fast
    # forever. Track whether it is applied; on removal, bump every
    # account's sources manifest (a parse-stage dep) so the rebuild
    # cascades through merge and gains. ([[distributions]] lives in
    # taxjson.toml, which the input fingerprint covers.)
    _maps_marker = cache / ".project_maps_applied"
    _maps_now = sorted(p.name for p in (ticker_map,) if p.exists())
    _maps_before = (_read_work_stamp(_maps_marker) or "").split()
    _maps_removed = sorted(set(_maps_before) - set(_maps_now))
    if _maps_removed:
        _step(f"{', '.join(_maps_removed)} removed: rebuilding the books "
              f"built with it")
        import os as _os
        for _f in cache.glob("*_sources.list"):
            if not _f.name.startswith("."):
                _os.utime(_f)
    if _maps_now:
        cache.mkdir(parents=True, exist_ok=True, mode=0o700)
        if _maps_now != _maps_before:
            _write_work_stamp(_maps_marker, "\n".join(_maps_now) + "\n")
    else:
        _drop_work_file(_maps_marker)

    _dup_inputs = _duplicate_input_files(inputs_dir, accounts)
    for _paths in _dup_inputs:
        _say("attention", f"the same export file sits in two accounts: "
             f"{', '.join(_paths)} (identical content)",
             "Every row of it is booked twice, once in each account. Keep "
             "each broker export under ONE inputs/<account>/ folder.",
             indent="  ")
    if _dup_inputs and getattr(args, "strict", False):
        _die("--strict: the same export file is in two accounts "
             "(warning above)", "Its rows would be booked twice — "
             "nothing was built.")

    _step("Loading currency rates")
    rates = stage_currency_rates(settings, cache)

    sheltered_items = [(n, c) for n, c in accounts.items()
                       if c.get("type", "sheltered") == "sheltered"]
    taxable_items = [(n, c) for n, c in accounts.items()
                     if c.get("type") == "taxable"]

    if args.account:
        sheltered_items = [(n, c) for n, c in sheltered_items if n == args.account]
        taxable_items = [(n, c) for n, c in taxable_items if n == args.account]
        if not sheltered_items and not taxable_items:
            _die(f"no [accounts.{args.account}] in taxjson.toml")

    no_input = getattr(args, "no_input", False)
    pending_accounts: List[PendingElectionsError] = []

    # Crypto sends pair a send in one crypto account with its arrival
    # in another: parse EVERY crypto account's exports before any
    # account's sends stage reads the transfer evidence, so the first
    # run after a new export pairs against it (re-audit A2-0077) and a
    # removed export's evidence is gone (A2-1026). The parse is cached,
    # so the account's own stage below does not parse again.
    _crypto_first = [(n, c) for n, c in accounts.items()
                     if (c or {}).get("crypto") and not (c or {}).get(
                         "transfers")]
    if len(_crypto_first) >= 2:
        for name, acfg in _crypto_first:
            stage_account(name, acfg, settings, inputs_dir, cache,
                          reports_dir, rates, ticker_map_arg,
                          sec_overrides_arg, args.force,
                          incomplete_history=mh_arg,
                          no_input=no_input,
                          strict=getattr(args, "strict", False),
                          parse_only=True)
        _dups = _duplicate_crypto_exports(
            cache, [n for n, _c in _crypto_first])
        for _d in _dups:
            _say("warning", *_split_msg(_d), prog=_PROG)
        if _dups and getattr(args, "strict", False):
            _die("--strict: the same exchange rows are in two crypto "
                 "accounts (above)", "Every one would be booked twice. "
                 "Remove the copy.")

    # US: a move between two of your own taxable accounts carries its
    # lots (US-BASIS-05). Every taxable equity account's transfer
    # evidence is parsed first (cached), so the moves are known before
    # any account's books are merged; each account's legs file is then
    # one of its sources.
    # Both countries: a transfer-in that pairs with a transfer-out of
    # another of your taxable accounts is not an arrival from outside
    # the books (lib/transfer_in) — every account's evidence must be
    # current before any account's books are merged.
    # Every equity account, sheltered ones too: two listings joined by
    # a transfer journal (lib/cross_listings) are one security in EVERY
    # account's books, so all transfer evidence is read before any
    # account is merged.
    _equity_first = [(n, c) for n, c in accounts.items()
                     if not (c or {}).get("crypto")]
    if len(_equity_first) < 2:
        _equity_first = []
    # Questrade internal symbol codes are resolved from the OTHER
    # accounts' transfers and names (stage_symbol_codes): those accounts
    # are parsed first, the accounts holding codes last.
    _code_accts = (_accounts_with_symbol_codes(inputs_dir, accounts)
                   if len(accounts) >= 2 else [])
    if _code_accts:
        _equity_first += [(n, c) for n, c in accounts.items()
                          if not (c or {}).get("crypto")
                          and n not in {x for x, _c in _equity_first}]
        _equity_first.sort(key=lambda nc: nc[0] in _code_accts)
    if _equity_first:
        for name, acfg in _equity_first:
            try:
                stage_account(name, acfg, settings, inputs_dir, cache,
                              reports_dir, rates, ticker_map_arg,
                              sec_overrides_arg, args.force,
                              incomplete_history=mh_arg,
                              no_input=no_input,
                              strict=getattr(args, "strict", False),
                              parse_only=True)
            except PendingElectionsError:
                pass
        # A listing read from another account's books (lib/
        # listing_suffix) whose evidence that account parsed only after
        # this one: read the account again, so every account's books
        # are final before any is merged (the order never matters).
        _stale = set(_listing_suffix_stale(root, cache))
        for name, acfg in _equity_first:
            if name not in _stale:
                continue
            try:
                stage_account(name, acfg, settings, inputs_dir, cache,
                              reports_dir, rates, ticker_map_arg,
                              sec_overrides_arg, args.force,
                              incomplete_history=mh_arg,
                              no_input=no_input,
                              strict=getattr(args, "strict", False),
                              parse_only=True)
            except PendingElectionsError:
                pass
    stage_own_account_moves(root, {"accounts": accounts,
                                   "settings": settings},
                            settings, cache,
                            strict=getattr(args, "strict", False))

    sheltered_outputs: List[Tuple[str, Dict[str, Path]]] = []
    _skipped_no_input: List[str] = []       # no CSV/.tt — see B7 helper
    for name, acfg in sheltered_items:
        try:
            out = stage_account(name, acfg, settings, inputs_dir, cache,
                                reports_dir, rates, ticker_map_arg,
                                sec_overrides_arg, args.force,
                                incomplete_history=mh_arg,
                                no_input=no_input,
                                strict=getattr(args, "strict", False))
        except PendingElectionsError as pe:
            _say("warning", f"{name}: corp-action elections required — "
                 f"account deferred", indent="  ")
            pending_accounts.append(pe)
            continue
        if out is None:                     # unpopulated account — skipped
            _skipped_no_input.append(name)
            continue
        sheltered_outputs.append((name, out))

    sheltered_base: Optional[Path] = None
    _sheltered_merge_inputs: List[Path] = []
    if sheltered_outputs and not args.account:
        _sheltered_merge_inputs = [o["base"] for _, o in sheltered_outputs]
    elif sheltered_outputs and args.account:
        # `--account <sheltered>`: the named book is fresh, the other
        # sheltered books are whatever the last run left in work/. Fold
        # them together anyway — leaving sheltered_base.json untouched
        # meant a later `wash-radar --account margin` read a sheltered
        # book that predated this run's buys,
        # exactly the rows a 30-day radar exists to see (2026-09 audit).
        _other_names = [n for n, c in accounts.items()
                        if c.get("type", "sheltered") == "sheltered"
                        and n != args.account]
        _others = [cache / f"{n}_base.json" for n in _other_names]
        # A sibling WITH inputs but no book (deleted, or its last stage
        # failed) would silently drop its registered buys from the
        # combined book — the radar and the what-if then said "safe to
        # sell at a loss" (audit A2-0128). Refuse and keep the old
        # combined book; an account with no inputs never has a book.
        _lost = [f"{n}_base.json" for n in _other_names
                 if not (cache / f"{n}_base.json").exists()
                 and not (cache / f"{n}_pending_elections.json").exists()
                 and (input_files(inputs_dir / n, ".csv")
                      or input_files(inputs_dir / n, ".tt"))]
        if _lost:
            _die(f"--account {args.account}: the sheltered book(s) "
                 f"{', '.join(_lost)} are missing from work/ although "
                 f"their accounts have inputs",
                 "sheltered_base.json was left unchanged (rebuilding it "
                 "without them would hide their purchases from the "
                 "superficial-loss checks). Run `taxjson run` without "
                 "--account to rebuild every book.")
        _missing = [p.name for p in _others if not p.exists()]
        _sheltered_merge_inputs = (
            [o["base"] for _, o in sheltered_outputs]
            + [p for p in _others if p.exists()])
        _step("Combining sheltered accounts")
        _say("note", f"from this run's {args.account} book plus the other "
             f"sheltered accounts' last-built books"
             + (f" (no book for {', '.join(_missing)}: no inputs, or "
                f"deferred on elections)" if _missing else ""),
             indent="  ", file=sys.stdout)
    _pending_sheltered = {pe.account for pe in pending_accounts}
    if (not _sheltered_merge_inputs and not args.account
            and not _pending_sheltered):
        # No sheltered account produced books in this FULL run (the last
        # one was removed, or its inputs emptied): the previous run's
        # combined book must go, or the filed-year lock, check-filed and
        # the radar keep reading registered holdings that no longer
        # exist — a false OK on a moved filed number (S004-05).
        for _ghost in (cache / "sheltered_base.json",
                       cache / "sheltered_base.json.diag"):
            if _ghost.exists():
                _ghost.unlink()
                _say("note", f"removed stale work/{_ghost.name} (no "
                     f"sheltered account has books)", indent="  ",
                     file=sys.stdout)
    if _sheltered_merge_inputs:
        if not args.account:
            _step("Combining sheltered accounts")
        sheltered_base = cache / "sheltered_base.json"
        run_to_file(_cmd("taxjson-merge")
                    + [str(p) for p in _sheltered_merge_inputs],
                    sheltered_base)
    if sheltered_base is not None:
        # Sanity-check the combined sheltered file before the wash-radar
        # pass consumes it. Quiet on success; surface and halt on failure.
        from taxjson.lib.dispatch import run_cmd as _run_cmd
        vres = _run_cmd(_cmd("taxjson-validate") + [str(sheltered_base)],
                        capture_output=True)
        if vres.returncode != 0:
            _echo_stage_stderr((vres.stdout or "") + (vres.stderr or ""))
            # A clean exit, not a raw CalledProcessError traceback —
            # the validator's output above already names the offending
            # transaction(s); tell the user where to look next.
            _die("the combined sheltered book failed validation (details "
                 "above) — the wash pass cannot trust it",
                 "The usual cause is a malformed row from a corp-action "
                 "election; check the named account's DIAGNOSTICS in its "
                 ".sum, fix the election (`taxjson elect <account> "
                 "--redo`) or the input row, and re-run.")

    taxable_outputs: List[Tuple[str, Dict[str, Path], bool]] = []
    _blend_names: List[str] = []
    # Canada: crypto accounts blend with each other when the project
    # CONFIGURES two or more (decided on the config, not on this run's
    # --account subset, so a single-account rerun never rewrites a
    # blended wash file with a one-exchange one).
    _crypto_blend_names: List[str] = []
    _crypto_blend = (
        _country(settings)
        not in ("us", "usa")
        and sum(1 for _c in accounts.values()
                if _c.get("type") == "taxable" and _c.get("crypto")) >= 2)
    # USA: taxable crypto accounts with a move of coins between them
    # (stage_own_account_moves wrote their legs) run one blended crypto
    # pass — FIFO stays per account and no wash-sale rule applies, but
    # the move carries its lots (US-CRYPTO-05). Without a move they stay
    # per account.
    _us_crypto_blend = (
        _country(settings) in ("us", "usa")
        and any(_c.get("type") == "taxable" and _c.get("crypto")
                and not _c.get("transfers")
                and (cache / f"{_n}{OWN_MOVES_SUFFIX}").is_file()
                for _n, _c in accounts.items()))
    if not args.account:
        # A per-account blend mirror is rewritten only for accounts IN
        # this run's blend: one that left it (re-typed, the other
        # crypto account removed) kept its old mirror, and its fixed
        # problem was re-reported in every later banner (S038-08).
        for _n, _c in accounts.items():
            _c = _c or {}
            _taxable = _c.get("type") == "taxable"
            for _tag, _in_blend in (
                    ("blend", _taxable and not _c.get("crypto")),
                    ("cryptoblend", _taxable and bool(_c.get("crypto"))
                     and (_crypto_blend or (_us_crypto_blend
                                            and not _c.get("transfers"))))):
                _m = cache / f"{_n}_{_tag}.diag"
                if not _in_blend and _m.exists():
                    _m.unlink()
    for name, acfg in taxable_items:
        try:
            out = stage_account(name, acfg, settings, inputs_dir, cache,
                                reports_dir, rates, ticker_map_arg,
                                sec_overrides_arg, args.force,
                                incomplete_history=mh_arg,
                                no_input=no_input,
                                strict=getattr(args, "strict", False))
        except PendingElectionsError as pe:
            _say("warning", f"{name}: corp-action elections required — "
                 f"account deferred", indent="  ")
            pending_accounts.append(pe)
            continue
        if out is None:                     # unpopulated account — skipped
            _skipped_no_input.append(name)
            continue
        is_crypto = acfg.get("crypto", False)
        taxable_outputs.append((name, out, is_crypto))
        # Wash second pass: crypto is skipped only for US projects
        # (§1091 does not reach digital assets — matching _wash_flags).
        # Canada's superficial-loss rule covers ANY identical property,
        # crypto included: the engine already wash-checks Canadian
        # crypto in the main pass, so the advisory tooling must not go
        # silent on exactly the account type where 30-day rebuys are
        # most common.
        _crypto_wash_covered = _country(settings) not in ("us", "usa")
        if not is_crypto:
            # Equity taxable accounts are handled by ONE blended pass
            # after this loop (Canada ACB blending / US cross-account
            # §1091 — the multi-account fix). Collected here.
            _blend_names.append(name)
        elif _crypto_wash_covered and _crypto_blend:
            # Two or more Canadian crypto accounts: ONE blended crypto
            # pass after this loop (s.47 averaging and superficial loss
            # across exchanges — each exchange's book alone missed both).
            _crypto_blend_names.append(name)
        elif _crypto_wash_covered and sheltered_base is not None:
            stage_wash_pass(name, settings, cache, reports_dir, sheltered_base,
                            incomplete_history=mh_arg)
        elif _us_crypto_blend and not acfg.get("transfers"):
            # USA, two or more crypto accounts: ONE blended crypto pass
            # (no wash-sale rule) so own moves carry their lots.
            _crypto_blend_names.append(name)
        elif not args.account and not pending_accounts:
            # A FULL run decided this crypto account gets no wash pass
            # (US policy excludes it, or the sheltered context vanished
            # by data). A stale _gains_wash.json would otherwise keep
            # winning resolve_gains_files forever. (Kept under
            # --account and pending-election deferrals — transient.)
            for _stale in (cache / f"{name}_gains_wash.json",
                           cache / f"{name}_gains_wash.traces",
                           cache / f"{name}_gains_wash.json.diag",
                           reports_dir / f"{name}_wash.sum"):
                _stale.unlink(missing_ok=True)

    # An in-kind contribution's plan acquisition is a purchase for the
    # loss rule (CA-INKIND-04): marked in the combined book (or the book
    # written for it) once every taxable account's transfer evidence is
    # read, before the cross-account passes use it.
    if not args.account or _sheltered_merge_inputs:
        sheltered_base = stage_in_kind_context(root, cache, settings,
                                               sheltered_base)
    _record_skipped_accounts(cache, _skipped_no_input,
                             only=args.account or None)
    if (not args.account and not pending_accounts
            and not sheltered_outputs and not taxable_outputs):
        # Every account was skipped for having no inputs: "Done" with
        # exit 0 read as success on an empty project (2026-09 CLI audit).
        _say("warning", "no account had any input — nothing was computed",
             "Drop broker CSV exports (or .tt files) into "
             "inputs/<account>/ and re-run.", prog=f"{_PROG} run")
        if getattr(args, "strict", False):
            raise SystemExit(1)
        return
    _report_short_positions(root, settings, cache, ticker_map_arg, mh_arg)
    _rename_records = _write_dated_events_state(root, cfg, cache,
                                                _tmap_parsed)
    if not pending_accounts:
        _warn_unused_renames(_rename_records,
                             strict=getattr(args, "strict", False))
        _check_renamed_late(root, strict=getattr(args, "strict", False))
    if _blend_names and not args.account and not pending_accounts:
        stage_blended_wash_pass(_blend_names, settings, cache,
                                reports_dir, sheltered_base,
                                incomplete_history=mh_arg,
                                strict=getattr(args, "strict", False))
    if _crypto_blend_names and not args.account and not pending_accounts:
        stage_blended_wash_pass(_crypto_blend_names, settings, cache,
                                reports_dir, sheltered_base,
                                incomplete_history=mh_arg,
                                tag="cryptoblend",
                                no_wash=not _crypto_blend,
                                spot_crypto=not _crypto_blend,
                                strict=getattr(args, "strict", False))
    _say_transfer_windows(settings)
    _say_in_kind(root, cache, settings,
                 strict=getattr(args, "strict", False))
    if not args.account and not pending_accounts:
        # A ticker.map line naming a bare ticker whose US listing the
        # books hold (v0.24.1 leftovers, 1), said before the radar.
        _say_listing_spellings(root)
        # Every account's gains are final: a loss on one listing, the
        # other listing bought in the window (QA F3).
        _say_xlist_losses(root, cfg, cache,
                          strict=getattr(args, "strict", False))
    if not args.account and not pending_accounts:
        # A sheltered account never gets a wash pass. One re-typed from
        # taxable kept its old <name>_gains_wash.json / _wash.sum, which
        # resolve_gains_files prefers forever — the "run a full `taxjson
        # run`" remedy never cleared them (S038-19).
        for _n, _c in accounts.items():
            if (_c or {}).get("type") != "sheltered":
                continue
            for _stale in (cache / f"{_n}_gains_wash.json",
                           cache / f"{_n}_gains_wash.traces",
                           cache / f"{_n}_gains_wash.json.diag",
                           reports_dir / f"{_n}_wash.sum"):
                if _stale.exists():
                    _stale.unlink()
                    _say("note", f"removed stale {_stale.name} ({_n} is "
                         f"sheltered: no wash pass)", indent="  ",
                         file=sys.stdout)

    if pending_accounts:
        # Some account(s) stopped at unresolved corp-action elections.
        # Aggregate the per-account pending JSONs into ONE document a
        # GUI (or the user) can act on, explain the resolution path,
        # and exit 3 — the cross-account passes below would be built
        # from incomplete books.
        import json as _json
        agg: Dict[str, Any] = {"schema_version": 1, "accounts": {}}
        agg_path = cache / "pending_elections.json"
        # Under --account only a SUBSET was re-examined: other accounts'
        # pending entries in the existing aggregate are still live —
        # overwriting (or, below, unlinking) the file lost their
        # ready-to-copy --set lines (REVIEW #33).
        if args.account and agg_path.exists():
            try:
                prior = _load_pending_agg(agg_path)
                agg["accounts"].update(
                    {a: d for a, d in (prior.get("accounts")
                                       or {}).items()
                     if a != args.account})
            except ValueError:
                pass                    # damaged: rebuilt below
        for pe in pending_accounts:
            try:
                agg["accounts"][pe.account] = _json.loads(
                    pe.pending_path.read_text(encoding="utf-8"))
            except (OSError, ValueError):
                agg["accounts"][pe.account] = {"pending": []}
        # tmp + replace: a reader never sees half a file (A2-0779)
        write_text_atomic(agg_path,
                          _json.dumps(agg, indent=2, sort_keys=True))
        from taxjson.lib import out as _out
        _n = len(pending_accounts)
        _sets = []
        for pe in pending_accounts:
            doc = agg["accounts"].get(pe.account) or {}
            for ev in doc.get("pending", []):
                opts = "|".join(o["election"] for o in ev.get("options",
                                                             []))
                _sets.append(f"  taxjson elect {pe.account} --set "
                             f"{ev['event_id']}=<{opts}>")
        _shown = _out.width(sys.stderr) > 0
        if not _shown:
            print(file=sys.stderr)
        _lines = _out.message(
            "error", f"{_n} account{'s' if _n != 1 else ''} "
            f"need{'' if _n != 1 else 's'} corp-action elections "
            f"before {'their' if _n != 1 else 'its'} books can build",
            prog=f"{_PROG} run")
        # The ready lines are commands to copy: never wrapped (shown to
        # a person, flush-left like every continuation).
        _lines += [ln.strip() if _shown else ln for ln in _sets]
        _lines += _out.wrap(
            "`taxjson elect --pending` shows what each option books "
            "and the hints it needs (also in "
            f"{_out.relpath(agg_path, root)}). Set each with `taxjson "
            "elect ACCOUNT --set` (add --hint KEY=VALUE where "
            "required), or run `taxjson run` at a terminal to be "
            "asked; then run again.", indent="" if _shown else "  ",
            stream=sys.stderr)
        _out.show(_lines, sys.stderr)
        raise SystemExit(3)
    _agg_path = cache / "pending_elections.json"
    if args.account and _agg_path.exists():
        # This run only proved args.account resolved — drop just its
        # entry; other accounts' pending elections are untouched
        # (REVIEW #33: the unconditional unlink made `elect --pending`
        # claim everything was resolved).
        import json as _json
        try:
            _doc = _load_pending_agg(_agg_path)
        except ValueError:
            # A damaged or wrong-shape aggregate is a rebuildable work
            # file: dropped, never a traceback after a good run
            # (re-audit A2-1439, A2-1457, A2-1419).
            _doc = None
            _agg_path.unlink(missing_ok=True)
        if _doc is not None:
            _accts = dict(_doc.get("accounts") or {})
            _accts.pop(args.account, None)
            _accts = {a: d for a, d in _accts.items() if d.get("pending")}
            if _accts:
                _doc["accounts"] = _accts
                write_text_atomic(
                    _agg_path, _json.dumps(_doc, indent=2, sort_keys=True))
            else:
                _agg_path.unlink()
    else:
        _agg_path.unlink(missing_ok=True)

    if not args.account:
        _sweep_retired_exports(reports_dir)

        all_gains = ([o["gains"] for _, o in sheltered_outputs] +
                     [_wash_preferred_gains(o["gains"])
                      for _, o, _ in taxable_outputs])
        # Radar/lint bases: equity always; crypto too when the
        # jurisdiction's wash rule covers it (Canada s.54 identical
        # property — same condition as the second pass above).
        _crypto_wash_covered = _country(settings) not in ("us", "usa")
        taxable_equity_base = [
            o["base"] for _, o, is_crypto in taxable_outputs
            if not is_crypto or _crypto_wash_covered]
        stage_cross_reports(all_gains, taxable_equity_base, sheltered_base, reports_dir,
                            ticker_map_arg, missing_history=mh_arg,
                            country=_country(settings))
        # Overlap notes per blended group — the note says the blended
        # pass covers the symbol, so it must only name accounts a blend
        # actually spans (crypto blends only in Canada; equity and
        # crypto never blend with each other).
        _warn_cross_taxable_overlap(
            [(n, o["base"]) for n, o, c in taxable_outputs if not c],
            settings)
        _shared_brokers = _warn_shared_broker_accounts(
            [(n, o["base"]) for n, o in sheltered_outputs]
            + [(n, o["base"]) for n, o, _c in taxable_outputs])
        if _shared_brokers and getattr(args, "strict", False):
            # Every row of that broker account is booked twice (A2-0366).
            _die("--strict: one broker account feeds two taxjson "
                 "accounts (warning above) — aborting.")
        if _crypto_blend:
            _warn_cross_taxable_overlap(
                [(n, o["base"]) for n, o, c in taxable_outputs if c],
                settings)
    stage_fees(cache, settings, rates, reports_dir)
    _warn_year_without_activity(
        settings.get("year"),
        [o["base"] for _, o in sheltered_outputs]
        + [o["base"] for _, o, _c in taxable_outputs])

    # Filed-year lock: recompute every closed year from the fresh books
    # and shout if a filed number moved (warn-only; --strict aborts).
    try:
        from taxjson.bin import taxjson_filed as _tf
        _snaps = _tf.list_snapshots(root)
        if _snaps and args.account:
            # A single-account run skipped the cross-account wash pass,
            # so the books the recompute would read are NOT the books
            # a full run produces: printing "OK" here right after
            # declaring the wash pass skipped was a false all-clear
            # that the next full run contradicted with DRIFTED
            # (2026-09 audit). Say so instead of checking.
            _step("Checking the filed years")
            for _year, _ in _snaps:
                _say("note", f"filed {_year}: not checked (a single-account "
                     f"run skips the wash pass; run without --account)",
                     indent="  ", file=sys.stdout)
        elif _snaps:
            _step("Checking the filed years")
            _check_filed_years(root, cache, settings,
                               strict=getattr(args, "strict", False),
                               console=True)
    except SystemExit:
        raise
    except Exception as _e:              # advisory guard, never a crash
        _say("warning", f"filed-year check failed: {_e}", prog=_PROG)

    if not args.account:
        # What these reports were built from (content hashes), so the
        # checklist's run-clean step sees a deleted input or a
        # corrected export copied with an old mtime (S067-07).
        try:
            from taxjson.lib.checklist import record_input_fingerprint
            record_input_fingerprint(root, cfg)
        except Exception as _e:          # advisory, never a crash
            _say("warning", f"could not record the input fingerprint: "
                 f"{_e}", prog=_PROG)

    try:
        _fx_cash_after_run(root, cache, reports_dir)
    except Exception as _e:              # advisory guard, never a crash
        _say("warning", f"fx-cash report failed: {_e}", prog=_PROG)

    # Filing-obligation reminder: a rollover elected in March is
    # forgotten by filing season, and the deferral is INVALID without
    # the paperwork. The option text said so at choose time; say it
    # again where it matters — at the end of every run.
    try:
        from taxjson.lib.corp_actions import (FILING_REQUIRED_ELECTIONS,
                                              Manifest)
        _year = str(settings.get("year", ""))
        _obligations = []
        for _name, _acfg in cfg.get("accounts", {}).items():
            if _acfg.get("type", "sheltered") != "taxable":
                continue          # no gain to defer inside a registered
                                  # plan, so there is nothing to file —
                                  # the election only kept the books
                                  # consistent
            _mp = _manifest_path_for(inputs_dir / _name, cache, _name)
            if not _mp.exists() and not _mp.is_symlink():
                continue
            try:
                _recs = list(Manifest.load(_mp).records.values())
            except (OSError, ValueError, AttributeError) as _e:
                # One unreadable manifest used to discard every
                # account's reminder in silence (S038-23): name it and
                # keep going.
                _say("warning", f"could not read {_out_relpath(_mp, root)} "
                     f"({_e})",
                     "Its elections are not checked for a FILING REQUIRED "
                     f"reminder; fix the file (`taxjson elect {_name}` "
                     "reads it too).", prog=_PROG)
                continue
            for _rec in _recs:
                _todo = FILING_REQUIRED_ELECTIONS.get(_rec.election)
                if not _todo:
                    continue
                _sum = _rec.summary or ""
                if _year and _sum[:4].isdigit() and _sum[:4] != _year:
                    continue          # election from another tax year
                _obligations.append((f"{_name}: {_sum or _rec.event_id}",
                                     _todo))
        if _obligations:
            _head = (f"FILING REQUIRED for {len(_obligations)} "
                     f"election(s) — the deferral is only valid with the "
                     f"paperwork")
            from taxjson.lib.out import width as _ow
            if _ow(sys.stderr) > 0:
                # Shown to a person: one message, its lines flush-left.
                _say("warning", _head, *[x for _pair in _obligations
                                         for x in _pair], prog=_PROG)
            else:
                _say("warning", _head, prog=_PROG)
                for _what, _todo in _obligations:
                    for _ln in _out_wrap(_what, indent="  - ",
                                         hang="    ", file=sys.stderr):
                        print(_ln, file=sys.stderr)
                    for _ln in _out_wrap(_todo, indent="    ",
                                         file=sys.stderr):
                        print(_ln, file=sys.stderr)
    except Exception:
        pass                          # reminder must never break a run

    if not args.account:
        _code_stamp.write_text(_code_fp + "\n", encoding="utf-8")
    _step(f"Done. Reports are in {_out_relpath(reports_dir, root)}/")

    # Broker-positions cross-check, when taxjson.toml declares any
    # account's `holdings` files. A WARNING, never a failing exit:
    # same-day trades that haven't reached the CSVs yet differ
    # routinely, and a hard failure there would teach the user to
    # ignore it. Only a self-vs-external compare catches a stranded
    # position that every internal report agrees on (shares stranded
    # by a split, an option class split).
    if not args.account and any((_a or {}).get("holdings")
                                for _a in cfg.get("accounts", {}).values()):
        from taxjson.lib.out import width as _ow
        if _ow(sys.stdout) <= 0:
            print()
        _step("Checking positions against the broker's holdings files")
        _san_notes = _sanity_items_from_config(cfg.get("accounts", {}),
                                               root)[1]
        for _n in _san_notes:
            # One unreadable holdings file drops that account from the
            # compare while sanity itself still exits 0 — say so here,
            # or the run reads as fully checked (2026-09 audit R1-324).
            _say("warning", *_split_msg(f"holdings check incomplete: {_n}"),
                 indent="  ")
        try:
            if _ow(sys.stdout) > 0:
                # Shown to a person: what differs, in a few lines
                # (`taxjson sanity` has the tables).
                _sanity_console(root)
            else:
                cmd_sanity(argparse.Namespace(dir=str(root), items=[],
                                              tolerance=None, json=False,
                                              brief_extras=True))
        except SystemExit as _e:
            if isinstance(_e.code, str):
                # A message exit is a CONFIG problem (missing holdings
                # file, unknown account, malformed .toml) — not a
                # position difference (2026-09 CLI audit B13).
                _say("warning", "holdings check could not run",
                     *str(_e.code).splitlines(), indent="  ")
            elif _e.code and _ow(sys.stdout) <= 0:
                # (shown to a person, _sanity_console said it)
                _say("warning", "positions differ from the broker "
                     "holdings files",
                     "On a first project the likely cause is missing "
                     "history (purchases before your download starts: "
                     "`taxjson find-missing-history`, "
                     "docs/getting-started.md step 5); later, same-day "
                     "trades not yet in the CSVs are the usual one; "
                     "anything else is a booking problem (see `taxjson "
                     "sanity`).", indent="  ")
        except Exception as _e:  # noqa: BLE001 — never break a run
            _say("warning", f"holdings sanity skipped: {_e}", indent="  ")
    if not args.account:
        _first_run_summary(root, cfg, cache, mh_arg)
    if args.account:
        # A single-account run can't do cross-account wash detection or the
        # combined cross-account reports — those are SKIPPED (previously they
        # ran on just this account's data and silently OVERWROTE the combined
        # ccd/leaps/crosslistings with one-account truncations).
        # `<account>_wash.sum` and the combined reports keep whatever the
        # last FULL run wrote.
        # Canada's rule is the superficial-loss rule (audit A2-1360).
        _rule_n = ("wash-sale" if _country(settings) == "usa"
                   else "superficial-loss")
        _say("warning", f"single-account run ({args.account}): cross-account "
             f"{_rule_n} detection and the combined cross-account reports "
             f"were skipped",
             "They keep the last full run's contents. Run `taxjson run` "
             "with no --account before filing.", prog=f"{_PROG} run")


# Discrepancies the run's console names before `+N more`.
_SANITY_SHOWN = 8


def _sanity_console(root: Path) -> None:
    """The run's holdings check as a person reads it on the console:
    one message per finding with its few lines (`taxjson sanity` lists
    every row). Exits as cmd_sanity does (1 on a quantity difference,
    a message on a config problem)."""
    import contextlib
    import io
    import json as _json
    buf = io.StringIO()
    code: Any = 0
    try:
        with contextlib.redirect_stdout(buf):
            cmd_sanity(argparse.Namespace(dir=str(root), items=[],
                                          tolerance=None, json=True,
                                          brief_extras=True))
    except SystemExit as e:
        code = e.code
    if isinstance(code, str):
        raise SystemExit(code)
    try:
        doc = _json.loads(buf.getvalue())
    except ValueError:
        raise SystemExit(f"holdings check returned no result "
                         f"({buf.getvalue()[:200]!r})")
    rows = doc.get("discrepancies") or []

    def _n(k: int, one: str, many: str) -> str:
        return f"{k} {one if k == 1 else many}"
    if rows:
        first = rows if len(rows) <= _SANITY_SHOWN else rows[:5]
        shown = [f"{'+'.join(r.get('accounts') or [])} {r['symbol']}: "
                 f"taxjson {r['taxjson_qty']:g}, broker "
                 f"{r['holdings_qty']:g}" for r in first]
        if len(first) < len(rows):
            per: Dict[str, int] = {}
            for r in rows:
                a = "+".join(r.get("accounts") or [])
                per[a] = per.get(a, 0) + 1
            shown.append(f"+{len(rows) - len(first)} more"
                         + (" (by account: " + ", ".join(
                             f"{a} {k}" for a, k in sorted(per.items()))
                            + ")" if len(per) > 1 else ""))
        _say("warning", f"{_n(len(rows), 'position differs', 'positions differ')}"
             f" from the broker's holdings files", *shown,
             "`taxjson sanity` lists them. Fewer shares in taxjson than at "
             "the broker usually means missing history (purchases before "
             "your download starts, or shares transferred in: `taxjson "
             "find-missing-history`, docs/getting-started.md step 5); a "
             "trade after your last export is the other usual cause.",
             file=sys.stdout)
    else:
        # An account with open positions and no holdings file was never
        # compared: not an all-clear for it (pre-release review L4).
        _unchk = doc.get("uncovered_accounts") or []
        _say("note", "positions match the broker's holdings files"
             + (f" (checked accounts only; {len(_unchk)} unchecked: "
                f"{', '.join(_unchk)})" if _unchk
                else " (every checked account)" if doc.get("notes")
                else ""),
             file=sys.stdout)
    diffs = doc.get("cost_differences") or []
    if diffs:
        unexpl = sum(1 for d in diffs if d.get("reasons") == ["unexplained"])
        _say("note", f"{len(diffs)} of "
             f"{_n((doc.get('cost') or {}).get('compared', 0), 'position', 'positions')}"
             f" differ from the reports' cost ({unexpl} unexplained)",
             "`taxjson sanity` lists them with their reasons (a broker's "
             "book value is not always your ACB).", file=sys.stdout)
    inc = doc.get("income_share_mismatches") or []
    if inc:
        _say("note", f"{_n(len(inc), 'dividend row states', 'dividend rows state')}"
             f" a share count the books did not hold",
             "`taxjson sanity` lists them.", file=sys.stdout)
    if rows:
        raise SystemExit(1)


def _short_positions_cands(base_json: Path, account: str,
                           ticker_map: Optional[Path],
                           missing_history: Optional[Path]) -> List[Any]:
    """A taxable account's positions that go short in its books — a sale
    with no purchase in the files, unless the broker marks it a short
    sale or codes it closing (those are said as ATTENTION lines) — read
    like find-missing-history reads them (a journal's same-day legs —
    lib/missing_history.walk_journal_symbols — and missing_history.json
    entries are not missing history). [] when the
    books cannot be read (advisory: never breaks a run)."""
    try:
        from taxjson.lib.core import load_transactions
        from taxjson.lib.first_run import read_missing_history_pairs
        from taxjson.lib.missing_history import (detect_missing_history,
                                                  walk_journal_symbols)
        txs = load_transactions(base_json)
        journal = walk_journal_symbols(
            Path(base_json).parent,
            ticker_map if ticker_map and Path(ticker_map).is_file()
            else None)
        covered = {(sym, a.lower()) for sym, a in
                   read_missing_history_pairs(missing_history)}
        return [c for c in detect_missing_history(
                    txs, include_broker_shorts=True,
                    registered_accounts={account: False},
                    journal_symbols=journal)
                if c.account == account and not c.broker_marked_short
                and not c.broker_says_closing
                and (str(c.symbol).upper(), account.lower())
                not in covered]
    except Exception:                               # noqa: BLE001
        return []


def _short_positions_note(account: str, symbols: List[str],
                          booked: str = "open") -> Tuple[str, ...]:
    """The note (headline, detail) naming a taxable account's positions
    that go short (_short_positions_cands) and bear on the tax year.
    `booked`: what the gains engine did with their sales
    (lib/first_run.engine_booking, the split the run's closing summary
    and `taxjson sum` say too): "open" — not in any total —,
    "short_cover" — a short sale a later purchase closed, in the totals
    — or "matched" — sold from a purchase in the files."""
    shown = ", ".join(symbols[:5]) \
        + (f" +{len(symbols) - 5} more" if len(symbols) > 5 else "")
    if booked == "short_cover":
        return (f"{len(symbols)} position(s) go short in {account}'s data "
                f"({shown}): booked as short sales closed by a later "
                f"purchase",
                "Sales with no purchase in your files, unless they were "
                "real short sales. Their gain is in the totals at the "
                "covering purchase's cost — not yours if you held the "
                "shares before your files start; `taxjson "
                "find-missing-history` lists them with the fixes.")
    if booked == "matched":
        return (f"{len(symbols)} position(s) read short in {account}'s "
                f"data by the missing-history check ({shown})",
                "The gains engine sold them from purchases in your files, "
                "so they are in the totals; the check reads that day's "
                "rows in another order: compare it with the broker's "
                "trades.")
    return (f"{len(symbols)} position(s) go short in {account}'s data "
            f"({shown})",
            "Sales with no purchase in your files, unless they were real "
            "short sales. Until the purchase is supplied their gain is in "
            "no total — `taxjson find-missing-history` lists them with "
            "the fixes.")


# The accounts whose gains this run built or echoed, in run order:
# (name, base book, gains book, taxable equity) — _report_short_positions.
_SHORT_SOURCES: List[Tuple[str, Path, Path, bool]] = []


def _short_blocks(gains_json: Path) -> List[List[str]]:
    """The `ATTENTION: short:` messages of a gains stage's .diag, each
    with its continuation lines."""
    from taxjson.lib.pipeline import ATTENTION_SHORT
    out: List[List[str]] = []
    cur: Optional[List[str]] = None
    for line in _diag_lines(gains_json):
        if cur is not None and line[:1] in (" ", "\t") and line.strip():
            cur.append(line)
            continue
        cur = None
        if line.startswith(ATTENTION_SHORT):
            cur = [line]
            out.append(cur)
    return out


def _report_short_positions(root: Path, settings: Dict[str, Any],
                            cache: Path, ticker_map: Optional[Path],
                            missing_history: Optional[Path]) -> None:
    """The positions that go short in this run's books (sales with no
    purchase in the files), once, after every account's books: the ones
    that bear on the tax year one by one — a row of the year draws on
    the missing purchase or touches the position at all, or (Canada) an
    other taxable account of its ACB pool trades it that year; the test
    find-missing-history sorts by (lib/missing_history.
    classify_year_shorts) — and the rest in ONE line that names the
    command recording them. Display only: each gains stage's .diag and
    the .sum DIAGNOSTICS keep every line (owner request: a position
    that went short years ago and never comes up again is noise)."""
    sources = list(_SHORT_SOURCES)
    _SHORT_SOURCES.clear()
    year = settings.get("year")
    blocks: List[Tuple[Tuple[str, str], List[str]]] = []
    unmarked: List[Tuple[str, List[Any]]] = []
    for name, base_json, gains_json, taxable_equity in sources:
        for b in _short_blocks(gains_json):
            m = _SHORT_KEY_RE.match(b[0])
            blocks.append(((m["sym"], m["acct"]) if m else ("", ""), b))
        if taxable_equity:
            unmarked.append((name, _short_positions_cands(
                base_json, name, ticker_map, missing_history)))
    if not blocks and not any(c for _n, c in unmarked):
        return
    rows = (_year_short_rows(root, _project_base_files(cache), year)
            if year else {})

    def _listed(key) -> bool:
        r = rows.get(key)
        return r is None or r.year_listed

    shown_blocks, outside = [], {}
    for key, b in blocks:
        if _listed(key):
            shown_blocks.append(b)
        else:
            outside[key] = rows[key]
            # (a later pass's echo of it — the blended pass, a failed
            # stage — is not shown either)
            _SHOWN_THIS_RUN.add(("short",) + key)
    # What the gains engine booked for each listed pair (the split the
    # closing summary and `taxjson sum` make, lib/first_run.
    # engine_booking): a short a later purchase of the year closed is IN
    # the totals — "in no total" said for it contradicted both. This
    # run's plain gains files: the cross-account wash pass has not yet
    # rebuilt <acct>_gains_wash.json, the last run's (third pre-release
    # review, finding 5).
    booked: Dict[Tuple[str, str], str] = {}
    if rows:
        try:
            from taxjson.lib.first_run import engine_booking
            booked = engine_booking(
                cache, [rows[(c.symbol, c.account)]
                        for _n, cands in unmarked for c in cands
                        if (c.symbol, c.account) in rows],
                year, date_basis=_tax_date_basis(settings),
                prefer_wash=False)
        except Exception:                           # noqa: BLE001
            booked = {}
    notes: List[Tuple[str, List[str], str]] = []
    for name, cands in unmarked:
        keep: Dict[str, List[str]] = {}
        for c in cands:
            key = (c.symbol, c.account)
            if _listed(key):
                keep.setdefault(booked.get(key, "open"), []).append(
                    c.symbol)
            else:
                outside[key] = rows[key]
        for how in ("open", "short_cover", "matched"):
            if keep.get(how):
                notes.append((name, keep[how], how))
    _step("Checking for missing purchase history")
    for b in shown_blocks:
        for line in b:
            _echo_captured(line, once=True)
    for name, syms, how in notes:
        _say("note", *_short_positions_note(name, syms, how), indent="  ",
             file=sys.stdout)
    if notes:
        # A day a TOBASE line's two listings trade opposite ways with no
        # journal on it reads in clock order: the line to add when the
        # units were journaled (lib/missing_history.
        # undeclared_journal_days).
        try:
            from taxjson.lib.missing_history import undeclared_journal_days
            _named = {n[0] for n in notes}
            _undecl = [u for u in undeclared_journal_days(cache, ticker_map)
                       if u[0] in _named]
        except Exception:                           # noqa: BLE001
            _undecl = []
        if _undecl:
            _say("note", f"{len(_undecl)} day(s) with a buy of one listing "
                 f"and a sale of the other that a ticker.map TOBASE line "
                 f"joins, the same quantity, and no journal",
                 "A TOBASE line says two listings are one security, not "
                 "that units moved between them: such a day reads in "
                 "clock order, and a sale stamped before the buy is a "
                 "sale with no purchase. If the units were journaled (a "
                 "Norbert's gambit), declare each journal in a .tt file "
                 "of its account: "
                 + "; ".join(f"`JOURNAL {d} {b} {s_} {q:g}` ({a})"
                             for a, d, b, s_, q in _undecl[:5])
                 + (" ..." if len(_undecl) > 5 else "") + ".",
                 indent="  ", file=sys.stdout)
    if outside:
        n = len(outside)
        when = ("before" if all(
            (r.candidate.first_negative_date or "") < f"{year}-01-01"
            for r in outside.values()) else "outside")
        _say("note", f"{n} position{'' if n == 1 else 's'} went short "
             f"{when} {year} with missing history; no effect on {year}'s "
             f"numbers",
             f"No purchase in your files and no {year} activity. `taxjson "
             f"find-missing-history` lists {'it' if n == 1 else 'them'}; "
             f"`taxjson find-missing-history --write-missing-history "
             f"--outside-year` records {'it' if n == 1 else 'them'} in "
             f"missing_history.json so the run stops listing "
             f"{'it' if n == 1 else 'them'}.", indent="  ",
             file=sys.stdout)


def _uncovered_sales(root: Path, cfg: Dict[str, Any],
                     account: Optional[str] = None) -> List[Dict[str, Any]]:
    """[{symbol, account, sales, proceeds, booked}] — the tax year's
    sales in taxable accounts with no purchase in the files that
    missing_history.json does not cover (lib/first_run), with what the
    gains files did with them (`booked`, first_run.engine_booking:
    "open" — not in the totals —, "short_cover" or "matched"). []
    outside a project or when the books cannot be read (advisory)."""
    if not cfg:
        return []
    try:
        from taxjson.lib import first_run as FR
        from taxjson.lib.country import settings_tax_date
        from taxjson.lib.missing_history import walk_journal_symbols
        settings = cfg.get("settings") or {}
        accounts = cfg.get("accounts") or {}
        txs, _failed = FR.load_books(root / "work")
        if not txs:
            return []
        sheltered = {str(n): (a.get("type") == "sheltered")
                     for n, a in accounts.items() if isinstance(a, dict)
                     and a.get("type") in ("taxable", "sheltered")}
        tm = root / "ticker.map"
        journal = walk_journal_symbols(root / "work",
                                       tm if tm.is_file() else None)
        from taxjson.lib.missing_history import missing_history_path
        mh = missing_history_path(root, note=False)
        rows = FR.uncovered_short_sales(
            txs, settings.get("year"), sheltered=sheltered,
            covered=FR.read_missing_history_pairs(mh),
            date_basis=settings_tax_date(settings), journal=journal)
        booked = FR.engine_booking(root / "work", rows, settings.get("year"),
                                   date_basis=settings_tax_date(settings))
    except Exception:                               # noqa: BLE001
        return []
    return [{"symbol": r.candidate.symbol, "account": r.candidate.account,
             "sales": r.in_year_dispositions,
             "proceeds": r.in_year_proceeds,
             "booked": booked.get((r.candidate.symbol, r.candidate.account),
                                  FR.BOOKED_OPEN)}
            for r in rows if not account or r.candidate.account == account]


def _first_run_summary(root: Path, cfg: Dict[str, Any], cache: Path,
                       mh_file: Optional[Path]) -> None:
    """What the books show is still incomplete, each with the command
    that lists it (lib/first_run): printed after a full run when any
    count is nonzero, silent when clean; the counts also go to
    reports/run_summary.json. Advisory — never breaks a run."""
    from taxjson.lib import first_run as FR
    try:
        doc = FR.collect(root, cfg, missing_history=mh_file,
                         arrivals=transfer_arrivals(root, cache,
                                                    cfg.get("accounts")))
    except Exception as e:                          # noqa: BLE001
        emit_line(f"taxjson: warning: the closing summary could not be built "
                  f"({type(e).__name__}: {e}).", file=sys.stderr)
        return
    import json as _json
    try:
        # In reports/, not work/: every work/*.json is read as a stage
        # file by the fees report (and a planted symlink there must not
        # break the next run's fees stage).
        write_text_atomic(cache.parent / "reports" / FR.SUMMARY_FILE,
                          _json.dumps(doc, indent=2, sort_keys=True) + "\n")
    except OSError:
        pass
    from taxjson.lib.out import show_blocks
    show_blocks(FR.render_blocks(doc, mh_name=(mh_file.name if mh_file
                                               else "missing_history.json")),
                sys.stdout)


# The taxjson.toml template — every key, documented, per country — and
# its renderer live in lib/config_template (`taxjson format` uses the
# same one, so a fresh scaffold is already formatted).
def _render_init_config(country_canon: str,
                        year: Optional[int] = None
                        ) -> Tuple[str, Tuple[str, ...]]:
    """(toml_text, account_names) for `taxjson init` — the same tuple
    drives the inputs/ folder scaffold so config sections and input dirs
    can't drift apart. local_timezone is this machine's zone when it can
    be read, else left commented (there is no default: `taxjson run`
    then asks for it when the project has a crypto account)."""
    from taxjson.lib import config_template as CT
    return CT.render_init(country_canon, year, tz=CT.system_timezone())


# A commented `ticker.map` stub. The pipeline runs fine without this file, so
# every rule is left commented — it's here to document the format and the four
# keywords so a user can populate it without hunting the README.
# The ticker.map `taxjson init` writes is lib/ticker_map_format.
# init_template(): the `taxjson format-map` layout with a commented-out
# example per group, so format-map on a new project changes nothing.

# Keep generated artifacts out of version control. `taxjson run` rebuilds all
# of these from inputs/ + taxjson.toml, so none of them need committing.
_TEMPLATE_GITIGNORE = """\
# Generated by `taxjson run` — rebuildable from inputs/ + taxjson.toml.
work/
reports/
export/
# The redacted copy `taxjson redact` makes to share (review it first).
inputs_redact/
.DS_Store
"""



def _manifest_path_for(acct_dir: Path, cache: Path, name: str) -> Path:
    """The corp-action elections manifest the pipeline uses for an account.
    Delegates to _resolve_manifest (read-only mode) so `taxjson elect` and
    the run pipeline can never disagree about which file is live — a
    legacy work/ manifest is migrated to inputs/ on first touch."""
    return _resolve_manifest(acct_dir, cache, name, create=False)


def _hint_text(hints: Dict[str, Any]) -> str:
    """`key=value` pairs of an election's hints (400.0 -> 400)."""
    def _v(v):
        if isinstance(v, float) and v.is_integer() and abs(v) < 1e15:
            return str(int(v))
        return str(v)
    return ", ".join(f"{k}={_v(v)}" for k, v in sorted(hints.items()))


def _elections_section(doc, name: str, manifest_path: Path, root: Path,
                       country: Optional[str] = None) -> int:
    """One account's saved elections into `doc` (lib/out.Doc): a heading
    naming the manifest, then one `- ID: election` item per event with
    its summary, hints and notes aligned under it. Returns the count
    (0: nothing added — the caller lists the empty accounts together)."""
    from taxjson.lib import out as _out
    from taxjson.lib.corp_actions import Manifest, election_keys
    man = Manifest.load(manifest_path)
    if not man.records:
        return 0
    known = election_keys(country) if country else None
    doc.section(f"{name} — {_out.relpath(manifest_path, root)}")
    for eid, r in sorted(man.records.items()):
        # A hand-typed key no rule knows: `taxjson run` refuses it, so
        # say so here too (audit S072-16 — it was listed as if valid).
        bad = (known is not None and r.election
               and r.election not in known)
        doc.item(f"{eid}: {r.election or '(none)'}"
                 + (f" — UNKNOWN election for {country}" if bad else ""))
        pairs = []
        if r.summary:
            pairs.append(("event", r.summary))
        if r.hints:
            pairs.append(("hints", _hint_text(r.hints)))
        if r.notes:
            pairs.append(("notes", r.notes))
        if bad:
            pairs.append(("fix", f"`taxjson run` refuses it; choose again "
                                 f"with `taxjson elect {name} --redo "
                                 f"--event {eid}`"))
        doc.kv(pairs, indent="  ")
    return len(man.records)


def _print_elections(names: List[str], inputs_dir: Path, cache: Path,
                     root: Path, country: Optional[str],
                     footer: str) -> None:
    """The saved-elections listing of `taxjson elect [ACCOUNT]`."""
    from taxjson.lib.out import Doc
    doc = Doc("CORPORATE-ACTION ELECTIONS")
    empty = []
    for name in names:
        if not _elections_section(doc, name, _manifest_path_for(
                inputs_dir / name, cache, name), root, country):
            empty.append(name)
    if empty:
        doc.blank().para(f"No elections recorded: {', '.join(empty)}.")
    doc.blank().para(footer)
    doc.print()


def _reextract_pending_entry(acct_dir: Path, name: str, country: str,
                             manifest_path: Path,
                             event_id: str) -> Optional[Dict[str, Any]]:
    """The pending-elections entry for ONE event (same shape as
    work/pending_elections.json), rebuilt from the account's broker
    CSVs in-process. That file only lists events a --no-input run
    deferred, so a re-election after `--reset --event ID` (or a --set
    typed before any run) has nothing to validate against without
    this. None when no extractor knows the id. Extractor chatter is
    swallowed: the run repeats it."""
    import contextlib
    import io as _io
    from taxjson.bin.taxjson_corp_actions import (EXTRACTORS, _pending_doc,
                                                  extract_events)
    from taxjson.lib.corp_actions import combine_broker_copies
    try:
        grouped = group_inputs(acct_dir)
    except SystemExit:
        return None
    sink = _io.StringIO()
    for broker, csvs in grouped.items():
        extractor = EXTRACTORS.get(broker)
        if extractor is None:
            continue
        # The same extraction the run does (all the group's files as
        # context, broker-account copies combined), so the id matches.
        try:
            with contextlib.redirect_stderr(sink), \
                    contextlib.redirect_stdout(sink):
                events = combine_broker_copies(
                    extract_events(extractor, csvs, name,
                                   symbol_codes=_symbol_codes_state(
                                       acct_dir.parent.parent, name)),
                    stream=sink)
        except Exception:
            continue
        for ev in events:
            if ev.event_id == event_id:
                return _pending_doc([ev], manifest_path,
                                    country)["pending"][0]
    return None


def _wrong_country_section(doc, wrong: List[Dict[str, str]],
                           country: str) -> None:
    """`elect --pending`: the saved elections this country's rules do not
    know, each with the command that replaces it."""
    from taxjson.lib.country import display_name
    doc.section(f"NOT {display_name(country).upper()} ELECTIONS — "
                f"`taxjson run` refuses them")
    for w in wrong:
        doc.item(f"{w['account']}: {w['event_id']} (saved: "
                 f"{w['election']})")
        from taxjson.lib.out import Verbatim
        doc.kv([("event", w["summary"]),
                ("redo", Verbatim(f"taxjson elect {w['account']} --redo "
                                  f"--event {w['event_id']}"))],
               indent="  ")


def _print_pending(root: Path, inputs_dir: Path, cache: Path,
                   agg: Dict[str, Any], wrong: List[Dict[str, str]],
                   country: str) -> None:
    """`taxjson elect --pending`: each deferred event with its options —
    what each one books, the hints it needs and the ready `--set` line —
    and a last line saying what to do (the checklist's elections step
    shows that line)."""
    from taxjson.lib.corp_actions import Manifest
    from taxjson.lib.out import Doc, Verbatim
    events = [(acct, ev) for acct, adoc in
              sorted((agg.get("accounts") or {}).items())
              for ev in (adoc.get("pending") or [])]
    n = len(events)
    doc = Doc(f"PENDING ELECTIONS — {n} event{'s' if n != 1 else ''}"
              if events else None)
    if wrong:
        _wrong_country_section(doc, wrong, country)
    open_n = 0
    for acct, ev in events:
        eid = ev.get("event_id", "")
        man = Manifest.load(_manifest_path_for(inputs_dir / acct, cache,
                                               acct))
        rec = man.get(eid)
        doc.section(f"{acct}: {eid}")
        if ev.get("summary"):
            doc.para(ev["summary"], indent="  ")
        if ev.get("sheltered"):
            from taxjson.bin.taxjson_corp_actions import SHELTERED_NOTE
            doc.para(SHELTERED_NOTE[0].upper() + SHELTERED_NOTE[1:] + ".",
                     indent="  ")
        if rec is not None:
            # The pending file only clears on the next successful run —
            # without this marker, "did my --set take?" looked like NO
            # and users re-set (or overwrote) their election.
            doc.para(f"already elected: {rec.election} — re-run "
                     f"`taxjson run` to apply", indent="  ")
        else:
            open_n += 1
        for i, o in enumerate(ev.get("options", []), 1):
            hints = o.get("hints") or []
            doc.blank().line(f"  {i}. {o['election']}")
            if o.get("description"):
                doc.para(o["description"], indent="     ")
            pairs = [("hint", f"{h['key']} — "
                              f"{h.get('prompt') or 'a number'}")
                     for h in hints]
            hint_args = "".join(f" --hint {h['key']}=..." for h in hints)
            pairs.append(("set", Verbatim(
                f"taxjson elect {acct} --set {eid}={o['election']}"
                f"{hint_args}")))
            doc.kv(pairs, indent="     ")
    doc.blank()
    if open_n:
        # ONE short line: `taxjson checklist` shows it as the step's
        # detail.
        doc.line(f"{open_n} election{'s' if open_n != 1 else ''} pending: "
                 f"set each with `taxjson elect ACCOUNT --set`, then "
                 f"`taxjson run`.")
    elif events:
        doc.line("Every pending event has an election saved: run "
                 "`taxjson run` to apply them.")
    else:
        doc.line("Replace each of them with `taxjson elect ACCOUNT --redo "
                 "--event ID`, then run `taxjson run`.")
    doc.print()


def _save_manifest(man, manifest_path: Path) -> None:
    """Save the elections manifest, or one line naming it when its
    folder cannot be written (a read-only inputs/<acct>/): it was a
    PermissionError traceback on the .tmp file (re-audit A2-1418)."""
    try:
        manifest_path.parent.mkdir(parents=True, exist_ok=True)
        man.save(manifest_path)
    except OSError as e:
        _die_input(f"cannot write {manifest_path}: {e.strerror or e} — "
                   f"nothing was saved; make its folder writable and "
                   f"re-run.")


def _load_pending_agg(path: Path) -> Dict[str, Any]:
    """work/pending_elections.json, shape-checked: an object whose
    `accounts` maps each account to {"pending": [event, ...]}, each
    event an object with a text `event_id` and `options` a list of
    objects with a text `election`. Anything else (truncated, not
    UTF-8, a directory, a list, a pending row that is a number) is an
    InputFileError naming the file — elect --pending, elect --set and
    run --account read it bare and tracebacked (re-audit A2-0471,
    A2-0779, A2-1419, A2-1439, A2-1457, A2-1460)."""
    from taxjson.lib.json_input import InputFileError, read_json_doc
    doc = read_json_doc(path, list_key=None)
    accts = doc.get("accounts")
    if accts is None:
        doc["accounts"] = accts = {}
    if not isinstance(accts, dict):
        raise InputFileError(f'{path}: "accounts" must be an object')
    for a, ad in accts.items():
        if not isinstance(ad, dict):
            raise InputFileError(f'{path}: account {a!r} must be an '
                                 f'object')
        pend = ad.get("pending")
        if pend is None:
            ad["pending"] = pend = []
        if not isinstance(pend, list):
            raise InputFileError(f'{path}: {a}: "pending" must be a list')
        for i, ev in enumerate(pend):
            if not isinstance(ev, dict) \
                    or not isinstance(ev.get("event_id"), str):
                raise InputFileError(f'{path}: {a}: pending entry {i} '
                                     f'must be an object with an '
                                     f'"event_id"')
            opts = ev.get("options")
            if opts is None:
                ev["options"] = opts = []
            if not isinstance(opts, list) or any(
                    not isinstance(o, dict)
                    or not isinstance(o.get("election"), str)
                    or not isinstance(o.get("hints") or [], list)
                    or any(not isinstance(h, dict)
                           or not isinstance(h.get("key"), str)
                           for h in (o.get("hints") or []))
                    for o in opts):
                raise InputFileError(f'{path}: {a}: {ev["event_id"]}: '
                                     f'"options" must be a list of '
                                     f'{{"election": ...}} objects')
    return doc


def cmd_elect(args: argparse.Namespace) -> None:
    """View, clear, or redo corporate-action tax elections (taxable vs
    rollover, FMV/ACB hints) that `taxjson run` otherwise prompts for once
    and then reuses silently."""
    from taxjson.lib.corp_actions import Manifest
    from taxjson.lib import out as _out

    def fail(headline: str, *details: str, code: int = 1):
        # One headline naming what was refused, the why and the fix as
        # indented detail lines (docs/output-style.md).
        _out.fail(headline, prog=f"{_PROG} elect", details=details,
                  code=code)

    root = Path(args.dir).resolve()
    cfg = load_config(root)
    accounts = cfg.get("accounts", {})
    country = _country(cfg.get("settings", {}))
    cache = root / "work"
    inputs_dir = root / "inputs"

    if getattr(args, "pending", False):
        import json as _json
        # A saved election the project's country does not know (a
        # Canadian rollover left in a project switched to usa) stops
        # `taxjson run`; it is pending too (re-audit A2-0725).
        from taxjson.lib.corp_views import (ViewError,
                                            wrong_country_elections)
        try:
            _wrong = wrong_country_elections(root, cfg)
        except ViewError as e:
            fail(str(e))
        agg_path = cache / "pending_elections.json"
        if not agg_path.exists():
            if getattr(args, "json", False):
                # Same shape as the pending document itself, so a
                # machine consumer never has to parse prose.
                _json_out({"schema_version": 1, "accounts": {}}
                          | ({"wrong_country": _wrong} if _wrong else {}))
                return
            if _wrong:
                _print_pending(root, inputs_dir, cache, {}, _wrong, country)
                return
            print("No pending elections (no --no-input run has deferred "
                  "any, or they've been resolved).")
            return
        try:
            doc = _load_pending_agg(agg_path)
        except ValueError as e:
            # One line, exit 2 — not a traceback (re-audit A2-0471,
            # A2-0779, A2-1419, A2-1460). It is a work file `run`
            # rebuilds.
            fail(str(e), "A damaged work file: re-run `taxjson run "
                 "--no-input` to rebuild it.", code=2)
        if getattr(args, "json", False):
            if _wrong:
                doc = dict(doc, wrong_country=_wrong)
            print(_json.dumps(doc, indent=2, sort_keys=True))
            return
        _print_pending(root, inputs_dir, cache, doc, _wrong, country)
        return

    # No account → list every account's elections (read-only).
    if not args.account:
        if args.redo or args.reset:
            fail("--redo/--reset need an account",
                 "For example: `taxjson elect margin --redo`.")
        if getattr(args, "set", None) or getattr(args, "hint", None):
            # Falling through to the read-only listing here looked like
            # success (exit 0) while saving NOTHING (REVIEW #7).
            fail("--set/--hint need an account",
                 "For example: `taxjson elect margin --set "
                 "EVENT_ID=ELECTION`. Nothing was saved.")
        if getattr(args, "json", False):
            # Machine listing of SAVED elections (--pending --json
            # already covers the unresolved ones) — previously --json
            # here silently printed the text listing.
            from taxjson.lib.corp_actions import Manifest
            doc: Dict[str, Any] = {}
            for name in accounts:
                mp = _manifest_path_for(inputs_dir / name, cache, name)
                if not mp.exists() and not mp.is_symlink():
                    continue
                try:
                    man = Manifest.load(mp)
                except Exception as e:
                    doc[name] = {"error": str(e)}
                    continue
                doc[name] = {
                    eid: {"election": rec.election,
                          "summary": getattr(rec, "summary", "") or "",
                          "hints": dict(rec.hints or {}),
                          "notes": rec.notes or ""}
                    for eid, rec in sorted(man.records.items())}
            _json_out({"accounts": doc})
            return
        _print_elections(list(accounts), inputs_dir, cache, root, country,
                         "Redo one: `taxjson elect ACCOUNT --redo` (add "
                         "`--event ID` for just one event).")
        return

    name = args.account
    if name not in accounts:
        fail(f"no [accounts.{name}] in taxjson.toml",
             f"Accounts: {', '.join(accounts) or '(none)'}.")
    acct_dir = inputs_dir / name
    manifest_path = _manifest_path_for(acct_dir, cache, name)
    if getattr(args, "hint", None) and not getattr(args, "set", None):
        fail("--hint only applies with --set EVENT_ID=ELECTION",
             "Nothing was saved.")
    if getattr(args, "json", False):
        if args.redo or args.reset or getattr(args, "set", None):
            fail("--json applies to the listings only, not to "
                 "--set/--redo/--reset",
                 "Listings: `taxjson elect [ACCOUNT] --json`, `taxjson "
                 "elect --pending --json`.")
        # One account's SAVED elections — same shape as the
        # all-accounts listing (it printed the text listing before).
        doc_one: Dict[str, Any] = {}
        if manifest_path.exists() or manifest_path.is_symlink():
            try:
                _man = Manifest.load(manifest_path)
                doc_one[name] = {
                    eid: {"election": rec.election,
                          "summary": getattr(rec, "summary", "") or "",
                          "hints": dict(rec.hints or {}),
                          "notes": rec.notes or ""}
                    for eid, rec in sorted(_man.records.items())}
            except Exception as e:
                doc_one[name] = {"error": str(e)}
        _json_out({"accounts": doc_one})
        return

    # --set: non-interactive election writing (headless/CI bootstrap).
    if isinstance(getattr(args, "set", None), list):
        # A second --set used to replace the first silently (argparse
        # keeps the last) and the run still asked for the dropped event
        # (re-audit A2-0563 / A2-0568). --hint belongs to ONE election,
        # so one --set per command.
        if len(args.set) > 1:
            fail(f"{len(args.set)} --set flags — give ONE --set per "
                 f"command",
                 f"Its --hint flags belong to it: run `taxjson elect "
                 f"{name} --set ...` once per event. Nothing was saved.")
        args.set = args.set[0]
    if getattr(args, "set", None):
        from taxjson.lib.corp_actions import (ElectionRecord,
                                              RULES_BY_COUNTRY)
        if "=" not in args.set:
            # The example names a key this country accepts (a US
            # project refuses the Canadian s.85.1 key; audit A2-0718).
            _ex = "reorg_368" if country == "usa" else "rollover_s_85_1_5"
            fail("--set expects EVENT_ID=ELECTION",
                 f"For example `--set 20250317-abg-abh-1a2b={_ex}`; "
                 f"`taxjson elect --pending` lists each event's "
                 f"choices.")
        event_id, election = args.set.split("=", 1)
        event_id, election = event_id.strip(), election.strip()
        if not event_id:
            # A ""-keyed record could never be targeted by --event
            # afterwards (REVIEW #34).
            fail("--set: empty EVENT_ID (expected EVENT_ID=ELECTION)",
                 "`taxjson elect --pending` lists the ids.")
        # PER-EVENT validation on every --set: the country-wide set
        # accepted e.g. a spinoff election for a merger, which only
        # exploded at the NEXT run as a raw KeyError traceback (REVIEW
        # #6). The pending doc (written by the exit-3 run that told the
        # user this id) is the cheap source; when it doesn't list the
        # event — the documented `--reset --event ID` then `--set`
        # re-election, or a --set before any run — the event is
        # re-extracted from the account's CSVs instead.
        event_options = None
        event_summary = None
        event_hints_by_option: Dict[str, list] = {}
        pending_entry = None
        agg_path = cache / "pending_elections.json"
        if agg_path.exists():
            import json as _json
            try:
                _pdoc = _load_pending_agg(agg_path)
                for _ev in (((_pdoc.get("accounts") or {}).get(name)
                             or {}).get("pending") or []):
                    if _ev.get("event_id") == event_id:
                        pending_entry = _ev
            except ValueError:
                pass            # damaged: re-extracted below (A2-0779)
        if pending_entry is None:
            pending_entry = _reextract_pending_entry(
                acct_dir, name, country, manifest_path, event_id)
        if pending_entry is not None:
            event_options = {"ignore"} | {
                o.get("election")
                for o in pending_entry.get("options", [])}
            event_summary = pending_entry.get("summary")
            for o in pending_entry.get("options", []):
                event_hints_by_option[o.get("election")] = (
                    o.get("hints") or [])
        if event_options is not None:
            if election not in event_options:
                fail(f"election {election!r} is not valid for event "
                     f"{event_id}",
                     f"This event offers: "
                     f"{', '.join(sorted(event_options))}.")
        else:
            known = {"ignore"}
            for rule in RULES_BY_COUNTRY.get(country, {}).values():
                known.update(k for k, _ in rule.options)
            if election not in known:
                fail(f"unknown election {election!r} for "
                     f"country={country}",
                     f"Valid: {', '.join(sorted(known))}.")
        hints = {}
        for h in (args.hint or []):
            if "=" not in h:
                fail(f"--hint expects KEY=VALUE, got {h!r}",
                     "Nothing was saved.")
            k, v = h.split("=", 1)
            try:
                hints[k.strip()] = float(v)
                from taxjson.lib.corp_actions import hint_value_problem
                _prob = hint_value_problem(k.strip(), hints[k.strip()])
                if _prob:
                    # A negative allocated ACB created basis from
                    # nothing and a negative FMV booked negative
                    # dividend income, saved at exit 0; nan/inf failed
                    # only on the next run (S039-00).
                    fail(f"--hint: {_prob}", "Nothing was saved.")
            except ValueError:
                # Every hint consumer float()s its value — storing the
                # raw string reported "Election saved" and then crashed
                # the NEXT run with a ValueError traceback (REVIEW #5,
                # classic trigger: European decimal comma).
                fail(f"--hint: {k.strip()}={v.strip()!r} is not a number",
                     f"Use a decimal POINT, e.g. `{k.strip()}=12.50`. "
                     f"Nothing was saved.")
        if event_options is not None:
            # The pending doc declares exactly which hints this
            # election needs — a rollover saved WITHOUT its
            # allocated_acb used to print "Election saved" and later
            # emit a $0-basis position with no warning; a typo'd hint
            # key was stored and ignored by every consumer.
            declared = {h.get("key")
                        for h in event_hints_by_option.get(election, [])}
            missing = declared - set(hints)
            unknown = set(hints) - declared
            if missing:
                specs = " ".join(f"--hint {k}=<value>"
                                 for k in sorted(missing))
                fail(f"{election} needs {', '.join(sorted(missing))}",
                     f"Add `{specs}`; `taxjson elect --pending` says what "
                     f"each means. Nothing was saved.")
            if unknown:
                fail(f"{election} does not use hint(s) "
                     f"{', '.join(sorted(unknown))}",
                     (f"It takes: {', '.join(sorted(declared))}."
                      if declared else "It takes none.")
                     + " Nothing was saved.")
        man = Manifest.load(manifest_path)
        prior = man.get(event_id)
        # Best summary available: pending doc (the happy path — user
        # copied the id from `elect --pending`), else the prior
        # record's. Only a truly unknown id warns — the old note fired
        # on every VALIDATED save while a bogus id got the same mild
        # text (severity inverted).
        summary = (event_summary
                   or (prior.summary if prior else None)
                   or "(set non-interactively)")
        if prior is None and event_options is None:
            # Saving anyway left a junk record in the committed
            # manifest.json that no run ever reads (2026-09 CLI audit).
            fail(f"{event_id!r} matches no pending event — nothing was "
                 f"saved",
                 f"It is no saved election either, and no corporate "
                 f"action in {name}'s inputs. Check the id with `taxjson "
                 f"elect --pending` (after a `taxjson run --no-input`) or "
                 f"`taxjson elect {name}`.")
        man.set(ElectionRecord(event_id=event_id, summary=summary,
                               election=election,
                               notes="set via elect --set",
                               hints=hints))
        _save_manifest(man, manifest_path)
        _done = _out.Doc(f"Election saved: {event_id} = {election}")
        _done.kv(([("hints", _hint_text(hints))] if hints else [])
                 + [("file", _out.Verbatim(_out.relpath(manifest_path,
                                                        root)))],
                 indent="  ")
        _done.line("Run `taxjson run` to apply it.")
        _done.print()
        if ("fmv_per_share" in hints and abs(hints["fmv_per_share"]) < 1e-12
                and election.startswith("taxable_")):
            # 0 is the documented "defer" value (R1-11): say what it books.
            _out.warn(f"fmv_per_share=0 books this {election} at $0",
                      prog=f"{_PROG} elect",
                      details=["No income and a $0 cost for the new "
                               "shares. Every `taxjson run` and the "
                               "checklist flag it until a value is "
                               "set."])
        from taxjson.lib.corp_actions import ALLOCATED_BASIS_HINT
        _ak = ALLOCATED_BASIS_HINT.get(election)
        if _ak and _ak in hints and abs(hints[_ak]) < 0.005:
            # The missing hint is refused; an explicit 0 was saved with
            # no word (audits S073-21, S074-04).
            _out.warn(f"{_ak}=0 moves NO cost to the spun-off shares",
                      prog=f"{_PROG} elect",
                      details=["They book at $0 and the parent keeps all "
                               "of it. Enter the allocated amount; every "
                               "`taxjson run` and the checklist flag it "
                               "until then."])
        return

    if not (args.redo or args.reset):
        _print_elections([name], inputs_dir, cache, root, country,
                         f"Redo all: `taxjson elect {name} --redo`; one "
                         f"event: add `--event ID`; just clear: "
                         f"`--reset`.")
        return

    # --redo / --reset: clear the chosen elections from the manifest.
    if args.redo and not sys.stdin.isatty():
        # The old path cleared FIRST and then crashed on the missing
        # TTY — the user's saved (non-rebuildable) elections were
        # already gone (REVIEW #4).
        fail("--redo asks again, so it needs a terminal",
             f"Headless: `taxjson elect {name} --reset [--event ID]` to "
             f"clear, then `taxjson elect {name} --set EVENT_ID=ELECTION` "
             f"(ids and options: `taxjson elect --pending` after a "
             f"`taxjson run --no-input`). Nothing was cleared.")
    manifest_backup = (manifest_path.read_bytes()
                       if manifest_path.exists() else None)
    man = Manifest.load(manifest_path)
    # `is not None`: --event '' (e.g. an unset shell variable) must NOT
    # silently widen to ALL elections (REVIEW #34 wiped everything).
    if args.event is not None:
        if args.event not in man.records:
            fail(f"no election '{args.event}' for account '{name}'",
                 f"`taxjson elect {name}` lists the event ids.")
        targets = [args.event]
    else:
        targets = list(man.records)
    for eid in targets:
        man.records.pop(eid, None)
    _save_manifest(man, manifest_path)
    print(f"Cleared {len(targets)} election(s) from "
          f"{_out.relpath(manifest_path, root)}.")

    if args.reset:
        print(f"Next `taxjson run` will re-prompt for them.")
        return

    # --redo: re-prompt now by re-running corp-actions interactively.
    # Any failure or Ctrl-C mid-prompt RESTORES the pre-clear manifest —
    # elections are the one non-rebuildable user artifact (REVIEW #4).
    grouped = group_inputs(acct_dir)
    # The same valuation inputs `taxjson run` passes (event-date rates,
    # base currency, ticker.map): without them a cross-currency merger's
    # new shares were booked in the wrong currency, and a following
    # `run --fast` kept that corp file (A2-0981, A2-0982).
    _redo_corp_flags: List[str] = []
    _rates = cache / "to_base.csv"
    if _rates.exists():
        _redo_corp_flags += ["--rates", str(_rates)]
    _base_cur = (cfg.get("settings") or {}).get("base_currency")
    if _base_cur:
        _redo_corp_flags += ["--base-currency", str(_base_cur)]
    _tmap = root / "ticker.map"
    if _tmap.exists():
        _redo_corp_flags += ["--ticker-map", str(_tmap)]
    _acfg = ((cfg.get("accounts") or {}).get(name) or {})
    _redo_sheltered = ([] if isinstance(_acfg, dict)
                       and _acfg.get("type", "sheltered") == "taxable"
                       else ["--sheltered"])
    ran = False
    try:
        for broker, csvs in grouped.items():
            if broker not in CORP_ACTION_BROKERS:
                continue
            out = cache / f"{name}_{broker}_corp.json"
            _sc = _symbol_codes_state(root, name)
            cmd = _cmd("taxjson-corp-actions") + [
                "--account-name", name, "--country", country,
                "--brokerage", broker, "--manifest", str(manifest_path),
            ] + _redo_corp_flags + _redo_sheltered + (
                ["--symbol-codes", str(_sc)]
                if _sc and broker == "questrade" else []) + [
                str(p) for p in csvs]
            run_to_file(cmd, out, interactive=True)
            ran = True
    except (subprocess.CalledProcessError, KeyboardInterrupt):
        if manifest_backup is not None:
            manifest_path.write_bytes(manifest_backup)
        fail("--redo interrupted",
             f"The previous elections for '{name}' were restored "
             f"unchanged.")
    if not ran:
        print(f"No corp-action events to re-elect for '{name}'.")
    else:
        print("\nElections saved. Run `taxjson run` to recompute.")


def _tx_period_cutoff(period: str):
    """Oldest date to include for a look-back window: 30d / 6w / 3m / 1y,
    `mtd` / `ytd` (calendar month/year to date), or `all` for no lower bound
    (full history). Days and weeks are exact; months and years use calendar
    arithmetic. Year tokens (YYYY, tax_year) are NOT look-backs — the
    callers resolve them to that calendar year first (_period_keep,
    fees-sum); a lower-bound reading of them (the removed since-based
    commands' "through today") disagreed with every period command
    (S039-04)."""
    import re
    import calendar
    from datetime import date, timedelta
    tok = (period or "").strip().lower()
    if tok in ("all", "max"):
        # date.min.isoformat() == '0001-01-01', so every real row's
        # `d >= cutoff` compare passes — the whole history is included.
        return date.min
    if tok == "mtd":
        today = date.today()
        return date(today.year, today.month, 1)
    if tok == "ytd":
        return date(date.today().year, 1, 1)
    m = re.fullmatch(r"\s*(\d+)\s*([dwmy])\s*", (period or "").lower())
    if not m:
        _die(f"invalid time period {period!r} "
                 f"(use e.g. 30d, 6w, 3m, 1y, mtd, ytd, all)")
    n, unit = int(m.group(1)), m.group(2)
    today = date.today()
    # Magnitudes that walk past year 1 raised ValueError (and huge day
    # counts OverflowError) as raw tracebacks on EVERY period-aware
    # command — including the plausible typo "2026y" (REVIEW #32).
    # Anything reaching past all representable history means "all".
    _CAP_DAYS = (today - date.min).days
    if (unit == "d" and n >= _CAP_DAYS) or \
       (unit == "w" and n >= _CAP_DAYS // 7) or \
       (unit == "m" and n >= today.year * 12) or \
       (unit == "y" and n >= today.year):
        return date.min
    if unit == "d":
        return today - timedelta(days=n)
    if unit == "w":
        return today - timedelta(weeks=n)
    months = n if unit == "m" else 12 * n
    total = today.year * 12 + (today.month - 1) - months
    y, mo = divmod(total, 12)
    mo += 1
    return date(y, mo, min(today.day, calendar.monthrange(y, mo)[1]))


_TAX_YEAR_TOKENS = ("tax_year", "tax-year", "taxyear", "ty")

# A literal 4-digit tax year is a valid PERIOD token: `taxjson events 2025`
# scopes to calendar year 2025 (same shape the -sum roll-ups label
# "tax year N").
_YEAR_TOKEN_RE = re.compile(r"(19|20)\d{2}")

# One canonical help string for every PERIOD positional (AUDIT-2026-07-ui A1).
_PERIOD_HELP = ("Window: 30d, 6w, 3m, 1y, mtd, ytd, all, a tax year "
                "(2025), or tax_year/ty for the config year "
                "(default: tax year)")


def _year_keep(ys: str):
    """A tax-year window predicate, tagged `.tax_year` so the gains views
    can apply it on the project's tax_date basis (_gains_row_date)."""
    keep = (lambda d: d.startswith(ys))
    keep.tax_year = ys
    return keep


def _settle_basis(root: Path, doc: Optional[Dict[str, Any]] = None) -> bool:
    """True when dispositions belong to a tax year by SETTLEMENT date: the
    gains file's own summary.tax_date_basis when it says, else [settings]
    tax_date, else the country default (Canada settle, USA trade) — the
    same rule `sum`, form-export and the gains engine follow."""
    b = str(((doc or {}).get("summary") or {}).get("tax_date_basis")
            or "").strip().lower()
    if b in ("settle", "trade"):
        return b == "settle"
    settings = _soft_settings(root)
    td = str(settings.get("tax_date") or "").strip().lower()
    if td in ("settle", "trade"):
        return td == "settle"
    return _tax_date(settings) == "settle"


def _gains_row_date(t: Dict[str, Any], keep, settle: bool) -> str:
    """The date a gains row is windowed on: its SETTLEMENT date for a
    tax-year window on a settle-basis project (a Dec-31 trade that
    settles in January is next year's disposition — the gains artifacts,
    `sum` and form-export all place it there), else the trade date. The
    trade-date window dropped such rows from every year's winners /
    ccd-sum / leaps / gains (audit R1-171, R1-186, R1-238, R1-273)."""
    if settle and getattr(keep, "tax_year", None):
        return str(t.get("date_settle") or t.get("date") or "")
    return str(t.get("date") or "")


def _period_keep(period: str, root: Path):
    """Resolve a period token to `(keep(date_str) -> bool, scope_label)`.
    `tax_year` (or `ty`) binds the window to the config tax year; a literal
    YYYY is that calendar year; `all` is the whole history; anything else is
    a look-back window (30d/6w/3m/1y)."""
    tok = (period or "").strip().lower()
    if _YEAR_TOKEN_RE.fullmatch(tok):
        return _year_keep(tok), f"tax year {tok}"
    if tok in _TAX_YEAR_TOKENS:
        year = _soft_settings(root).get("year")
        if not year:
            _die("'tax_year' needs [settings] year in taxjson.toml "
                     "(or give an explicit window like 1y).")
        ys = str(year)
        return _year_keep(ys), f"tax year {year}"
    cutoff = _tx_period_cutoff(period).isoformat()      # handles all/max + errors
    if tok in ("all", "max"):
        label = "all history"
    elif tok in ("mtd", "ytd"):
        label = f"{tok.upper()} (since {cutoff})"
    else:
        label = f"last {period}"
    return (lambda d: d >= cutoff), label


# Native (pre-base) per-account transaction file, in preference order: the raw
# equity merge, then the crypto native (post fill-crypto-prices), then sorted.
# These carry NATIVE currency with NO TOBASE / currency-to-base mapping —
# exactly what `taxjson events` shows.
_NATIVE_TX_SUFFIXES = ("_raw.json", "_filled.json", "_sorted.json")


def _native_tx_file(cache: Path, account: str) -> Optional[Path]:
    for suf in _NATIVE_TX_SUFFIXES:
        p = cache / f"{account}{suf}"
        if p.exists():
            return p
    return None


def _discover_tx_accounts(cache: Path) -> List[str]:
    # The same suffixes the single-account form reads (_native_tx_file):
    # after a failed fill-crypto stage only <acct>_sorted.json exists,
    # and the all-accounts views dropped the account silently (S039-07).
    names = set()
    for suf in _NATIVE_TX_SUFFIXES:
        for p in cache.glob(f"*{suf}"):
            # pathlib's `*` matches leading dots — keep dot-prefixed
            # pipeline intermediates from masquerading as accounts.
            if not p.name.startswith("."):
                names.add(p.name[: -len(suf)])
    return sorted(names)


def _tx_display_line(tx: dict, settle: bool = False) -> Optional[str]:
    """Human-readable line for `taxjson events`. Money amounts (total,
    fee, dividend/tax/interest/adjust amount) are shown to 2 decimals; quantity
    and per-share price keep their significant digits (a 0.0375 dividend rate
    or a 0.25178314 crypto qty must not be rounded away). Mirrors the .tt field
    layout but is a DISPLAY formatter — distinct from tx_to_tt_line, which
    keeps full precision for round-trippable .tt output. Returns None for
    actions with no representation. `settle=True` writes the SETTLEMENT
    date (a .tt line's single date on a settle-basis project): the
    single-account view is round-trippable taxtext, and pasting its
    trade-dated Dec-31 sale into next year's .tt dropped it from both
    years (S002-03)."""
    money = fmt_money               # dollar amount → 2 decimals (shared)

    def sig(x):                         # qty / price → full precision
        # repr(): EXACT round-trip. The old :.8f truncated a 9-decimal
        # crypto qty, so re-importing the view produced a different
        # transaction id — dedup missed and every trade double-booked
        # (REVIEW #19).
        s = repr(float(x or 0))
        if s.endswith(".0"):
            s = s[:-2]
        return "0" if s in ("", "-0") else s

    action = tx.get("action", "")
    date = tx.get("date", "")
    if settle and tx.get("date_settle"):
        date = tx["date_settle"]
    time = tx.get("time", "09:30:00")
    sym = tx.get("symbol", "")
    # "?" like every other view (trades-sum, fees): a CAD label on a
    # currency-less row misstated it in a non-CAD project, and the line
    # is re-importable .tt (R1-287).
    cur = tx.get("currency") or "?"
    qty, price = tx.get("quantity"), tx.get("price")
    net = float(tx.get("net_amount") or 0.0)
    gross = float(tx.get("gross_amount") or 0.0) or net
    # fee + commission: parsers split the charge across both keys
    # (Questrade uses `commission`), so reading only `fee` printed
    # 0.00 on every row — and the "round-trippable" single-account
    # view silently erased the deductible fees on re-import
    # (REVIEW #36/#18). Same rule as _tx_fee (fees/trades-sum).
    fee = (float(tx.get("fee") or 0.0)
           + float(tx.get("commission") or 0.0))

    # SIGNED total/fee, exactly as convert_tt.tx_to_tt_line emits them:
    # abs() printed every fee rebate as a charge and a penny close's
    # negative proceeds as positive, so the "round-trippable" view
    # flipped both on re-import (audit S039-11).
    if action in ("BUYSELL", "ASSIGN"):
        line = f"{action} {date} {time} {sym} {sig(qty)} {cur} {sig(price)} {money(net)} {money(fee)}"
        # The declared contract size rides along as `x<size>`, as in
        # tx_to_tt_line: without it a re-imported x10 mini or a CL
        # future lost its multiplier (A2-0621).
        from taxjson.lib.core import is_option_symbol
        try:
            _m = float(tx.get("multiplier") or 0.0)
        except (TypeError, ValueError):
            _m = 0.0
        if _m > 0 and (str(sym).startswith(("F:", "/", "\\"))
                       or (is_option_symbol(str(sym)) and _m != 100.0)):
            line += f" x{_m:g}"
        return line
    if action == "TRANSFER":
        # The opt-in DECLARED token rides along as in tx_to_tt_line, or a
        # re-import loses the declaration (audit A2-0989).
        from taxjson.lib.pipeline import MANUAL_TRANSFER_DECLARATION
        decl = (" DECLARED" if tx.get("description")
                == MANUAL_TRANSFER_DECLARATION else "")
        return f"{action} {date} {time} {sym} {sig(qty)} {cur} {sig(price)} {money(net)}{decl}"
    if action == "SPLIT":
        return f"SPLIT {date} {time} {sym} {tx.get('symbol_new') or sym} {sig(qty)}"
    if action in ("DIVIDEND", "DIVIDEND_IN_LIEU", "TAX"):
        # Signed so a reversal row reads as negative instead of masquerading
        # as more income/tax.
        # The withholding-NETTED 9th column, as tx_to_tt_line writes it:
        # without it the line re-parses net as gross (audit A2-0989).
        net9 = f" {money(net)}" if abs(net - gross) > 0.005 else ""
        return f"{action} {date} {time} {sym} {sig(qty)} {cur} {sig(price)} {money(gross)}{net9}"
    if action in ("INTEREST", "FEE"):
        return f"{action} {date} {time} {cur} {money(net)}"
    if action in ("ADJUST", "DISALLOW"):
        return f"{action} {date} {time} {sym} {cur} {money(net)}"
    return None


# Back-compat aliases: the table helpers were promoted to
# taxjson.lib.report_model (shared with the standalone report tools); the
# 20+ call sites below keep their historical names.
_align_columns = align_columns


def _print_report_table(rows: List[str], padding: str = "   ",
                        rule_before_last: bool = False, **fit) -> None:
    """print()s taxjson.lib.report_model.format_report_table — see there
    (`fit=True, drop=..., key=...`: the house table that fits the
    width)."""
    for line in format_report_table(rows, padding=padding,
                                    rule_before_last=rule_before_last,
                                    **fit):
        print(line)


_ISO_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def _json_out(doc: Dict[str, Any]) -> None:
    """Machine output: pure JSON on stdout (notes/warnings stay on
    stderr) — the GUI's data source; never screen-scraped text.

    STRICT JSON: non-finite floats are emitted as null. json.dumps'
    default allow_nan=True wrote bare NaN/Infinity tokens, which are
    invalid JSON — node's JSON.parse throws and jq silently corrupts
    them (REVIEW #41)."""
    import json
    import math

    def _clean(v):
        if isinstance(v, float) and not math.isfinite(v):
            return None
        if isinstance(v, dict):
            return {k: _clean(x) for k, x in v.items()}
        if isinstance(v, (list, tuple)):
            return [_clean(x) for x in v]
        return v

    print(json.dumps(_clean(doc), indent=2, sort_keys=True, default=str))


# ---- Instrument-class filters (trades / gains) -----------------------
# `--options/--equities/--futures/--puts/--calls` narrow a view to
# particular instrument kinds. Multiple flags OR together; no flag means
# "all instruments" (the historical default). A futures OPTION (F: prefix
# + OCC contract block) is genuinely both a future and an option, so it
# matches `--futures` AND `--options`/`--puts`/`--calls`.
_INSTRUMENT_FLAGS = ("options", "equities", "futures", "puts", "calls")


def _add_instrument_filters(parser: argparse.ArgumentParser) -> None:
    g = parser.add_argument_group(
        "instrument filters",
        "Restrict to instrument classes (combine freely; default: all). "
        "A futures option counts as both a future and an option.")
    g.add_argument("--options", action="store_true",
                   help="Option contracts (OCC symbols)")
    g.add_argument("--equities", action="store_true",
                   help="Equities/ETFs (neither options nor futures)")
    g.add_argument("--futures", action="store_true",
                   help="Futures (symbols starting with F:, / or "
                        "a backslash)")
    g.add_argument("--calls", action="store_true",
                   help="Call options only")
    g.add_argument("--puts", action="store_true",
                   help="Put options only")


def _instrument_tags(symbol: str) -> set:
    """The instrument classes a symbol belongs to. A symbol can carry
    several tags: a futures option is `futures` + `options` + `calls`|
    `puts`; a plain equity is just `equities`."""
    from taxjson.lib.core import is_option_symbol, parse_option_right
    from taxjson.lib.ticker_map import is_future_ticker
    sym = symbol or ""
    tags = set()
    opt = is_option_symbol(sym)
    fut = is_future_ticker(sym)
    if opt:
        tags.add("options")
        right = parse_option_right(sym)
        if right == "C":
            tags.add("calls")
        elif right == "P":
            tags.add("puts")
    if fut:
        tags.add("futures")
    if not opt and not fut:
        tags.add("equities")
    return tags


def _instrument_filter(args: argparse.Namespace):
    """A `symbol -> bool` predicate built from the --options/--equities/…
    flags, or None when none were given (i.e. show every instrument)."""
    wanted = {f for f in _INSTRUMENT_FLAGS if getattr(args, f, False)}
    if not wanted:
        return None
    return lambda sym: bool(wanted & _instrument_tags(sym))


def _trade_total(tx: dict) -> float:
    """A trade row's money for the buy/sell totals, in the engine's pool
    terms (core.py _trade_money): a BUY's cost as a magnitude (parsers
    spell it either sign), a SELL's proceeds SIGNED — a penny close whose
    commission exceeds the gross really has negative proceeds, and abs()
    added it to TOTAL SELL (audit S039-11)."""
    net = float(tx.get("net_amount") or 0.0)
    return net if float(tx.get("quantity") or 0.0) < 0 else abs(net)


def _vprint(text: str = "", indent: str = "", hang: Optional[str] = None
            ) -> None:
    """A query view's prose line, wrapped at the house width
    (docs/output-style.md; unwrapped when captured for a program)."""
    from taxjson.lib.out import fill
    print(fill(text, indent=indent, hang=hang) if text else "")


def _view_msg(kind: str, text: str, *details: str) -> None:
    """A query view's diagnostic on stderr in the house style
    (docs/output-style.md): `taxjson <cmd>: <kind>: <headline>`, then
    each detail indented. `kind`: note | warning."""
    from taxjson.lib import out
    out.emit(kind, text, prog=_cmd_prog(), details=details)


def _run_tx_view(args: argparse.Namespace, actions, label: str,
                 symbol_filter=None) -> None:
    """Shared engine for `transactions` / `dividends` / `buysell`: read the
    native (pre-base) per-account files, filter by look-back window and (if
    given) an action set, sort chronologically, print aligned taxtext."""
    import json
    root = Path(args.dir).resolve()
    cache = root / "work"
    keep, _scope, account = _view_window(args, root)

    if account:
        accounts = [account]
        if _native_tx_file(cache, account) is None:
            _die(f"no native transaction file for account {account!r} in "
                 f"work/ — run `taxjson run` first, or check the name")
    else:
        accounts = _discover_tx_accounts(cache)
        if not accounts:
            _die("no transaction files in work/ — run `taxjson run` first")
        # S045-09 twin (audit A2-1182): an account with inputs but no
        # books was simply absent from trades/divs/events/roc.
        # An account whose stage failed has no native book: say so, as
        # the -sum twins do (audit A2-0333).
        _warn_accounts_without_books(root, accounts, label,
                                     "transaction file")

    rows = []
    bad_dates = 0
    # A "tax year N" window on a settle-basis project takes a trade by
    # its settlement date, as the books and Schedule 3 do (S039-18).
    _settle = _settle_basis(root)
    # Income and ROC rows are windowed on their tax date (lib/
    # income_dating: a Canadian trust's distribution or ROC by its
    # record date, a listed US RIC January dividend on Dec 31), the
    # date divs-sum / roc-sum / the .sum use — the row views used the
    # pay date, so their tax-year totals disagreed (audit A2-0326,
    # A2-0641, A2-0642, A2-0655, A2-1109, A2-1125, A2-1127).
    _rules = _view_income_rules(root)
    moved = 0
    for acct in accounts:
        native = _native_tx_file(cache, acct)
        if native is None:
            _view_msg("note", f"no native transaction file for account "
                      f"{acct!r}; skipping it.")
            continue
        data = _load_json_or_die(native)
        # The tax withheld on a payment is dated with it (A2-0396).
        _wh = (_rules.withholding_dates(data.get("transactions", []))
               if _rules is not None else {})
        for tx in data.get("transactions", []):
            if actions is not None and tx.get("action") not in actions:
                continue
            if symbol_filter is not None and not symbol_filter(tx.get("symbol") or ""):
                continue
            d = tx.get("date") or ""
            if not _ISO_DATE_RE.match(d):    # can't place it in the window
                bad_dates += 1
                continue
            if tx.get("action") in _TRADE_ACTIONS:
                _wd = _gains_row_date(tx, keep, _settle)
            elif (_rules is not None and tx.get("action") in
                  ("DIVIDEND", "DIVIDEND_IN_LIEU", "ADJUST")):
                _wd = _rules.row_date(tx) or d
            elif id(tx) in _wh:
                _wd = _wh[id(tx)]
            else:
                _wd = d
            if keep(_wd):
                rows.append((d, tx.get("time") or "", acct, tx))
                if _wd[:4] != d[:4]:
                    moved += 1
    if label == "roc":
        for acct, tx in _dist_adjust_rows(cache, accounts, keep):
            rows.append((tx.get("date") or "", tx.get("time") or "",
                         acct, tx))
        # The same ROC as a book ADJUST and a [[distributions]] entry
        # cuts the ACB twice: the roc-sum warning, here too (A2-1116).
        _warn_dist_double_entry(root, accounts, _rules, keep, label)
    if moved:
        _view_msg("note", f"{moved} income row(s) shown with their pay "
                  f"date belong to this window by their tax date",
                  "A Canadian trust's record date, a listed RIC January "
                  "dividend (`taxjson tax-logic`), as in divs-sum / "
                  "roc-sum.")

    # Chronological, oldest → latest (date, then time), across all accounts.
    rows.sort(key=lambda r: (r[0], r[1], r[2]))
    # A crypto account's DIVIDEND rows are staking rewards — ordinary
    # income, their own total, never under TOTAL DIVIDEND (S023-11).
    _crypto_accts = {n for n, c in (_soft_config(root).get("accounts")
                                    or {}).items()
                     if isinstance(c, dict) and c.get("crypto")}

    if getattr(args, "json", False):
        # Payments in lieu are their own total, as in `sum` and dil-sum
        # (one "dividend" bucket put them under TOTAL DIVIDEND, and the
        # PIL-only `dil` view labelled them dividends — S039-19, S041-07).
        jb: Dict[str, Dict[str, float]] = {"buy": {}, "sell": {},
                                           "dividend": {},
                                           "dividend_in_lieu": {},
                                           "staking": {}}
        for _d, _t, acct, tx in rows:
            cur = tx.get("currency") or "?"
            act = tx.get("action")
            if act in ("BUYSELL", "ASSIGN"):
                q = float(tx.get("quantity") or 0.0)
                amt = _trade_total(tx)
                bucket = "buy" if q > 0 else "sell" if q < 0 else None
                if bucket:
                    jb[bucket][cur] = jb[bucket].get(cur, 0.0) + amt
            elif act in ("DIVIDEND", "DIVIDEND_IN_LIEU"):
                amt = (float(tx.get("gross_amount") or 0.0)
                       or float(tx.get("net_amount") or 0.0))
                _k = ("dividend_in_lieu" if act != "DIVIDEND"
                      else "staking" if acct in _crypto_accts
                      else "dividend")
                jb[_k][cur] = jb[_k].get(cur, 0.0) + amt
        _json_out({"rows": [dict(tx, account=acct)
                            for _d, _t, acct, tx in rows],
                   "totals": {k: v for k, v in jb.items() if v},
                   "bad_dates": bad_dates})
        return

    # A single named account prints pure taxtext (round-trippable); the
    # all-accounts view prefixes each line with the account so the merged
    # chronological list stays legible.
    prefix = len(accounts) != 1
    # The single-account (round-trippable) view writes each line's
    # SETTLEMENT date on a settle-basis project — what a .tt line's one
    # date means there (README "Importing manual cost basis").
    _st = _soft_settings(root)
    settle_dates = (not prefix and _tax_date(_st) == "settle")
    skipped = 0
    out_lines = []
    buys: Dict[str, float] = {}
    sells: Dict[str, float] = {}
    divs: Dict[str, float] = {}
    pils: Dict[str, float] = {}
    stake: Dict[str, float] = {}
    for _d, _t, acct, tx in rows:
        line = _tx_display_line(tx, settle=settle_dates)
        if line is None:
            skipped += 1
            continue
        out_lines.append(f"{acct} {line}" if prefix else line)
        cur = tx.get("currency") or "?"
        act = tx.get("action")
        if act in ("BUYSELL", "ASSIGN"):
            amt = _trade_total(tx)
            q = float(tx.get("quantity") or 0.0)
            if q > 0:
                buys[cur] = buys.get(cur, 0.0) + amt
            elif q < 0:
                sells[cur] = sells.get(cur, 0.0) + amt
        elif act in ("DIVIDEND", "DIVIDEND_IN_LIEU"):
            # Signed: a broker reversal row (negative amount) must net
            # against the original posting rather than inflate the total.
            amt = (float(tx.get("gross_amount") or 0.0)
                   or float(tx.get("net_amount") or 0.0))
            _b = (pils if act != "DIVIDEND"
                  else stake if acct in _crypto_accts else divs)
            _b[cur] = _b.get(cur, 0.0) + amt
    if not out_lines:
        # roc/dil are the views most often legitimately empty — zero
        # bytes at rc 0 was indistinguishable from a mis-typed window
        # (REVIEW #37); every sibling prints an explicit empty state.
        print(f"(no {label} rows in this window)")
        return
    # numeric_right: quantities, per-share rates, and amounts line up
    # on their decimal points, same as the report tables. The rows
    # stay whitespace-tokenized taxtext — extra padding parses
    # identically when pasted into a .tt file.
    for aligned in _align_columns(out_lines, numeric_right=True):
        print(aligned)

    # Per-currency totals footer. Only the categories actually present print,
    # so `dividends` shows just the dividend total, `buysell` the buy/sell
    # totals, and `transactions` all three.
    def _fmt(d):
        return ", ".join(f"{v:,.2f} {c}" for c, v in sorted(d.items()))
    footer = [(lbl, d) for lbl, d in
              (("TOTAL BUY:", buys), ("TOTAL SELL:", sells),
               ("TOTAL DIVIDEND:", divs),
               ("TOTAL DIVIDEND IN LIEU:", pils),
               ("TOTAL STAKING (crypto, ordinary income):", stake)) if d]
    if footer:
        print()
        _w = max(15, max(len(lbl) for lbl, _d in footer))
        for lbl, d in footer:
            if prefix:
                _vprint(f"{lbl:<{_w}} {_fmt(d)}", hang=" " * (_w + 1))
            else:
                # One named account: re-importable taxtext, its bytes
                # never depend on the width (docs/output-style.md).
                print(f"{lbl:<{_w}} {_fmt(d)}")

    if skipped:
        _view_msg("note", f"skipped {skipped} row(s) with no taxtext "
                  f"representation (e.g. OPENING_BALANCE).")
    _warn_bad_dates(bad_dates)


def cmd_transactions(args: argparse.Namespace) -> None:      # `events` view
    _run_tx_view(args, actions=None, label="events")


_BOOK_VALUE_DESC_RE = re.compile(
    r"\bBOOK\s+VALUE:?\s*\$?\s*(\d+(?:,\d+)*(?:\.\d+)?)", re.IGNORECASE)


def _require_books(root: Path, account: Optional[str] = None,
                   also: Tuple[str, ...] = ()) -> None:
    """Refuse a books view over a project with no books: never run
    (no work/), a run that died before any book was written, or an
    account with no book. spinoffs, splits, transfers, edge-cases and
    fees-sum printed an empty report ('No spin-offs', nine 'None.'
    sections) at rc 0 where their twins say 'run `taxjson run` first'
    (re-audit A2-0797, A2-1395)."""
    cache = root / "work"
    if not cache.is_dir():
        _die("no work/ — run `taxjson run` first.")
    names = set(_discover_tx_accounts(cache)) | {
        p.name[:-len("_base.json")] for p in cache.glob("*_base.json")
        if not p.name.startswith(".")
        and not p.name.endswith("_raw_base.json")
        and p.name != "sheltered_base.json"}
    # `also`: the stage files a view reads besides the books (parsed
    # per-broker JSONs for fees-sum, transfer sidecars for transfers).
    extra = any(not p.name.startswith(".")
                for g in also for p in cache.glob(g))
    if account:
        if account not in names:
            _die(f"no books for account {account!r} in work/ — run "
                 f"`taxjson run` first (an account with no inputs has no "
                 f"books).")
    elif not names and not extra:
        _die("no books in work/ — run `taxjson run` first (or the last "
             "run stopped before writing any; see its error).")


def cmd_transfers_view(args: argparse.Namespace) -> None:
    """`taxjson transfers`: the custody-evidence view. TRANSFER rows
    are deliberately NOT tax events — a taxable book's basis comes from
    its buy/sell history, so the parse stage keeps them OUT of the
    books (in a sidecar) and `events` stays buysell-only. But a depot
    flip, listing journal, broker migration, or crypto withdrawal/send
    is exactly what explains a confusing position — or an undeclared
    FMV disposition — later; this view shows that evidence: sidecar
    rows (taxable accounts) plus in-book TRANSFERs (sheltered accounts
    with `transfers = true`)."""
    import json
    root = Path(args.dir).resolve()
    cache = root / "work"
    want = (args.account or "").strip() or None
    cfg = _soft_config(root)
    if not cfg:
        # With no config the sheltered accounts' in-book rows were left
        # out and the view said "the broker reported none" at rc 0
        # (re-audit A2-0717); the other views refuse.
        _die("no taxjson.toml in the project folder",
             "The accounts (and their in-book TRANSFER rows) are unknown; "
             "run from the project root.")
    if want and cfg and want not in (cfg.get("accounts") or {}):
        # A typo read "no transfer rows ... the broker reported none"
        # with rc 0, as if the account existed (S039-20).
        _die(f"no [accounts.{want}] in taxjson.toml — check the name.")
    _require_books(root, also=("*_transfers.json",))

    def _fee(t: Dict[str, Any]) -> float:
        # A custody move's fee (a crypto withdrawal's network fee) is
        # in the sidecar; the view dropped it (S039-21).
        return float(t.get("fee") or 0) + float(t.get("commission") or 0)

    _COIN_FEE_RE = re.compile(r"\(fee ([0-9.eE+-]+) ([A-Za-z0-9.]+)\)")

    def _coin_fee(t: Dict[str, Any]) -> Tuple[float, str]:
        # A fee paid IN COINS (Kraken: fee_qty/fee_currency; never the
        # money `fee` field, S061-17), else the "(fee 0.05 ABC)" the
        # description of a sidecar from an older parse carries — the
        # FEE column was empty on every real withdrawal (A2-0663).
        try:
            q = float(t.get("fee_qty") or 0)
        except (TypeError, ValueError):
            q = 0.0
        if q:
            return q, str(t.get("fee_currency") or "")
        m = _COIN_FEE_RE.search(str(t.get("description") or ""))
        if m:
            try:
                return float(m.group(1)), m.group(2)
            except ValueError:
                pass
        return 0.0, ""

    rows: List[Dict[str, Any]] = []
    for p in sorted(cache.glob("*_transfers.json")):
        try:
            doc = _read_work_doc(p)
            if not isinstance(doc.get("metadata") or {}, dict):
                raise ValueError('"metadata" must be a JSON object')
        except (OSError, ValueError) as e:
            _view_msg("warning", f"could not read {p.name}: {e}",
                      "Its transfer rows are not shown.")
            continue
        if (doc.get("metadata") or {}).get("kind") != "transfer_sidecar":
            continue
        acct = (doc.get("metadata") or {}).get("account") or ""
        for t in doc.get("transactions") or []:
            rows.append({"date": t.get("date") or "",
                         "account": t.get("account") or acct,
                         "symbol": t.get("symbol") or "",
                         "quantity": float(t.get("quantity") or 0),
                         "type": t.get("description") or "",
                         # RBC ships Value 0 on in-kind transfers; its
                         # "BOOK VALUE nnn" rides along as evidence.
                         "value": float(t.get("net_amount")
                                        or t.get("book_value") or 0),
                         "fee": _fee(t),
                         "fee_qty": _coin_fee(t)[0],
                         "fee_currency": _coin_fee(t)[1],
                         "currency": t.get("currency") or "",
                         "where": "sidecar"})
    _no_inputs = _accounts_skipped_for_no_inputs(root)
    for name in (cfg.get("accounts") or {}):
        p = cache / f"{name}_base.json"
        if not p.exists():
            # Missing says so like unreadable does (re-audit A2-1232).
            if name not in _no_inputs and _has_inputs(root, name):
                _view_msg("warning", f"no work/{p.name}: {name}'s "
                          f"in-book TRANSFER rows are not shown",
                          "Run `taxjson run` to build it.")
            continue
        try:
            doc = _read_work_doc(p)
        except (OSError, ValueError) as e:
            # Same warning as the sidecar loop: the account's in-book
            # rows vanished with no word (S039-22).
            _view_msg("warning", f"could not read {p.name}: {e}",
                      "Its in-book TRANSFER rows are not shown.")
            continue
        for t in (doc.get("transactions") if isinstance(doc, dict)
                  else doc) or []:
            if t.get("action") != "TRANSFER":
                continue
            # The book row lost the parser's book_value evidence (not a
            # transaction field); RBC's description still carries it
            # ("... BOOK VALUE 13579.24") — shown as the sidecar row is
            # (audit S027-06).
            _value = float(t.get("net_amount") or 0)
            if not _value:
                _bv = _BOOK_VALUE_DESC_RE.search(t.get("description") or "")
                if _bv:
                    from taxjson.lib.brokerages.base import desc_number
                    _value = desc_number(_bv.group(1), strict=False) or 0.0
            rows.append({"date": t.get("date") or "",
                         "account": t.get("account") or name,
                         "symbol": t.get("symbol") or "",
                         "quantity": float(t.get("quantity") or 0),
                         "type": t.get("description") or "",
                         "value": _value,
                         "fee": _fee(t),
                         "fee_qty": _coin_fee(t)[0],
                         "fee_currency": _coin_fee(t)[1],
                         "currency": t.get("currency") or "",
                         "where": "book"})
    if want:
        rows = [r for r in rows if r["account"] == want]
    rows.sort(key=lambda r: (r["date"], r["account"], r["symbol"]))
    # What the books did with each transfer-IN of a taxable account
    # (lib/transfer_in): your own move (its out leg is yours too), booked
    # at the broker's stated book value, covered by your .tt purchase,
    # or NO COST — shares from outside the books with no cost.
    _status = {"book_value": "book value", "covered": ".tt covers",
               "missing_history": "missing history",
               "no_cost": "NO COST"}
    try:
        _arr: Dict[Tuple[str, str, str], List[str]] = {}
        for a in transfer_arrivals(root, cache, cfg.get("accounts")):
            _arr.setdefault((a.account, a.symbol, a.date), []).append(
                _status[a.status])
    except Exception:                               # noqa: BLE001
        _arr = {}
    _tax_eq = {n for n, c in (cfg.get("accounts") or {}).items()
               if isinstance(c, dict) and c.get("type") == "taxable"
               and not c.get("crypto") and not c.get("transfers")}
    # The legs of the in-kind moves to and from your registered
    # accounts (lib/in_kind, work/in_kind.json).
    _ik: Dict[Tuple[str, str, str, float], str] = {}
    try:
        import json as _json
        _ikdoc = _json.loads((cache / IN_KIND_FILE).read_text(
            encoding="utf-8"))
        for _m in _ikdoc.get("moves") or []:
            _lbl = (f"in-kind {_m.get('kind')}"
                    + ("" if _m.get("booked") else
                       " (ambiguous, NOT booked)"
                       if _m.get("problem") == "ambiguous" else
                       " (NOT booked)"))
            for _leg in ([_m.get("taxable_leg"), _m.get("registered_leg")]
                         + list(_m.get("registered_legs") or [])):
                if isinstance(_leg, list) and len(_leg) == 4:
                    _ik[(str(_leg[0]), str(_leg[1]), str(_leg[2]),
                         round(float(_leg[3]), 8))] = _lbl
    except (OSError, ValueError, TypeError, AttributeError):
        pass
    for r in rows:
        r["arrival"] = "-"
        _lbl = _ik.get((r["account"], r["symbol"], r["date"][:10],
                        round(float(r["quantity"]), 8)))
        if _lbl:
            r["arrival"] = _lbl
        elif (r["where"] == "sidecar" and r["quantity"] > 0
                and r["account"] in _tax_eq):
            got = _arr.get((r["account"], r["symbol"], r["date"][:10]))
            r["arrival"] = got.pop(0) if got else "own move"
    # Questrade internal codes the run booked under a ticker it inferred
    # from the other exports (lib/symbol_codes), and those it could not.
    from taxjson.lib.symbol_codes import SUFFIX as _SC_SUFFIX, read_state
    codes: List[Dict[str, Any]] = []
    for name in sorted(cfg.get("accounts") or {}):
        if want and name != want:
            continue
        st = read_state(cache / f"{name}{_SC_SUFFIX}")
        for code, r in sorted((st.get("resolved") or {}).items()):
            codes.append({"account": name, "code": code,
                          "symbol": r.get("symbol") or "",
                          "how": r.get("how") or "",
                          "evidence": r.get("evidence") or ""})
        for code, r in sorted((st.get("unresolved") or {}).items()):
            codes.append({"account": name, "code": code, "symbol": "",
                          "how": "unresolved",
                          "evidence": r.get("detail") or
                          "no transfer or name in the project identifies "
                          "it"})
        # A code a ticker.map rule names: booked by that rule, never
        # inferred (lib/symbol_codes).
        for code, r in sorted((st.get("mapped") or {}).items()):
            codes.append({"account": name, "code": code, "symbol": "",
                          "how": "ticker.map",
                          "evidence": "a ticker.map rule names it; booked "
                                      "as that rule says"})
    if getattr(args, "json", False):
        _json_out({"transfers": rows, "count": len(rows),
                   "symbol_codes": codes})
        return
    from taxjson.lib.out import Doc

    def _codes_section(doc) -> None:
        if not codes:
            return
        doc.section("SYMBOL CODES — Questrade internal codes")
        doc.para("Booked under the ticker inferred from your exports "
                 "(the account's own rows of the same description, "
                 "another account's transfer or name, or a currency "
                 "journal of the account; a ticker.map GLOBAL line for "
                 "the code "
                 "overrides it); an unresolved code stays its own "
                 "security until ticker.map maps it.")
        doc.items([f"{c['account']}: {c['code']} → {c['symbol']} "
                   f"({c['evidence']})" if c["symbol"] else
                   f"{c['account']}: {c['code']} → ticker.map rule"
                   if c["how"] == "ticker.map" else
                   f"{c['account']}: {c['code']} UNRESOLVED "
                   f"({c['evidence']})" for c in codes])
    doc = Doc("CUSTODY TRANSFERS — evidence, not tax events")
    doc.para("Basis comes from the buy and sell history. WHERE: sidecar = "
             "kept out of the books; book = a sheltered account's "
             "transfers, kept in.")
    doc.blank()
    if not rows:
        doc.para("No transfer rows found"
                 + (f" for account {want!r}" if want else "")
                 + " — re-run `taxjson run` after enabling the sidecar, "
                   "or the broker reported none.")
        _codes_section(doc)
        doc.print()
        return
    body = []
    for r in rows:
        # Type column: the transfer KIND (InterDepot/Internal/ATON…);
        # some brokers put a whole sentence here — cap it, the --json
        # view carries the full text.
        _ty = (r["type"] or "-").replace(" ", "_")
        if len(_ty) > 24:
            _ty = _ty[:21] + "..."
        body.append([
            r["date"], r["account"], r["symbol"],
            fmt_qty(r["quantity"]), _ty,
            fmt_money(r["value"]),
            (f"{r['fee']:g}" if r["fee"]
             else (f"{r['fee_qty']:g}_{r['fee_currency']}".rstrip("_")
                   if r["fee_qty"] else "-")),
            r["currency"], r["where"], r["arrival"].replace(" ", "_")])
    # Too wide: the fee, the sidecar/book column, then the kind go first.
    doc.table(["DATE", "ACCOUNT", "SYMBOL", "QTY", "TYPE", "VALUE", "FEE",
               "CUR", "WHERE", "IN_BOOKS"], body, drop=(6, 8, 4),
              key=(0, 1, 2))
    doc.blank().para(f"{len(rows)} transfer row(s).")
    if any(r["arrival"] != "-" for r in rows):
        doc.section("IN_BOOKS — a taxable account's transfer-in")
        doc.items([
            "own_move: your own shares moving (a transfer-out of yours "
            "cancels it).",
            "book_value: from outside your books, booked at the book "
            "value the broker states on the row.",
            ".tt_covers: your .tt purchase covers it.",
            "missing_history: missing_history.json lists it (cost "
            "unknown, reported by hand).",
            "NO_COST: from outside your books with no cost — add the "
            "original purchase to a .tt file (docs/getting-started.md, "
            "step 5c).",
            "in-kind_contribution / in-kind_withdrawal: a move between a "
            "taxable and a registered account, booked in the taxable "
            "account as a sale / purchase at fair market value (`taxjson "
            "run` lists each)."])
    _codes_section(doc)
    doc.print()


def _cannot_write_decisions(path, e: OSError) -> str:
    """One line for a sends.json that cannot be saved (a read-only
    inputs/<acct>/, a full disk): it was a PermissionError traceback on
    sends.json.part (re-audit A2-1416)."""
    return (f"cannot write {path}: {e.strerror or e} — nothing was "
            f"saved; make inputs/{Path(path).parent.name}/ writable and "
            f"re-run.")


def cmd_crypto_sends(args: argparse.Namespace) -> None:
    """`taxjson crypto-sends`: every outgoing crypto transfer that did
    not arrive in another of your crypto accounts, with your decision (self /
    gift / payment), its fair value and the ready .tt line; --set
    records a decision, --write regenerates inputs/<acct>/crypto_sends.tt."""
    from taxjson.lib import crypto_sends as CS
    root = Path(args.dir).resolve()
    cfg = load_config(root)
    accts = CS.crypto_accounts(cfg)
    if not accts:
        _die("no crypto account in taxjson.toml",
             "A crypto account is an [accounts.X] with `crypto = true`.")
    acct = (args.account or "").strip() or None
    if acct and acct not in accts:
        _die(f"{acct!r} is not a crypto account — crypto accounts: "
             f"{', '.join(accts)}.")
    sets = list(getattr(args, "set", None) or [])
    unsets = list(getattr(args, "unset", None) or [])
    if (sets or unsets or args.write) and not acct:
        if len(accts) != 1:
            _die("--set/--unset/--write need an account",
                 f"`taxjson crypto-sends <{'|'.join(accts)}> --set ID="
                 f"{'|'.join(_send_decisions(_country(cfg.get('settings'))))}`")
        acct = accts[0]
    if (args.note is not None or args.price is not None
            or getattr(args, "unpair", False)) and not sets:
        _die("--note/--price/--unpair only apply with --set ID=DECISION.")
    if args.json and (sets or unsets or args.write):
        _die("--json applies to the listing only.")
    if sets and unsets:
        _die("--set and --unset go in separate commands.")
    cache = root / "work"
    if not any((cache / f"{a}_{b}_transfers.json").exists()
               for a in accts for b in ("kraken", "coinbase")):
        _die("no crypto transfer evidence in work/",
             "Run `taxjson run` first (the parse keeps withdrawals/sends "
             "in work/<acct>_<exchange>_transfers.json).")
    if unsets:
        # Removing a saved decision needs no current evidence (A2-1163).
        from taxjson.lib.crypto_sends import MANIFEST_NAME as _MN
        _man = root / "inputs" / acct / _MN
        try:
            for sid in unsets:
                sid = sid.strip()
                if not CS.clear_decision(_man, sid):
                    _die(f"no saved decision for {sid!r} in "
                         f"inputs/{acct}/{_MN}.")
                print(f"removed: {sid} (undecided again — `taxjson run` "
                      f"asks, or `--set {sid}=...`)")
        except ValueError as e:
            _die(str(e))
        except OSError as e:
            _die_input(_cannot_write_decisions(_man, e))
        print(f"Regenerate the .tt lines: `taxjson crypto-sends {acct} "
              f"--write` (or just `taxjson run`).")
        return
    files = _crypto_broker_files(root, cfg)
    # Evidence parsed before an export changed: a send that has since
    # arrived would still be listed as unmatched, and a decision saved
    # for it is then dropped by the next run (re-audit A2-1010).
    stale = CS.stale_evidence(cache, files, skip=_transfers_accounts(cfg))
    if stale and (sets or args.write):
        _die(f"the transfer evidence is not current for "
             f"{'; '.join(stale)}",
             "Run `taxjson run` first, then decide (a send may have "
             "arrived since).")
    if stale:
        _view_msg("warning", f"the transfer evidence is not current for "
                  f"{'; '.join(stale)}",
                  "Run `taxjson run` before deciding (a send may have "
                  "arrived since).")
    try:
        if sets:
            light = CS.build_report(root, cfg, files, None, want=acct,
                                    with_pool=False, exports_only=True)
            adoc = light["accounts"][acct]
            by_id = {s["id"]: s for s in adoc["sends"]}
            fee_ids = {f["id"]: f for f in adoc["network_fees"]}
            for item in sets:
                if "=" not in item:
                    _die(f"--set expects ID=DECISION, got {item!r}.")
                sid, dec = (x.strip() for x in item.rsplit("=", 1))
                dec = dec.lower()
                if sid in fee_ids:
                    # The network fee hidden in a send that arrived
                    # short: a sale at fair value; the owner can only
                    # price it (re-audit A2-0240).
                    if dec != CS.FEE_DECISION or args.price is None:
                        _die(f"{sid} is the network fee hidden in a send "
                             f"that arrived short — a sale at fair value",
                             f"Give its price: `--set {sid}="
                             f"{CS.FEE_DECISION} --price P`.")
                    try:
                        CS.record_decision(Path(adoc["manifest"]), sid, dec,
                                           note=args.note, price=args.price,
                                           summary=fee_ids[sid]["summary"])
                    except OSError as e:
                        _die_input(_cannot_write_decisions(adoc["manifest"], e))
                    print(f"saved: {sid} priced at {args.price:g} "
                          f"{light['base_currency']} per "
                          f"{fee_ids[sid]['symbol']}  "
                          f"(inputs/{acct}/{CS.MANIFEST_NAME})")
                    continue
                if dec not in CS.DECISIONS:
                    _die(f"decision {dec!r} for {sid} — expected one of "
                         f"{', '.join(_send_decisions(_country(cfg.get('settings'))))}.")
                _gift_no = command_country_problem(
                    "crypto-sends", _country(cfg.get("settings")), dec)
                if _gift_no:
                    # lib/country.COMMAND_COUNTRY["crypto-sends:gift"]
                    _die(f"{_gift_no}",
                         "A US donor's gift is not a sale (the recipient "
                         "takes over your basis) — record it as `self` (no "
                         "tax event) or, if you were paid, `payment`.")
                summary = by_id[sid]["summary"] if sid in by_id else ""
                unpair = None
                if sid not in by_id:
                    paired = CS.matched_send(root, cfg, acct, sid, files)
                    if paired is None:
                        _die(f"no send {sid!r} in account {acct!r}",
                             f"`taxjson crypto-sends {acct}` lists the "
                             f"ids.")
                    if dec in CS.DISPOSING and not args.unpair:
                        # The pairing calls it your own move: a gift or
                        # payment needs the owner to say the arrival is
                        # unrelated (re-audit A2-0004).
                        _die(f"{sid} is paired with an arrival — booked as "
                             f"your own move",
                             f"The arrival: {paired}.",
                             f"If that arrival is unrelated and the coins "
                             f"left your ownership: `--set {sid}={dec} "
                             f"--unpair`.")
                    summary = paired.split(" arrived as ")[0]
                if args.unpair:
                    if dec not in CS.DISPOSING:
                        _die("--unpair applies to a gift or payment.")
                    unpair = True
                try:
                    CS.record_decision(Path(adoc["manifest"]), sid, dec,
                                       note=args.note, price=args.price,
                                       summary=summary, unpair=unpair)
                except ValueError as e:
                    _die(str(e))
                except OSError as e:
                    _die_input(_cannot_write_decisions(adoc["manifest"], e))
                print(f"saved: {sid} = {dec}"
                      f"{' (unpaired)' if unpair else ''}  "
                      f"(inputs/{acct}/{CS.MANIFEST_NAME})")
            if not args.write:
                print(f"Regenerate the .tt lines: `taxjson crypto-sends "
                      f"{acct} --write` (or just `taxjson run`).")
                return
        _price_fn = CS.yahoo_usd_price(root)
        report = CS.build_report(root, cfg, files, _price_fn, want=acct,
                                 exports_only=True)
        for w in getattr(_price_fn, "attention", ()):
            _view_msg("warning", f"crypto id: {w}")
        if args.write:
            status, dups = _crypto_sends_tt(root, acct, report)
            n = len(CS.tt_entries(report["accounts"][acct])[0])
            print(f"inputs/{acct}/{CS.TT_NAME}: {status} "
                  f"({n} BUYSELL line(s)); `taxjson run` books it.")
            for w in _dup_warning(acct, dups):
                _view_msg("warning", w)
            return
    except ValueError as e:
        _die(str(e))
    if args.json:
        _json_out(report)
        return
    _print_crypto_sends(root, report)


def _print_crypto_sends(root: Path, report: Dict[str, Any]) -> None:
    """The crypto-sends listing in the house layout (docs/output-style.md):
    a title, one section per crypto account, each send's id and decision
    with its facts aligned under it (the ready .tt line never wrapped),
    and a last line saying what to do."""
    from taxjson.lib import crypto_sends as CS
    from taxjson.lib.out import Doc, Verbatim
    base = report["base_currency"]
    _usa = _country(_soft_settings(root)) == "usa"
    doc = Doc("CRYPTO SENDS — outgoing transfers that did not arrive in "
              "another of your crypto accounts")
    if _usa:
        # A US donor's gift is not a disposition (the recipient takes
        # over the basis); `gift` is refused (COMMAND_COUNTRY).
        doc.para("A move to your own wallet is not a sale (self); a "
                 "payment is a sale at fair market value. A gift is not a "
                 "sale for a US donor: record it as self.")
    else:
        doc.para("A move to your own wallet is not a sale (self); a gift "
                 "or a payment is a disposition at fair market value.")
    fx_by_year: Dict[str, float] = {}
    last = None
    for acct, adoc in report["accounts"].items():
        sends = adoc["sends"]
        doc.section(f"{acct} — {len(sends)} unmatched send(s), "
                    f"{adoc['undecided']} undecided")
        doc.para(f"{adoc['matched']} matched to an arrival (self-custody "
                 f"moves, `taxjson transfers`).", indent="  ")
        _short = adoc.get("network_fees") or []
        if _short:
            # R1-26: the coins lost in transit paid the network fee — a
            # disposition at fair value, written to crypto_sends.tt.
            doc.para(f"{len(_short)} matched send(s) arrived SHORT — the "
                     f"difference is the network fee paid in the coin, a "
                     f"sale at fair value booked in {CS.TT_NAME}:",
                     indent="  ")
            for _s in _short:
                _fv = _s["fair_value"]
                _val = (f"{_fv['value']:,.2f} {base}  [{_fv['source']}]"
                        if _fv else "UNPRICED (lookup failed or offline)")
                doc.item(f"{_s['id']}: {_s['summary']}, "
                         f"{CS.fmt_qty(_s['quantity'])} {_s['symbol']} "
                         f"short = {_val}", indent="  ")
        for e in sends:
            dec = (e["decision"] or "PENDING").upper()
            ref = f"   ref {e['ref']}" if e["ref"] else ""
            unp = "   (unpaired by you)" if e.get("unpaired") else ""
            doc.blank().line(f"  {e['id']}   {dec}{ref}{unp}")
            fee = ("" if not e["fee_booked"] else
                   f" (plus a {CS.fmt_qty(e['fee_booked'])} {e['symbol']} "
                   f"withdrawal fee — cash, not a sale)" if e["stable"] else
                   f" ({CS.fmt_qty(e['fee_booked'])} {e['symbol']} network "
                   f"fee already booked from the ledger)")
            pairs = [("send", f"{e['summary']}{fee}")]
            fv = e["fair_value"]
            if fv:
                pairs.append(("fair value",
                              f"{CS.fmt_price(fv['price'])} {base}/"
                              f"{e['symbol']} = {fv['value']:,.2f} {base}  "
                              f"[{fv['source']}]"))
            else:
                pairs.append(("fair value",
                              f"UNPRICED (lookup failed or offline) — "
                              f"`--set {e['id']}=... --price P` gives it"))
            if e["stable"]:
                fx = e["fx"]
                if base == "USD":
                    pairs.append(("stablecoin", "US-dollar cash: no sale "
                                  "line and no currency gain in a USD "
                                  "project"))
                elif fx:
                    tag = ("FX gain" if e["decision"] in CS.DISPOSING
                           else "FX gain if gift/payment")
                    pairs.append(("stablecoin", "US-dollar cash in the "
                                  "books: no sale line"))
                    pairs.append((tag, f"value {fx['value']:,.2f} - ACB "
                                  f"{fx['acb']:,.2f} (USD pool average "
                                  f"cost) = {fx['gain']:+,.2f} {base}"))
                    if fx.get("superficial"):
                        pairs.append(("superficial", "that loss is likely "
                                      "SUPERFICIAL (s.54): USD/stablecoins "
                                      "acquired within 30 days and still "
                                      "held — denied"))
                    if fx.get("overdrawn"):
                        pairs.append(("pool", "the pool was short: the "
                                      "ledgers do not show where part of "
                                      "this USD came from"))
                    if e["decision"] in CS.DISPOSING:
                        y = e["date"][:4]
                        allowed = 0.0 if (fx["gain"] < 0 and
                                          fx.get("superficial")) \
                            else fx["gain"]
                        fx_by_year[y] = fx_by_year.get(y, 0.0) + allowed
                else:
                    pairs.append(("stablecoin", "US-dollar cash in the "
                                  "books: no sale line (FX gain "
                                  "unavailable: no USD rate)"))
            elif e["tt"]:
                lead = ".tt" if e["decision"] in CS.DISPOSING else \
                    f".tt if {_disposing_word(report['country'])}"
                pairs.append((lead, Verbatim(e["tt"])))
            if e["note"]:
                pairs.append(("your note", e["note"]))
            if e.get("refused"):
                pairs.append(("REFUSED", e["refused"]))
            doc.kv(pairs, indent="    ")
        entries, unpriced = CS.tt_entries(adoc)
        tt = Path(adoc["tt_file"])
        want = CS.render_tt(acct, entries, report["country"])
        have = CS.read_tt(tt)              # a BOM re-save (A2-1405)
        doc.blank()
        if unpriced:
            doc.message("warning", f"NOT BOOKED — no fair value for "
                        f"{', '.join(e['id'] for e in unpriced)}",
                        details=[f"Give it with `--set ID="
                                 f"{_disposing_word(report['country']).replace('/', '|')}"
                                 f" --price P` (a `-fee` id: `--set "
                                 f"ID=fee --price P`)."])
        if want == have:
            last = (f"inputs/{acct}/{CS.TT_NAME}: up to date "
                    f"({len(entries)} line(s))." if have else
                    f"No {_disposing_word(report['country'])} or network "
                    f"fee needs a sale line.")
        else:
            last = (f"inputs/{acct}/{CS.TT_NAME}: OUT OF DATE — run "
                    f"`taxjson crypto-sends {acct} --write` (or `taxjson "
                    f"run`).")
        doc.para(last)
        for w in _dup_warning(acct, CS.duplicate_lines(
                root / "inputs" / acct, entries)):
            doc.message("warning", w)
        for w in _crypto_sends_problems(acct, adoc):
            doc.message("warning", w)
        for sid in adoc["orphans"]:
            doc.message("note", f"sends.json has a decision for {sid}, "
                        f"which is no longer a send in the exports",
                        details=["Inputs or local_timezone changed? It "
                                 "is ignored."])
        if adoc["undecided"]:
            last = (f"Decide: taxjson crypto-sends {acct} --set "
                    f"ID={'self|payment' if _usa else 'self|gift|payment'}"
                    f" [--note TEXT]   (then --write)")
            doc.line(last)
    if fx_by_year:
        doc.section("STABLECOIN GIFTS AND PAYMENTS — currency gain")
        doc.kv([(y, f"{g:+,.2f} {base}")
                for y, g in sorted(fx_by_year.items())], indent="  ")
        # fx-cash has no input for it (re-audit A2-0591): the amount is
        # added by hand to the year's s.39(1.1) currency total.
        doc.para("Superficial losses are excluded. Stablecoins are "
                 "US-dollar cash in these books, so this is a "
                 "foreign-currency gain: ITA s.39(1.1) taxes only the "
                 "year's NET currency gain beyond $200. It is NOT in any "
                 "taxjson figure (`taxjson fx-cash` does not read it): add "
                 "it by hand to the year's net foreign-exchange gain or "
                 "loss (the fx-cash net before the $200) and apply the "
                 "$200 to the total.", indent="  ")
    pool = report.get("pool")
    if pool and pool.get("overdrafts"):
        doc.blank()
        doc.message("note", f"the USD/stablecoin pool went short "
                    f"{pool['overdrafts']} time(s)",
                    details=["The ledgers do not show where that USD came "
                             "from (an earlier year's export?); the "
                             "shortfall is valued at the day's rate (no "
                             "gain)."])
    doc.print()


